package hcl

import (
	"fmt"
	"unicode/utf8"
)

// TokenType identifies a lexical token kind.
type TokenType rune

const (
	TokenOBrace          TokenType = '{'
	TokenCBrace          TokenType = '}'
	TokenOBrack          TokenType = '['
	TokenCBrack          TokenType = ']'
	TokenOParen          TokenType = '('
	TokenCParen          TokenType = ')'
	TokenOQuote          TokenType = '«'
	TokenCQuote          TokenType = '»'
	TokenOHeredoc        TokenType = 'H'
	TokenCHeredoc        TokenType = 'h'
	TokenStar            TokenType = '*'
	TokenSlash           TokenType = '/'
	TokenPlus            TokenType = '+'
	TokenMinus           TokenType = '-'
	TokenPercent         TokenType = '%'
	TokenEqual           TokenType = '='
	TokenEqualOp         TokenType = '≔'
	TokenNotEqual        TokenType = '≠'
	TokenLessThan        TokenType = '<'
	TokenLessThanEq      TokenType = '≤'
	TokenGreaterThan     TokenType = '>'
	TokenGreaterThanEq   TokenType = '≥'
	TokenAnd             TokenType = '∧'
	TokenOr              TokenType = '∨'
	TokenBang            TokenType = '!'
	TokenDot             TokenType = '.'
	TokenComma           TokenType = ','
	TokenDoubleColon     TokenType = '⸬'
	TokenEllipsis        TokenType = '…'
	TokenFatArrow        TokenType = '⇒'
	TokenQuestion        TokenType = '?'
	TokenColon           TokenType = ':'
	TokenTemplateInterp  TokenType = '∫'
	TokenTemplateControl TokenType = 'λ'
	TokenTemplateSeqEnd  TokenType = '∎'
	TokenQuotedLit       TokenType = 'Q'
	TokenStringLit       TokenType = 'S'
	TokenNumberLit       TokenType = 'N'
	TokenIdent           TokenType = 'I'
	TokenComment         TokenType = 'C'
	TokenNewline         TokenType = '\n'
	TokenEOF             TokenType = '␄'
	TokenBitwiseAnd      TokenType = '&'
	TokenBitwiseOr       TokenType = '|'
	TokenBitwiseNot      TokenType = '~'
	TokenBitwiseXor      TokenType = '^'
	TokenStarStar        TokenType = '➚'
	TokenApostrophe      TokenType = '\''
	TokenBacktick        TokenType = '`'
	TokenSemicolon       TokenType = ';'
	TokenTabs            TokenType = '␉'
	TokenInvalid         TokenType = '�'
	TokenBadUTF8         TokenType = '💩'
	TokenQuotedNewline   TokenType = '␤'
	TokenNil             TokenType = '\x00'
)

// Pos is a position in a source file.
type Pos struct {
	Line   int
	Column int
	Byte   int
}

// Range is a range in a source file.
type Range struct {
	Filename   string
	Start, End Pos
}

func (r Range) String() string {
	if r.Start.Line == r.End.Line {
		return fmt.Sprintf("%s:%d,%d-%d", r.Filename, r.Start.Line, r.Start.Column, r.End.Column)
	}
	return fmt.Sprintf("%s:%d,%d-%d,%d", r.Filename, r.Start.Line, r.Start.Column, r.End.Line, r.End.Column)
}

// Ptr returns a pointer to a copy of the range.
func (r Range) Ptr() *Range { return &r }

// RangeBetween returns a range spanning from the start of a to the end of b.
func RangeBetween(a, b Range) Range {
	start, end := a.Start, b.End
	if b.Start.Byte < start.Byte {
		start = b.Start
	}
	if a.End.Byte > end.Byte {
		end = a.End
	}
	return Range{Filename: a.Filename, Start: start, End: end}
}

// RangeOver returns the smallest range covering both.
func RangeOver(a, b Range) Range {
	start, end := a.Start, a.End
	if b.Start.Byte < start.Byte {
		start = b.Start
	}
	if b.End.Byte > end.Byte {
		end = b.End
	}
	return Range{Filename: a.Filename, Start: start, End: end}
}

// Token is a single lexical token.
type Token struct {
	Type  TokenType
	Bytes []byte
	Range Range
}

// Diagnostic is an HCL error.
type Diagnostic struct {
	Summary string
	Detail  string
	Subject *Range
}

func (d *Diagnostic) Error() string {
	subj := "<nil>"
	if d.Subject != nil {
		subj = d.Subject.String()
	}
	return fmt.Sprintf("%s: %s; %s", subj, d.Summary, d.Detail)
}

// Diagnostics is a list of diagnostics.
type Diagnostics []*Diagnostic

func (d Diagnostics) Error() string {
	switch len(d) {
	case 0:
		return "no diagnostics"
	case 1:
		return d[0].Error()
	default:
		return fmt.Sprintf("%s, and %d other diagnostic(s)", d[0].Error(), len(d)-1)
	}
}

// HasErrors reports whether there are any diagnostics.
func (d Diagnostics) HasErrors() bool { return len(d) > 0 }

// Err returns the diagnostics as error or nil.
func (d Diagnostics) Err() error {
	if len(d) == 0 {
		return nil
	}
	return d
}

func runeCount(b []byte) int { return utf8.RuneCount(b) }
EOF
echo ok"}

