{"command":"cd /workspace/internal/hcl && cat > scanner.go <<'EOF'
package hcl

import (
	"bytes"
	"unicode"
	"unicode/utf8"
)

type scanMode int

const (
	modeMain scanMode = iota
	modeString
	modeHeredoc
)

type heredocInProgress struct {
	Marker      []byte
	StartOfLine bool
}

type rawTok struct {
	typ        TokenType
	start, end int
}

type scanner struct {
	data      []byte
	p         int
	toks      []rawTok
	modes     []scanMode
	braces    int
	retBraces []int
	heredocs  []heredocInProgress
}

func isIDStart(r rune) bool {
	return unicode.IsLetter(r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Other_ID_Start, r)
}

func isIDContinue(r rune) bool {
	return isIDStart(r) || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Mc, r) || unicode.Is(unicode.Nd, r) || unicode.Is(unicode.Pc, r) || unicode.Is(unicode.Other_ID_Continue, r)
}

func (s *scanner) emit(t TokenType, start, end int) {
	s.toks = append(s.toks, rawTok{t, start, end})
}

func (s *scanner) mode() scanMode {
	if len(s.modes) == 0 {
		return modeMain
	}
	return s.modes[len(s.modes)-1]
}

func (s *scanner) push(m scanMode) { s.modes = append(s.modes, m) }
func (s *scanner) pop() {
	if len(s.modes) > 0 {
		s.modes = s.modes[:len(s.modes)-1]
	}
}

// identLen returns length of identifier at position i, or 0.
func identLen(data []byte, i int) int {
	r, sz := utf8.DecodeRune(data[i:])
	if r == utf8.RuneError && sz <= 1 {
		return 0
	}
	if !(isIDStart(r) || r == '_') {
		return 0
	}
	j := i + sz
	for j < len(data) {
		r, sz = utf8.DecodeRune(data[j:])
		if r == utf8.RuneError && sz <= 1 {
			break
		}
		if isIDContinue(r) || r == '-' || r == '_' {
			j += sz
			continue
		}
		break
	}
	return j - i
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func numberLen(data []byte, i int) int {
	if !isDigit(data[i]) {
		return 0
	}
	j := i + 1
	for j < len(data) {
		c := data[j]
		if isDigit(c) || c == '.' {
			j++
			continue
		}
		if c == 'e' || c == 'E' {
			k := j + 1
			if k < len(data) && (data[k] == '+' || data[k] == '-') {
				k++
			}
			if k < len(data) && isDigit(data[k]) {
				j = k + 1
				continue
			}
		}
		break
	}
	for j > i+1 && data[j-1] == '.' {
		j--
	}
	return j - i
}

func (s *scanner) beginInterp(t TokenType, start, end int) {
	s.emit(t, start, end)
	s.braces++
	s.retBraces = append(s.retBraces, s.braces)
	if len(s.heredocs) > 0 {
		s.heredocs[len(s.heredocs)-1].StartOfLine = false
	}
	s.push(modeMain)
}

func (s *scanner) templateIntro(i int) (TokenType, int) {
	d := s.data
	if i+1 < len(d) && d[i+1] == '{' {
		t := TokenTemplateInterp
		if d[i] == '%' {
			t = TokenTemplateControl
		}
		n := 2
		if i+2 < len(d) && d[i+2] == '~' {
			n = 3
		}
		return t, n
	}
	return 0, 0
}

func (s *scanner) scanMain() {
	d := s.data
	i := s.p
	c := d[i]
	switch {
	case c == ' ' || c == '\t':
		j := i
		for j < len(d) && (d[j] == ' ' || d[j] == '\t') {
			j++
		}
		s.p = j
		return
	case isDigit(c):
		n := numberLen(d, i)
		s.emit(TokenNumberLit, i, i+n)
		s.p = i + n
		return
	case c == '#' || (c == '/' && i+1 < len(d) && d[i+1] == '/'):
		j := i
		for j < len(d) && d[j] != '\n' {
			j++
		}
		if j < len(d) {
			j++
		}
		s.emit(TokenComment, i, j)
		s.p = j
		return
	case c == '/' && i+1 < len(d) && d[i+1] == '*':
		k := bytes.Index(d[i+2:], []byte("*/"))
		if k >= 0 {
			j := i + 2 + k + 2
			s.emit(TokenComment, i, j)
			s.p = j
			return
		}
	case c == '\n':
		s.emit(TokenNewline, i, i+1)
		s.p = i + 1
		return
	case c == '\r' && i+1 < len(d) && d[i+1] == '\n':
		s.emit(TokenNewline, i, i+2)
		s.p = i + 2
		return
	case c == '"':
		s.emit(TokenOQuote, i, i+1)
		s.p = i + 1
		s.push(modeString)
		return
	case c == '{':
		s.emit(TokenOBrace, i, i+1)
		s.braces++
		s.p = i + 1
		return
	case c == '}':
		if len(s.retBraces) > 0 && s.retBraces[len(s.retBraces)-1] == s.braces {
			s.emit(TokenTemplateSeqEnd, i, i+1)
			s.braces--
			s.retBraces = s.retBraces[:len(s.retBraces)-1]
			s.pop()
		} else {
			s.emit(TokenCBrace, i, i+1)
			s.braces--
		}
		s.p = i + 1
		return
	case c == '~' && i+1 < len(d) && d[i+1] == '}':
		s.emit(TokenTemplateSeqEnd, i, i+2)
		if len(s.retBraces) > 0 && s.retBraces[len(s.retBraces)-1] == s.braces {
			s.braces--
			s.retBraces = s.retBraces[:len(s.retBraces)-1]
			s.pop()
		} else {
			s.braces--
		}
		s.p = i + 2
		return
	case c == '<' && i+1 < len(d) && d[i+1] == '<':
		j := i + 2
		if j < len(d) && d[j] == '-' {
			j++
		}
		if j < len(d) {
			if n := identLen(d, j); n > 0 {
				k := j + n
				nl := 0
				if k < len(d) && d[k] == '\n' {
					nl = 1
				} else if k+1 < len(d) && d[k] == '\r' && d[k+1] == '\n' {
					nl = 2
				}
				if nl > 0 {
					s.emit(TokenOHeredoc, i, k+nl)
					s.heredocs = append(s.heredocs, heredocInProgress{Marker: append([]byte(nil), d[j:k]...), StartOfLine: true})
					s.push(modeHeredoc)
					s.p = k + nl
					return
				}
			}
		}
	}
	// multi-char operators
	if i+2 < len(d) && d[i] == '.' && d[i+1] == '.' && d[i+2] == '.' {
		s.emit(TokenEllipsis, i, i+3)
		s.p = i + 3
		return
	}
	if i+1 < len(d) {
		two := string(d[i : i+2])
		var t TokenType
		switch two {
		case "==":
			t = TokenEqualOp
		case "!=":
			t = TokenNotEqual
		case ">=":
