// Lex scans the given source into tokens, terminated by an EOF token.
func Lex(src []byte, filename string) []Token {
	s := &scanner{data: src}
	for s.p < len(src) {
		switch s.mode() {
		case modeString:
			s.scanString()
		case modeHeredoc:
			s.scanHeredoc()
		default:
			s.scanMain()
		}
	}
	s.emit(TokenEOF, len(src), len(src))
	// compute positions
	toks := make([]Token, len(s.toks))
	line, col, b := 1, 1, 0
	advance := func(to int) {
		for b < to {
			if src[b] == '\n' {
				line++
				col = 1
				b++
				continue
			}
			_, sz := utf8.DecodeRune(src[b:])
			if b+sz > to {
				sz = to - b
			}
			b += sz
			col++
		}
	}
	for i, rt := range s.toks {
		advance(rt.start)
		start := Pos{Line: line, Column: col, Byte: b}
		advance(rt.end)
		end := Pos{Line: line, Column: col, Byte: b}
		toks[i] = Token{Type: rt.typ, Bytes: src[rt.start:rt.end], Range: Range{Filename: filename, Start: start, End: end}}
	}
	return toks
}
