		return false
	case subject.Type == TokenComma:
		return true
	case subject.Type == TokenQuotedLit || subject.Type == TokenStringLit || subject.Type == TokenOQuote || subject.Type == TokenOHeredoc || after.Type == TokenQuotedLit || after.Type == TokenStringLit || after.Type == TokenCQuote || after.Type == TokenCHeredoc:
