		switch before.Type {
		case TokenNil, TokenOParen, TokenOBrace, TokenOBrack, TokenEqual, TokenColon, TokenComma, TokenQuestion,
			TokenPlus, TokenStar, TokenSlash, TokenPercent, TokenMinus,
			TokenEqualOp, TokenNotEqual, TokenGreaterThan, TokenGreaterThanEq, TokenLessThan, TokenLessThanEq,
			TokenAnd, TokenOr, TokenBang:
			return false
		}
		return true
	case subject.Type == TokenOBrace || after.Type == TokenCBrace:
		if subject.Type == TokenOBrace && after.Type == TokenCBrace {
			return false
		}
		return true
	case (subject.Type == TokenTemplateInterp || subject.Type == TokenTemplateControl) && after.Type == TokenOBrace:
		return true
	case subject.Type == TokenCBrace && after.Type == TokenTemplateSeqEnd:
		return true
	case subject.Type == TokenTemplateSeqEnd && (after.Type == TokenTemplateInterp || after.Type == TokenTemplateControl):
		return false
	case tokenBracketChange(subject) > 0:
		return false
	case tokenBracketChange(after) < 0:
		return false
	}
	return true
}
