)

// silentError is an error that should not be printed by the CLI.
type silentError struct{ code int }

func (silentError) Error() string { return "" }

func main() {
	root := newRootCmd()
	cmd, err := root.ExecuteC()
	_ = cmd
	if err != nil {
		var se silentError
		if errors.As(err, &se) {
			if se.code != 0 {
				os.Exit(se.code)
			}
			os.Exit(1)
		}
		maybeCommunityError()
		os.Exit(1)
	}
}

func setHelp(c *cobra.Command, path string) {
	if s, ok := helpShort[path]; ok {
		c.Short = s
	}
	if l, ok := helpLong[path]; ok && l != c.Short {
		c.Long = l
	}
	if e, ok := helpExample[path]; ok {
		c.Example = e
	}
}

func newRootCmd() *cobra.Command {
	root := &cobra.Command{
		Use:          "atlas",
		Short:        "Manage your database schema as code",
		SilenceUsage: true,
	}
	root.AddCommand(
		newLicenseCmd(),
		newVersionCmd(),
		newSchemaCmd(),
		newMigrateCmd(),
	)
	return root
}

func newLicenseCmd() *cobra.Command {
	c := &cobra.Command{
		Use: "license",
		Run: func(cmd *cobra.Command, _ []string) {
			fmt.Fprintln(cmd.OutOrStdout(), "LICENSE\nAtlas is licensed under Apache 2.0 as found in https://github.com/ariga/atlas/blob/master/LICENSE.")
		},
	}
	setHelp(c, "license")
	return c
}

func newVersionCmd() *cobra.Command {
	c := &cobra.Command{
		Use: "version",
		Run: func(cmd *cobra.Command, _ []string) {
			fmt.Fprintln(cmd.OutOrStdout(), "atlas unofficial version - development\nhttps://github.com/ariga/atlas/releases/latest\nTo download an official version, visit: https://atlasgo.io/getting-started#installation")
		},
	}
	setHelp(c, "version")
	return c
}

// globalFlags holds the persistent flags shared by schema and migrate.
type globalFlags struct {
	config string
	env    string
	vars   varsFlag
}

var gFlags globalFlags

func addGlobalFlags(c *cobra.Command) {
	f := c.PersistentFlags()
	f.StringVarP(&gFlags.config, "config", "c", "file://atlas.hcl", "select config (project) file using URL format")
	f.StringVar(&gFlags.env, "env", "", "set which env from the config file to use")
	f.Var(&gFlags.vars, "var", "input variables")
}

// varsFlag implements pflag.Value for --var flags.
type varsFlag struct {
	order  []string
	values map[string][]string
}

func (v *varsFlag) String() string {
	if v.values == nil {
		return "[]"
	}
	var parts []string
	for _, k := range v.order {
		for _, x := range v.values[k] {
			parts = append(parts, k+":"+x)
		}
	}
	return "[" + strings.Join(parts, " ") + "]"
}

func (v *varsFlag) Type() string { return "<name>=<value>" }

func (v *varsFlag) Set(s string) error {
	recs, err := readAsCSV(s)
	if err != nil {
		return err
	}
	if v.values == nil {
		v.values = make(map[string][]string)
	}
	for _, r := range recs {
		kv := strings.SplitN(r, "=", 2)
		if len(kv) != 2 {
			return fmt.Errorf("variables must be format as key=value, got: %q", r)
		}
		if _, ok := v.values[kv[0]]; !ok {
			v.order = append(v.order, kv[0])
		}
		v.values[kv[0]] = append(v.values[kv[0]], kv[1])
	}
	return nil
}
EOF
echo"}

