package hcl

// Node is any AST node.
type Node interface{}

// Body is a body of attributes and blocks.
type Body struct {
	Attributes map[string]*Attribute
	AttrOrder  []*Attribute
	Blocks     []*Block
	SrcRange   Range
	EndRange   Range
}

// Attribute is a name = expr pair.
type Attribute struct {
	Name        string
	Expr        Expression
	SrcRange    Range
	NameRange   Range
	EqualsRange Range
}

// Block is a nested block.
type Block struct {
	Type            string
	Labels          []string
	Body            *Body
	TypeRange       Range
	LabelRanges     []Range
	OpenBraceRange  Range
	CloseBraceRange Range
}

// DefRange returns the definition range of the block (type + labels).
func (b *Block) DefRange() Range {
	last := b.TypeRange
	if len(b.LabelRanges) > 0 {
		last = b.LabelRanges[len(b.LabelRanges)-1]
	}
	return RangeBetween(b.TypeRange, last)
}

// Expression is an HCL expression.
type Expression interface {
	Range() Range
	StartRange() Range
}

// Traverser is a step in a traversal.
type Traverser interface{}

// TraverseRoot is the root of an absolute traversal.
type TraverseRoot struct {
	Name     string
	SrcRange Range
}

// TraverseAttr is an attribute access.
type TraverseAttr struct {
	Name     string
	SrcRange Range
}

// TraverseIndex is an index step.
type TraverseIndex struct {
	Key      Value
	SrcRange Range
}

// TraverseSplat is a splat step.
type TraverseSplat struct {
	Each     []Traverser
	SrcRange Range
}

// Traversal is a sequence of traversal steps.
type Traversal []Traverser

// RootName returns the name of the root step.
func (t Traversal) RootName() string {
	if len(t) == 0 {
		return ""
	}
	if r, ok := t[0].(TraverseRoot); ok {
		return r.Name
	}
	return ""
}

type LiteralValueExpr struct {
	Val      Value
	SrcRange Range
}

type TemplateExpr struct {
	Parts    []Expression
	SrcRange Range
}

type TemplateWrapExpr struct {
	Wrapped  Expression
	SrcRange Range
}

type TemplateJoinExpr struct {
	Tuple Expression
}

type ScopeTraversalExpr struct {
	Traversal Traversal
	SrcRange  Range
}

type RelativeTraversalExpr struct {
	Source    Expression
	Traversal Traversal
	SrcRange  Range
}

type FunctionCallExpr struct {
	Name        string
	Args        []Expression
	ExpandFinal bool
	NameRange   Range
	OpenParen   Range
	CloseParen  Range
}

type ConditionalExpr struct {
	Condition   Expression
	TrueResult  Expression
	FalseResult Expression
	SrcRange    Range
}

type Operation struct {
	Name string
	Tok  TokenType
}

var (
	OpLogicalOr          = &Operation{"||", TokenOr}
	OpLogicalAnd         = &Operation{"&&", TokenAnd}
	OpLogicalNot         = &Operation{"!", TokenBang}
	OpEqual              = &Operation{"==", TokenEqualOp}
	OpNotEqual           = &Operation{"!=", TokenNotEqual}
	OpGreaterThan        = &Operation{">", TokenGreaterThan}
	OpGreaterThanOrEqual = &Operation{">=", TokenGreaterThanEq}
	OpLessThan           = &Operation{"<", TokenLessThan}
	OpLessThanOrEqual    = &Operation{"<=", TokenLessThanEq}
	OpAdd                = &Operation{"+", TokenPlus}
	OpSubtract           = &Operation{"-", TokenMinus}
	OpMultiply           = &Operation{"*", TokenStar}
	OpDivide             = &Operation{"/", TokenSlash}
	OpModulo             = &Operation{"%", TokenPercent}
	OpNegate             = &Operation{"-", TokenMinus}
)

type BinaryOpExpr struct {
	LHS      Expression
	Op       *Operation
	RHS      Expression
	SrcRange Range
}

type UnaryOpExpr struct {
