func (e *LiteralValueExpr) Range() Range      { return e.SrcRange }
func (e *TemplateExpr) Range() Range          { return e.SrcRange }
func (e *TemplateWrapExpr) Range() Range      { return e.SrcRange }
func (e *TemplateJoinExpr) Range() Range      { return e.Tuple.Range() }
