}
func NumberFloatVal(f float64) Value {
	return Value{T: TNumber, N: new(big.Float).SetPrec(512).SetFloat64(f)}
}
func NumberVal(f *big.Float) Value { return Value{T: TNumber, N: f} }
func TupleVal(l []Value) Value     { return Value{T: TTuple, L: l} }
func ObjectVal(m map[string]Value) Value {
	if m == nil {
		m = map[string]Value{}
	}
	return Value{T: TObject, M: m}
}
func CapsuleVal(c interface{}) Value { return Value{T: TCapsule, Cap: c} }

func (v Value) IsNull() bool  { return v.T == TNull }
func (v Value) IsKnown() bool { return v.T != TUnknown }

// Keys returns sorted object keys.
func (v Value) Keys() []string {
	keys := make([]string, 0, len(v.M))
	for k := range v.M {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// NumberString formats a number like cty does.
func NumberString(f *big.Float) string {
	if f.IsInt() {
		i, _ := f.Int(nil)
		return i.String()
	}
	return f.Text('f', -1)
}

// GoString renders a value for debugging.
func (v Value) GoString() string {
	switch v.T {
	case TNull:
		return "null"
	case TString:
		return fmt.Sprintf("%q", v.S)
	case TNumber:
		return NumberString(v.N)
	case TBool:
		return fmt.Sprint(v.B)
	case TTuple:
		var parts []string
		for _, e := range v.L {
			parts = append(parts, e.GoString())
		}
		return "[" + strings.Join(parts, ", ") + "]"
	case TObject:
		var parts []string
		for _, k := range v.Keys() {
			parts = append(parts, k+"="+v.M[k].GoString())
