		return "{" + strings.Join(parts, ", ") + "}"
	case TCapsule:
		return fmt.Sprintf("capsule(%v)", v.Cap)
	}
	return "unknown"
}

// Equals compares two values.
func (v Value) Equals(o Value) bool {
	if v.T != o.T {
		return false
	}
	switch v.T {
	case TNull, TUnknown:
		return true
	case TString:
		return v.S == o.S
	case TNumber:
		return v.N.Cmp(o.N) == 0
	case TBool:
		return v.B == o.B
	case TTuple:
		if len(v.L) != len(o.L) {
			return false
		}
		for i := range v.L {
			if !v.L[i].Equals(o.L[i]) {
				return false
			}
		}
		return true
	case TObject:
		if len(v.M) != len(o.M) {
			return false
		}
		for k, x := range v.M {
			y, ok := o.M[k]
			if !ok || !x.Equals(y) {
				return false
			}
		}
		return true
	case TCapsule:
		return v.Cap == o.Cap
	}
	return false
}
