package hcl

import (
	"bytes"
	"fmt"
	"math/big"
	"strings"
	"unicode"
)

type peeker struct {
	Tokens           []Token
	NextIndex        int
	includeNewlines  []bool
}

func (p *peeker) includingNewlines() bool {
	if len(p.includeNewlines) == 0 {
		return true
	}
	return p.includeNewlines[len(p.includeNewlines)-1]
}

func (p *peeker) PushIncludeNewlines(b bool) { p.includeNewlines = append(p.includeNewlines, b) }
func (p *peeker) PopIncludeNewlines() {
	p.includeNewlines = p.includeNewlines[:len(p.includeNewlines)-1]
}

func (p *peeker) nextToken() (Token, int) {
	for i := p.NextIndex; i < len(p.Tokens); i++ {
		tok := p.Tokens[i]
		switch tok.Type {
		case TokenComment:
			if p.includingNewlines() {
				if len(tok.Bytes) > 0 && tok.Bytes[len(tok.Bytes)-1] == '\n' {
					return Token{Type: TokenNewline, Bytes: tok.Bytes[len(tok.Bytes)-1:], Range: tok.Range}, i + 1
				}
			}
			continue
		case TokenNewline:
			if !p.includingNewlines() {
				continue
			}
		}
		return tok, i + 1
	}
	return p.Tokens[len(p.Tokens)-1], len(p.Tokens)
}

func (p *peeker) Peek() Token {
	t, _ := p.nextToken()
	return t
}

func (p *peeker) Read() Token {
	t, n := p.nextToken()
	p.NextIndex = n
	return t
}

func (p *peeker) NextRange() Range { return p.Peek().Range }

func (p *peeker) PrevRange() Range {
	if p.NextIndex == 0 {
		return p.NextRange()
	}
	return p.Tokens[p.NextIndex-1].Range
}

type parser struct {
	*peeker
	recovery bool
}

func (p *parser) setRecovery() { p.recovery = true }

// ParseConfig parses an HCL configuration file.
func ParseConfig(src []byte, filename string) (*File, Diagnostics) {
	tokens := Lex(src, filename)
	diags := checkInvalidTokens(tokens)
	p := &parser{peeker: &peeker{Tokens: tokens}}
	body, pdiags := p.ParseBody(TokenEOF)
	diags = append(diags, pdiags...)
	return &File{Body: body, Bytes: src, Name: filename}, diags
}

func checkInvalidTokens(tokens []Token) Diagnostics {
	var diags Diagnostics
	toldBitwise, toldExponent, toldBacktick, toldApostrophe, toldSemicolon, toldTabs, toldBadUTF8 := 0, 0, 0, 0, 0, 0, 0
	for _, tok := range tokens {
		r := tok.Range
		switch tok.Type {
		case TokenBitwiseAnd, TokenBitwiseOr, TokenBitwiseXor, TokenBitwiseNot:
			if toldBitwise < 4 {
				var suggestion string
				switch tok.Type {
				case TokenBitwiseAnd:
					suggestion = " Did you mean boolean AND (\"&&\")?"
				case TokenBitwiseOr:
					suggestion = " Did you mean boolean OR (\"||\")?"
				case TokenBitwiseNot:
					suggestion = " Did you mean boolean NOT (\"!\")?"
				}
				diags = append(diags, &Diagnostic{Summary: "Unsupported operator", Detail: "Bitwise operators are not supported." + suggestion, Subject: &r})
				toldBitwise++
			}
		case TokenStarStar:
			if toldExponent < 1 {
				diags = append(diags, &Diagnostic{Summary: "Unsupported operator", Detail: "\"**\" is not a supported operator. Exponentiation is not supported as an operator.", Subject: &r})
				toldExponent++
			}
		case TokenBacktick:
			if toldBacktick%2 == 0 {
				diags = append(diags, &Diagnostic{Summary: "Invalid character", Detail: "The \"`\" character is not valid. To create a multi-line string, use the \"heredoc\" syntax, like \"<<EOT\".", Subject: &r})
			}
			if toldBacktick <= 2 {
				toldBacktick++
			}
		case TokenApostrophe:
			if toldApostrophe%2 == 0 {
				diags = append(diags, &Diagnostic{Summary: "Invalid character", Detail: "Single quotes are not valid. Use double quotes (\") to enclose strings.", Subject: &r})
			}
			if toldApostrophe <= 2 {
				toldApostrophe++
			}
		case TokenSemicolon:
			if toldSemicolon < 1 {
				diags = append(diags, &Diagnostic{Summary: "Invalid character", Detail: "The \";\" character is not valid. Use newlines to separate arguments and blocks, and commas to separate items in collection values.", Subject: &r})
				toldSemicolon++
			}
		case TokenTabs:
			if toldTabs < 1 {
				diags = append(diags, &Diagnostic{Summary: "Invalid character", Detail: "Tab characters may not be used. The recommended indentation style is two spaces per indent.", Subject: &r})
				toldTabs++
			}
		case TokenBadUTF8:
			if toldBadUTF8 < 1 {
				diags = append(diags, &Diagnostic{Summary: "Invalid character encoding", Detail: "All input files must be UTF-8 encoded. Ensure that UTF-8 encoding is selected in your editor.", Subject: &r})
				toldBadUTF8++
			}
		case TokenQuotedNewline:
			diags = append(diags, &Diagnostic{Summary: "Invalid multi-line string", Detail: "Quoted strings may not be split over multiple lines. To produce a multi-line string, either use the \\n escape to represent a newline character or use the \"heredoc\" multi-line template syntax.", Subject: &r})
		case TokenInvalid:
			chars := string(tok.Bytes)
			switch chars {
			case "“", "”":
				diags = append(diags, &Diagnostic{Summary: "Invalid character", Detail: "\"Curly quotes\" are not valid here. These can sometimes be inadvertently introduced when sharing code via documents or discussion forums. It might help to replace the character with a \"straight quote\".", Subject: &r})
			default:
				diags = append(diags, &Diagnostic{Summary: "Invalid character", Detail: "This character is not used within the language.", Subject: &r})
			}
		}
	}
	return diags
}

func (p *parser) oppositeBracket(ty TokenType) TokenType {
	switch ty {
	case TokenOBrace:
		return TokenCBrace
	case TokenOBrack:
		return TokenCBrack
	case TokenOParen:
		return TokenCParen
	case TokenOQuote:
		return TokenCQuote
	case TokenOHeredoc:
		return TokenCHeredoc
	case TokenCBrace:
		return TokenOBrace
	case TokenCBrack:
		return TokenOBrack
	case TokenCParen:
		return TokenOParen
	case TokenCQuote:
		return TokenOQuote
	case TokenCHeredoc:
		return TokenOHeredoc
	case TokenTemplateControl:
		return TokenTemplateSeqEnd
	case TokenTemplateInterp:
		return TokenTemplateSeqEnd
	case TokenTemplateSeqEnd:
		return TokenTemplateInterp
	}
	return TokenNil
}

func (p *parser) recover(end TokenType) Token {
	start := p.oppositeBracket(end)
	p.recovery = true
	nest := 0
	for {
		tok := p.Read()
		ty := tok.Type
		if end == TokenTemplateSeqEnd && ty == TokenTemplateControl {
			ty = TokenTemplateInterp
		}
		switch ty {
		case start:
			nest++
		case end:
			if nest < 1 {
				return tok
			}
			nest--
		case TokenEOF:
			return tok
		}
	}
}

func (p *parser) recoverOver(start TokenType) {
	end := p.oppositeBracket(start)
	nest := 0
	for {
		tok := p.Read()
		switch tok.Type {
		case start:
			nest++
		case end:
			nest--
			if nest < 1 {
				return
			}
		case TokenEOF:
			return
		}
	}
}

func (p *parser) recoverAfterBodyItem() {
	p.recovery = true
	var open []TokenType
	for {
		tok := p.Read()
		switch tok.Type {
		case TokenNewline:
			if len(open) == 0 {
				return
			}
		case TokenEOF:
			return
		case TokenOBrace, TokenOBrack, TokenOParen, TokenOQuote, TokenOHeredoc, TokenTemplateInterp, TokenTemplateControl:
			open = append(open, tok.Type)
		case TokenCBrace, TokenCBrack, TokenCParen, TokenCQuote, TokenCHeredoc:
			opener := p.oppositeBracket(tok.Type)
			for len(open) > 0 && open[len(open)-1] != opener {
				open = open[:len(open)-1]
			}
			if len(open) > 0 {
				open = open[:len(open)-1]
			}
		case TokenTemplateSeqEnd:
			for len(open) > 0 && open[len(open)-1] != TokenTemplateInterp && open[len(open)-1] != TokenTemplateControl {
				open = open[:len(open)-1]
			}
			if len(open) > 0 {
				open = open[:len(open)-1]
			}
		}
	}
}

// ParseBody parses a body until the end token.
func (p *parser) ParseBody(end TokenType) (*Body, Diagnostics) {
	attrs := map[string]*Attribute{}
	var order []*Attribute
	var blocks []*Block
	var diags Diagnostics
	startRange := p.PrevRange()
	var endRange Range
Token:
	for {
		next := p.Peek()
		if next.Type == end {
			endRange = p.NextRange()
			p.Read()
			break Token
		}
		switch next.Type {
		case TokenNewline:
			p.Read()
			continue
		case TokenIdent:
			item, itemDiags := p.ParseBodyItem()
			diags = append(diags, itemDiags...)
			switch titem := item.(type) {
			case *Block:
				blocks = append(blocks, titem)
			case *Attribute:
				if existing, exists := attrs[titem.Name]; exists {
					nr := titem.NameRange
					diags = append(diags, &Diagnostic{
						Summary: "Attribute redefined",
						Detail:  fmt.Sprintf("The argument %q was already set at %s. Each argument may be set only once.", titem.Name, existing.NameRange.String()),
						Subject: &nr,
					})
				} else {
					attrs[titem.Name] = titem
					order = append(order, titem)
				}
			default:
				continue
			}
		default:
			bad := p.Read()
			if !p.recovery {
				br := bad.Range
				switch bad.Type {
				case TokenOQuote:
					diags = append(diags, &Diagnostic{Summary: "Invalid argument name", Detail: "Argument names must not be quoted.", Subject: &br})
				case TokenEOF:
					sr := startRange
					switch end {
					case TokenCBrace:
						diags = append(diags, &Diagnostic{Summary: "Unclosed configuration block", Detail: "There is no closing brace for this block before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.", Subject: &sr})
					default:
						diags = append(diags, &Diagnostic{Summary: "Unclosed configuration body", Detail: "Found end of file before the end of this configuration body.", Subject: &sr})
					}
				default:
					diags = append(diags, &Diagnostic{Summary: "Argument or block definition required", Detail: "An argument or block definition is required here.", Subject: &br})
				}
			}
			endRange = p.PrevRange()
			p.recover(end)
			break Token
		}
	}
	return &Body{Attributes: attrs, AttrOrder: order, Blocks: blocks, SrcRange: RangeBetween(startRange, endRange), EndRange: Range{Filename: endRange.Filename, Start: endRange.End, End: endRange.End}}, diags
}

func (p *parser) ParseBodyItem() (Node, Diagnostics) {
	ident := p.Read()
	if ident.Type != TokenIdent {
		p.recoverAfterBodyItem()
		r := ident.Range
		return nil, Diagnostics{{Summary: "Argument or block definition required", Detail: "An argument or block definition is required here.", Subject: &r}}
	}
	next := p.Peek()
	switch next.Type {
	case TokenEqual:
		return p.finishParsingBodyAttribute(ident, false)
	case TokenOQuote, TokenOBrace, TokenIdent:
		return p.finishParsingBodyBlock(ident)
	default:
		p.recoverAfterBodyItem()
		r := ident.Range
		return nil, Diagnostics{{Summary: "Argument or block definition required", Detail: "An argument or block definition is required here. To set an argument, use the equals sign \"=\" to introduce the argument value.", Subject: &r}}
	}
}

func (p *parser) parseSingleAttrBody(end TokenType) (*Body, Diagnostics) {
	ident := p.Read()
	if ident.Type != TokenIdent {
		p.recoverAfterBodyItem()
		r := ident.Range
		return nil, Diagnostics{{Summary: "Argument or block definition required", Detail: "An argument or block definition is required here.", Subject: &r}}
	}
	var attr *Attribute
	var diags Diagnostics
	next := p.Peek()
	switch next.Type {
	case TokenEqual:
		node, attrDiags := p.finishParsingBodyAttribute(ident, true)
		diags = append(diags, attrDiags...)
		attr = node.(*Attribute)
	case TokenOQuote, TokenOBrace, TokenIdent:
		p.recoverAfterBodyItem()
		r := RangeBetween(ident.Range, next.Range)
		return nil, Diagnostics{{Summary: "Argument definition required", Detail: fmt.Sprintf("A single-line block definition can contain only a single argument. If you meant to define argument %q, use an equals sign to assign it a value. To define a nested block, place it on a line of its own within its parent block.", ident.Bytes), Subject: &r}}
	default:
		p.recoverAfterBodyItem()
		r := ident.Range
		return nil, Diagnostics{{Summary: "Argument or block definition required", Detail: "An argument or block definition is required here. To set an argument, use the equals sign \"=\" to introduce the argument value.", Subject: &r}}
	}
	body := &Body{Attributes: map[string]*Attribute{attr.Name: attr}, AttrOrder: []*Attribute{attr}, SrcRange: attr.SrcRange, EndRange: attr.SrcRange}
	return body, diags
}

func (p *parser) finishParsingBodyAttribute(ident Token, singleLine bool) (Node, Diagnostics) {
	eqTok := p.Read()
	var endRange Range
	expr, diags := p.ParseExpression()
	if p.recovery && diags.HasErrors() {
		p.recoverAfterBodyItem()
	} else {
		endRange = p.PrevRange()
		if !singleLine {
			end := p.Peek()
			if end.Type != TokenNewline && end.Type != TokenEOF {
				if !p.recovery {
					summary := "Missing newline after argument"
					detail := "An argument definition must end with a newline."
					if end.Type == TokenComma {
						summary = "Unexpected comma after argument"
						detail = "Argument definitions must be separated by newlines, not commas. " + detail
					}
					r := end.Range
					diags = append(diags, &Diagnostic{Summary: summary, Detail: detail, Subject: &r})
				}
				p.recoverAfterBodyItem()
			} else {
				endRange = p.PrevRange()
				p.Read()
			}
		}
	}
	if endRange.Filename == "" && endRange.Start.Line == 0 {
		endRange = expr.Range()
	}
	return &Attribute{
		Name:        string(ident.Bytes),
		Expr:        expr,
		SrcRange:    RangeBetween(ident.Range, endRange),
		NameRange:   ident.Range,
		EqualsRange: eqTok.Range,
	}, diags
}

func (p *parser) finishParsingBodyBlock(ident Token) (Node, Diagnostics) {
	blockType := string(ident.Bytes)
	var diags Diagnostics
	var labels []string
	var labelRanges []Range
	var oBrace Token
Token:
	for {
		tok := p.Peek()
		switch tok.Type {
		case TokenOBrace:
			oBrace = p.Read()
			break Token
		case TokenOQuote:
			label, labelRange, labelDiags := p.parseQuotedStringLiteral()
			diags = append(diags, labelDiags...)
			labels = append(labels, label)
			labelRanges = append(labelRanges, labelRange)
		case TokenIdent:
			tok = p.Read()
			labels = append(labels, string(tok.Bytes))
			labelRanges = append(labelRanges, tok.Range)
		default:
			r := tok.Range
			switch tok.Type {
			case TokenEqual:
				diags = append(diags, &Diagnostic{Summary: "Invalid block definition", Detail: "The equals sign \"=\" indicates an argument definition, and must not be used when defining a block.", Subject: &r})
			case TokenNewline:
				diags = append(diags, &Diagnostic{Summary: "Invalid block definition", Detail: "A block definition must have block content delimited by \"{\" and \"}\", starting on the same line as the block header.", Subject: &r})
			default:
				if !p.recovery {
					diags = append(diags, &Diagnostic{Summary: "Invalid block definition", Detail: "Either a quoted string block label or an opening brace (\"{\") is expected here.", Subject: &r})
				}
			}
			p.recoverAfterBodyItem()
			return &Block{Type: blockType, Labels: labels, Body: &Body{Attributes: map[string]*Attribute{}, SrcRange: ident.Range, EndRange: ident.Range}, TypeRange: ident.Range, LabelRanges: labelRanges, OpenBraceRange: ident.Range, CloseBraceRange: ident.Range}, diags
		}
	}
	var body *Body
	var bodyDiags Diagnostics
	switch p.Peek().Type {
	case TokenNewline, TokenEOF, TokenCBrace:
		body, bodyDiags = p.ParseBody(TokenCBrace)
	default:
		body, bodyDiags = p.parseSingleAttrBody(TokenCBrace)
	}
	diags = append(diags, bodyDiags...)
	cBraceRange := p.PrevRange()
	eol := p.Peek()
	if eol.Type == TokenNewline || eol.Type == TokenEOF {
		p.Read()
	} else {
		if !p.recovery {
			r := eol.Range
			diags = append(diags, &Diagnostic{Summary: "Missing newline after block definition", Detail: "A block definition must end with a newline.", Subject: &r})
		}
		p.recoverAfterBodyItem()
	}
	if body == nil {
		body = &Body{Attributes: map[string]*Attribute{}, SrcRange: RangeBetween(oBrace.Range, cBraceRange), EndRange: cBraceRange}
	}
	return &Block{Type: blockType, Labels: labels, Body: body, TypeRange: ident.Range, LabelRanges: labelRanges, OpenBraceRange: oBrace.Range, CloseBraceRange: cBraceRange}, diags
}

func (p *parser) ParseExpression() (Expression, Diagnostics) {
	return p.parseTernaryConditional()
}

func (p *parser) parseTernaryConditional() (Expression, Diagnostics) {
	startRange := p.NextRange()
	var diags Diagnostics
	condExpr, condDiags := p.parseBinaryOps(binaryOps)
	diags = append(diags, condDiags...)
	if p.recovery && condDiags.HasErrors() {
		return condExpr, diags
	}
	questionMark := p.Peek()
	if questionMark.Type != TokenQuestion {
		return condExpr, diags
	}
	p.Read()
	trueExpr, trueDiags := p.ParseExpression()
	diags = append(diags, trueDiags...)
	if p.recovery && trueDiags.HasErrors() {
		return condExpr, diags
	}
	colon := p.Peek()
	if colon.Type != TokenColon {
		r := colon.Range
		diags = append(diags, &Diagnostic{Summary: "Missing false expression in conditional", Detail: "The conditional operator (...?...:...) requires a false expression, delimited by a colon.", Subject: &r})
		return condExpr, diags
	}
	p.Read()
	falseExpr, falseDiags := p.ParseExpression()
	diags = append(diags, falseDiags...)
	if p.recovery && falseDiags.HasErrors() {
		return condExpr, diags
	}
	return &ConditionalExpr{Condition: condExpr, TrueResult: trueExpr, FalseResult: falseExpr, SrcRange: RangeBetween(startRange, falseExpr.Range())}, diags
}

var binaryOps = []map[TokenType]*Operation{
	{TokenOr: OpLogicalOr},
	{TokenAnd: OpLogicalAnd},
	{TokenEqualOp: OpEqual, TokenNotEqual: OpNotEqual},
	{TokenGreaterThan: OpGreaterThan, TokenGreaterThanEq: OpGreaterThanOrEqual, TokenLessThan: OpLessThan, TokenLessThanEq: OpLessThanOrEqual},
	{TokenPlus: OpAdd, TokenMinus: OpSubtract},
	{TokenStar: OpMultiply, TokenSlash: OpDivide, TokenPercent: OpModulo},
}

func (p *parser) parseBinaryOps(ops []map[TokenType]*Operation) (Expression, Diagnostics) {
	if len(ops) == 0 {
		return p.parseExpressionWithTraversals()
	}
	thisLevel := ops[0]
	remaining := ops[1:]
	var diags Diagnostics
	var operation *Operation
	var rhs Expression
	lhs, lhsDiags := p.parseBinaryOps(remaining)
	diags = append(diags, lhsDiags...)
	if p.recovery && lhsDiags.HasErrors() {
		return lhs, diags
	}
	for {
		next := p.Peek()
		newOp, ok := thisLevel[next.Type]
		if !ok {
			break
		}
		if operation != nil {
			lhs = &BinaryOpExpr{LHS: lhs, Op: operation, RHS: rhs, SrcRange: RangeBetween(lhs.Range(), rhs.Range())}
		}
		operation = newOp
		p.Read()
		var rhsDiags Diagnostics
		rhs, rhsDiags = p.parseBinaryOps(remaining)
		diags = append(diags, rhsDiags...)
		if p.recovery && rhsDiags.HasErrors() {
			return lhs, diags
		}
	}
	if operation == nil {
		return lhs, diags
	}
	return &BinaryOpExpr{LHS: lhs, Op: operation, RHS: rhs, SrcRange: RangeBetween(lhs.Range(), rhs.Range())}, diags
}

func (p *parser) parseExpressionWithTraversals() (Expression, Diagnostics) {
	term, diags := p.parseExpressionTerm()
	ret, more := p.parseExpressionTraversals(term)
	diags = append(diags, more...)
	return ret, diags
}

func makeRelativeTraversal(expr Expression, next Traverser, rng Range) Expression {
	switch texpr := expr.(type) {
	case *ScopeTraversalExpr:
		t := append(Traversal{}, texpr.Traversal...)
		t = append(t, next)
		return &ScopeTraversalExpr{Traversal: t, SrcRange: RangeBetween(texpr.SrcRange, rng)}
	case *RelativeTraversalExpr:
		t := append(Traversal{}, texpr.Traversal...)
		t = append(t, next)
		return &RelativeTraversalExpr{Source: texpr.Source, Traversal: t, SrcRange: RangeBetween(texpr.SrcRange, rng)}
	default:
		return &RelativeTraversalExpr{Source: expr, Traversal: Traversal{next}, SrcRange: RangeBetween(expr.Range(), rng)}
	}
}

func (p *parser) parseExpressionTraversals(from Expression) (Expression, Diagnostics) {
	var diags Diagnostics
	ret := from
Traversal:
	for {
		next := p.Peek()
		switch next.Type {
		case TokenDot:
			dot := p.Read()
			attrTok := p.Peek()
			switch attrTok.Type {
			case TokenIdent:
				attrTok = p.Read()
				rng := RangeBetween(dot.Range, attrTok.Range)
				ret = makeRelativeTraversal(ret, TraverseAttr{Name: string(attrTok.Bytes), SrcRange: rng}, rng)
			case TokenNumberLit:
				numTok := p.Read()
				if dotIdx := bytes.IndexByte(numTok.Bytes, '.'); dotIdx >= 0 {
					r := numTok.Range
					diags = append(diags, &Diagnostic{Summary: "Invalid legacy index syntax", Detail: fmt.Sprintf("When using the legacy index syntax, chaining two indexes together is not permitted. Use the proper index syntax instead, like [%s][%s].", numTok.Bytes[:dotIdx], numTok.Bytes[dotIdx+1:]), Subject: &r})
					rng := RangeBetween(dot.Range, numTok.Range)
					ret = makeRelativeTraversal(ret, TraverseIndex{Key: UnknownVal, SrcRange: rng}, rng)
					break
				}
				numVal, numDiags := p.numberLitValue(numTok)
				diags = append(diags, numDiags...)
				rng := RangeBetween(dot.Range, numTok.Range)
				ret = makeRelativeTraversal(ret, TraverseIndex{Key: numVal, SrcRange: rng}, rng)
			case TokenStar:
				marker := p.Read()
				var trav Traversal
				firstRange := p.NextRange()
				lastRange := marker.Range
				for p.Peek().Type == TokenDot {
					dot := p.Read()
					if p.Peek().Type == TokenNumberLit {
						numTok := p.Read()
						numVal, numDiags := p.numberLitValue(numTok)
						diags = append(diags, numDiags...)
						trav = append(trav, TraverseIndex{Key: numVal, SrcRange: RangeBetween(dot.Range, numTok.Range)})
						lastRange = numTok.Range
						continue
					}
					if p.Peek().Type != TokenIdent {
						if !p.recovery {
							if p.Peek().Type == TokenStar {
								r := p.Peek().Range
								diags = append(diags, &Diagnostic{Summary: "Nested splat expression not allowed", Detail: "A splat expression (*) cannot be used inside another attribute-only splat expression.", Subject: &r})
							} else {
								r := attrTok.Range
								diags = append(diags, &Diagnostic{Summary: "Invalid attribute name", Detail: "An attribute name is required after a dot.", Subject: &r})
							}
						}
						p.setRecovery()
						continue Traversal
					}
					at := p.Read()
					trav = append(trav, TraverseAttr{Name: string(at.Bytes), SrcRange: RangeBetween(dot.Range, at.Range)})
					lastRange = at.Range
				}
				itemExpr := &AnonSymbolExpr{SrcRange: RangeBetween(dot.Range, marker.Range)}
				var travExpr Expression
				if len(trav) == 0 {
					travExpr = itemExpr
				} else {
					travExpr = &RelativeTraversalExpr{Source: itemExpr, Traversal: trav, SrcRange: RangeBetween(firstRange, lastRange)}
				}
				ret = &SplatExpr{Source: ret, Each: travExpr, Item: itemExpr, SrcRange: RangeBetween(from.Range(), lastRange), MarkerRange: RangeBetween(dot.Range, marker.Range)}
			default:
				r := attrTok.Range
				diags = append(diags, &Diagnostic{Summary: "Invalid attribute name", Detail: "An attribute name is required after a dot.", Subject: &r})
				p.setRecovery()
			}
		case TokenOBrack:
			open := p.Read()
			switch p.Peek().Type {
			case TokenStar:
				p.Read()
				cl := p.Read()
				if cl.Type != TokenCBrack && !p.recovery {
					r := cl.Range
					diags = append(diags, &Diagnostic{Summary: "Missing close bracket on splat index", Detail: "The star for a full splat operator must be immediately followed by a closing bracket (\"]\").", Subject: &r})
					cl = p.recover(TokenCBrack)
				}
				itemExpr := &AnonSymbolExpr{SrcRange: RangeBetween(open.Range, cl.Range)}
				travExpr, nested := p.parseExpressionTraversals(itemExpr)
				diags = append(diags, nested...)
				ret = &SplatExpr{Source: ret, Each: travExpr, Item: itemExpr, SrcRange: RangeBetween(from.Range(), travExpr.Range()), MarkerRange: RangeBetween(open.Range, cl.Range)}
			default:
				var cl Token
				p.PushIncludeNewlines(false)
				keyExpr, keyDiags := p.ParseExpression()
				diags = append(diags, keyDiags...)
				if p.recovery && keyDiags.HasErrors() {
					cl = p.recover(TokenCBrack)
				} else {
					cl = p.Read()
					if cl.Type != TokenCBrack && !p.recovery {
						r := cl.Range
						diags = append(diags, &Diagnostic{Summary: "Missing close bracket on index", Detail: "The index operator must end with a closing bracket (\"]\").", Subject: &r})
						cl = p.recover(TokenCBrack)
					}
				}
				p.PopIncludeNewlines()
				rng := RangeBetween(open.Range, cl.Range)
				if lit, ok := keyExpr.(*LiteralValueExpr); ok {
					ret = makeRelativeTraversal(ret, TraverseIndex{Key: lit.Val, SrcRange: rng}, rng)
				} else if tmpl, ok := keyExpr.(*TemplateExpr); ok && tmpl.IsStringLiteral() {
					v := StringVal(tmpl.Parts[0].(*LiteralValueExpr).Val.S)
					if len(tmpl.Parts) == 0 {
						v = StringVal("")
					}
					ret = makeRelativeTraversal(ret, TraverseIndex{Key: v, SrcRange: rng}, rng)
				} else {
					ret = &IndexExpr{Collection: ret, Key: keyExpr, SrcRange: RangeBetween(from.Range(), rng), OpenRange: open.Range, BracketRange: rng}
				}
			}
		default:
			break Traversal
		}
	}
	return ret, diags
}

// IsStringLiteral reports whether the template is a single literal string.
func (e *TemplateExpr) IsStringLiteral() bool {
	if len(e.Parts) != 1 {
		return false
	}
	l, ok := e.Parts[0].(*LiteralValueExpr)
	return ok && l.Val.T == TString
}

func (p *parser) numberLitValue(tok Token) (Value, Diagnostics) {
	f, _, err := big.ParseFloat(string(tok.Bytes), 10, 512, big.ToNearestEven)
	if err != nil {
		r := tok.Range
		return UnknownVal, Diagnostics{{Summary: "Invalid number literal", Detail: "Failed to recognize the value of this number literal.", Subject: &r}}
	}
	return NumberVal(f), nil
}

func (p *parser) parseExpressionTerm() (Expression, Diagnostics) {
	start := p.Peek()
	switch start.Type {
	case TokenOParen:
		oParen := p.Read()
		p.PushIncludeNewlines(false)
		expr, diags := p.ParseExpression()
		if diags.HasErrors() {
			p.recover(TokenCParen)
			p.PopIncludeNewlines()
			return expr, diags
		}
		cl := p.Peek()
		if cl.Type != TokenCParen {
			r := cl.Range
			diags = append(diags, &Diagnostic{Summary: "Unbalanced parentheses", Detail: "Expected a closing parenthesis to terminate the expression.", Subject: &r})
			p.setRecovery()
		}
		cParen := p.Read()
		p.PopIncludeNewlines()
		return &ParenthesesExpr{Expression: expr, SrcRange: RangeBetween(oParen.Range, cParen.Range)}, diags
	case TokenNumberLit:
		tok := p.Read()
		v, diags := p.numberLitValue(tok)
		return &LiteralValueExpr{Val: v, SrcRange: tok.Range}, diags
	case TokenIdent:
		tok := p.Read()
		if p.Peek().Type == TokenOParen {
			return p.finishParsingFunctionCall(tok)
		}
		switch string(tok.Bytes) {
		case "true":
			return &LiteralValueExpr{Val: True, SrcRange: tok.Range}, nil
		case "false":
			return &LiteralValueExpr{Val: False, SrcRange: tok.Range}, nil
		case "null":
			return &LiteralValueExpr{Val: NullVal, SrcRange: tok.Range}, nil
		}
		return &ScopeTraversalExpr{Traversal: Traversal{TraverseRoot{Name: string(tok.Bytes), SrcRange: tok.Range}}, SrcRange: tok.Range}, nil
	case TokenOQuote, TokenOHeredoc:
		open := p.Read()
		closer := p.oppositeBracket(open.Type)
		flush := open.Type == TokenOHeredoc && len(open.Bytes) > 2 && open.Bytes[2] == '-'
		exprs, passthru, diags := p.parseTemplateInner(closer, flush)
		closeRange := p.PrevRange()
		if passthru {
			return &TemplateWrapExpr{Wrapped: exprs[0], SrcRange: RangeBetween(open.Range, closeRange)}, diags
		}
		return &TemplateExpr{Parts: exprs, SrcRange: RangeBetween(open.Range, closeRange)}, diags
	case TokenMinus:
		tok := p.Read()
		operand, diags := p.parseExpressionWithTraversals()
		return &UnaryOpExpr{Op: OpNegate, Val: operand, SrcRange: RangeBetween(tok.Range, operand.Range()), SymbolRange: tok.Range}, diags
	case TokenBang:
		tok := p.Read()
		operand, diags := p.parseExpressionWithTraversals()
		return &UnaryOpExpr{Op: OpLogicalNot, Val: operand, SrcRange: RangeBetween(tok.Range, operand.Range()), SymbolRange: tok.Range}, diags
	case TokenOBrack:
		return p.parseTupleCons()
	case TokenOBrace:
		return p.parseObjectCons()
	default:
		var diags Diagnostics
		if !p.recovery {
			r := start.Range
			switch start.Type {
			case TokenEOF:
				diags = append(diags, &Diagnostic{Summary: "Missing expression", Detail: "Expected the start of an expression, but found the end of the file.", Subject: &r})
			default:
				diags = append(diags, &Diagnostic{Summary: "Invalid expression", Detail: "Expected the start of an expression, but found an invalid expression token.", Subject: &r})
			}
		}
		p.setRecovery()
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: start.Range}, diags
	}
}

func (p *parser) finishParsingFunctionCall(name Token) (Expression, Diagnostics) {
	var diags Diagnostics
	openTok := p.Read()
	var args []Expression
	var expandFinal bool
	var closeTok Token
	p.PushIncludeNewlines(false)
Token:
	for {
		tok := p.Peek()
		if tok.Type == TokenCParen {
			closeTok = p.Read()
			break Token
		}
		arg, argDiags := p.ParseExpression()
		args = append(args, arg)
		diags = append(diags, argDiags...)
		if p.recovery && argDiags.HasErrors() {
			closeTok = p.recover(TokenCParen)
			break Token
		}
		sep := p.Read()
		if sep.Type == TokenCParen {
			closeTok = sep
			break Token
		}
		if sep.Type == TokenEllipsis {
			expandFinal = true
			if p.Peek().Type != TokenCParen {
				if !p.recovery {
					r := sep.Range
					diags = append(diags, &Diagnostic{Summary: "Missing closing parenthesis", Detail: "An expanded function argument (with ...) must be immediately followed by closing parentheses.", Subject: &r})
				}
				closeTok = p.recover(TokenCParen)
			} else {
				closeTok = p.Read()
			}
			break Token
		}
		if sep.Type != TokenComma {
			r := sep.Range
			diags = append(diags, &Diagnostic{Summary: "Missing argument separator", Detail: "A comma is required to separate each function argument from the next.", Subject: &r})
			closeTok = p.recover(TokenCParen)
			break Token
		}
		if p.Peek().Type == TokenCParen {
			closeTok = p.Read()
			break Token
		}
	}
	p.PopIncludeNewlines()
	return &FunctionCallExpr{Name: string(name.Bytes), Args: args, ExpandFinal: expandFinal, NameRange: name.Range, OpenParen: openTok.Range, CloseParen: closeTok.Range}, diags
}

func isKeyword(tok Token, kw string) bool {
	return tok.Type == TokenIdent && string(tok.Bytes) == kw
}

func (p *parser) parseTupleCons() (Expression, Diagnostics) {
	open := p.Read()
	p.PushIncludeNewlines(false)
	defer p.PopIncludeNewlines()
	if isKeyword(p.Peek(), "for") {
		return p.finishParsingForExpr(open)
	}
	var cl Token
	var diags Diagnostics
	var exprs []Expression
	for {
		next := p.Peek()
		if next.Type == TokenCBrack {
			cl = p.Read()
			break
		}
		expr, exprDiags := p.ParseExpression()
		exprs = append(exprs, expr)
		diags = append(diags, exprDiags...)
		if p.recovery && exprDiags.HasErrors() {
			cl = p.recover(TokenCBrack)
			break
		}
		next = p.Peek()
		if next.Type == TokenCBrack {
			cl = p.Read()
			break
		}
		if next.Type != TokenComma {
			if !p.recovery {
				r := next.Range
				diags = append(diags, &Diagnostic{Summary: "Missing item separator", Detail: "Expected a comma to mark the beginning of the next item.", Subject: &r})
			}
			cl = p.recover(TokenCBrack)
			break
		}
		p.Read()
	}
	return &TupleConsExpr{Exprs: exprs, SrcRange: RangeBetween(open.Range, cl.Range), OpenRange: open.Range}, diags
}

func (p *parser) parseObjectCons() (Expression, Diagnostics) {
	open := p.Read()
	p.PushIncludeNewlines(false)
	isFor := isKeyword(p.Peek(), "for")
	p.PopIncludeNewlines()
	if isFor {
		return p.finishParsingForExpr(open)
	}
	p.PushIncludeNewlines(true)
	defer p.PopIncludeNewlines()
	var cl Token
	var diags Diagnostics
	var items []ObjectConsItem
	for {
		next := p.Peek()
		if next.Type == TokenNewline {
			p.Read()
			continue
		}
		if next.Type == TokenCBrace {
			cl = p.Read()
			break
		}
		forceNonLiteral := p.Peek().Type == TokenOParen
		key, keyDiags := p.ParseExpression()
		diags = append(diags, keyDiags...)
		if p.recovery && keyDiags.HasErrors() {
			cl = p.recover(TokenCBrace)
			break
		}
		key = &ObjectConsKeyExpr{Wrapped: key, ForceNonLiteral: forceNonLiteral}
		next = p.Peek()
		if next.Type != TokenEqual && next.Type != TokenColon {
			if !p.recovery {
				r := next.Range
				switch next.Type {
				case TokenNewline, TokenComma:
					diags = append(diags, &Diagnostic{Summary: "Missing attribute value", Detail: "Expected an attribute value, introduced by an equals sign (\"=\").", Subject: &r})
				case TokenIdent:
					diags = append(diags, &Diagnostic{Summary: "Missing key/value separator", Detail: "Expected an equals sign (\"=\") to mark the beginning of the attribute value. If you intended to given an attribute name containing periods or spaces, write the name in quotes to create a string literal.", Subject: &r})
				case TokenEOF:
					or := open.Range
					diags = append(diags, &Diagnostic{Summary: "Unterminated object constructor expression", Detail: "There is no corresponding closing brace before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.", Subject: &or})
				default:
					diags = append(diags, &Diagnostic{Summary: "Missing key/value separator", Detail: "Expected an equals sign (\"=\") to mark the beginning of the attribute value.", Subject: &r})
				}
			}
			cl = p.recover(TokenCBrace)
			break
		}
		p.Read()
		value, valueDiags := p.ParseExpression()
		diags = append(diags, valueDiags...)
		if p.recovery && valueDiags.HasErrors() {
			cl = p.recover(TokenCBrace)
			break
		}
		items = append(items, ObjectConsItem{KeyExpr: key, ValueExpr: value})
		next = p.Peek()
		if next.Type == TokenCBrace {
			cl = p.Read()
			break
		}
		if next.Type != TokenComma && next.Type != TokenNewline {
			if !p.recovery {
				r := next.Range
				switch next.Type {
				case TokenEOF:
					or := open.Range
					diags = append(diags, &Diagnostic{Summary: "Unterminated object constructor expression", Detail: "There is no corresponding closing brace before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.", Subject: &or})
				default:
					diags = append(diags, &Diagnostic{Summary: "Missing attribute separator", Detail: "Expected a newline or comma to mark the beginning of the next attribute.", Subject: &r})
				}
			}
			cl = p.recover(TokenCBrace)
			break
		}
		p.Read()
	}
	return &ObjectConsExpr{Items: items, SrcRange: RangeBetween(open.Range, cl.Range), OpenRange: open.Range}, diags
}

func (p *parser) finishParsingForExpr(open Token) (Expression, Diagnostics) {
	p.PushIncludeNewlines(false)
	defer p.PopIncludeNewlines()
	introducer := p.Read() // "for"
	var makeObj bool
	var closeType TokenType
	switch open.Type {
	case TokenOBrace:
		makeObj = true
		closeType = TokenCBrace
	case TokenOBrack:
		closeType = TokenCBrack
	}
	var diags Diagnostics
	var keyName, valName string
	if p.Peek().Type != TokenIdent {
		if !p.recovery {
			r := p.Peek().Range
			diags = append(diags, &Diagnostic{Summary: "Invalid 'for' expression", Detail: "For expression requires variable name after 'for'.", Subject: &r})
		}
		cl := p.recover(closeType)
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, cl.Range)}, diags
	}
	valName = string(p.Read().Bytes)
	if p.Peek().Type == TokenComma {
		keyName = valName
		p.Read()
		if p.Peek().Type != TokenIdent {
			if !p.recovery {
				r := p.Peek().Range
				diags = append(diags, &Diagnostic{Summary: "Invalid 'for' expression", Detail: "For expression requires value variable name after comma.", Subject: &r})
			}
			cl := p.recover(closeType)
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, cl.Range)}, diags
		}
		valName = string(p.Read().Bytes)
	}
	if !isKeyword(p.Peek(), "in") {
		if !p.recovery {
			r := p.Peek().Range
			diags = append(diags, &Diagnostic{Summary: "Invalid 'for' expression", Detail: "For expression requires the 'in' keyword after its name declarations.", Subject: &r})
		}
		cl := p.recover(closeType)
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, cl.Range)}, diags
	}
	p.Read()
	collExpr, collDiags := p.ParseExpression()
	diags = append(diags, collDiags...)
	if p.recovery && collDiags.HasErrors() {
		cl := p.recover(closeType)
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, cl.Range)}, diags
	}
	if p.Peek().Type != TokenColon {
		if !p.recovery {
			r := p.Peek().Range
			diags = append(diags, &Diagnostic{Summary: "Invalid 'for' expression", Detail: "The 'in' clause of a for expression must be followed by a colon.", Subject: &r})
		}
		cl := p.recover(closeType)
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, cl.Range)}, diags
	}
	p.Read()
	var keyExpr, valExpr Expression
	var keyDiags, valDiags Diagnostics
	valExpr, valDiags = p.ParseExpression()
	if p.Peek().Type == TokenFatArrow {
		if !makeObj {
			r := p.Peek().Range
			valDiags = append(valDiags, &Diagnostic{Summary: "Invalid 'for' expression", Detail: "Key expression is not valid when building a tuple.", Subject: &r})
		}
		p.Read()
		keyExpr, keyDiags = valExpr, valDiags
		valExpr, valDiags = p.ParseExpression()
	}
	diags = append(diags, keyDiags...)
	diags = append(diags, valDiags...)
	if p.recovery && (keyDiags.HasErrors() || valDiags.HasErrors()) {
		cl := p.recover(closeType)
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, cl.Range)}, diags
	}
	group := false
	if p.Peek().Type == TokenEllipsis {
		group = true
		p.Read()
	}
	var condExpr Expression
	if isKeyword(p.Peek(), "if") {
		p.Read()
		var condDiags Diagnostics
		condExpr, condDiags = p.ParseExpression()
		diags = append(diags, condDiags...)
		if p.recovery && condDiags.HasErrors() {
			cl := p.recover(p.oppositeBracket(open.Type))
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, cl.Range)}, diags
		}
	}
	var cl Token
	if p.Peek().Type == closeType {
		cl = p.Read()
	} else {
		if !p.recovery {
			r := p.Peek().Range
			diags = append(diags, &Diagnostic{Summary: "Invalid 'for' expression", Detail: "Extra characters after the end of the 'for' expression.", Subject: &r})
		}
		cl = p.recover(closeType)
	}
	if !makeObj {
		if keyExpr != nil {
			keyExpr = nil
		}
		if group {
			group = false
		}
	} else if keyExpr == nil {
		if !p.recovery {
			r := valExpr.Range()
			diags = append(diags, &Diagnostic{Summary: "Invalid 'for' expression", Detail: "Key expression is required when building an object.", Subject: &r})
		}
	}
	_ = introducer
	return &ForExpr{KeyVar: keyName, ValVar: valName, CollExpr: collExpr, KeyExpr: keyExpr, ValExpr: valExpr, CondExpr: condExpr, Group: group, SrcRange: RangeBetween(open.Range, cl.Range), OpenRange: open.Range, CloseRange: cl.Range}, diags
}

func (p *parser) parseQuotedStringLiteral() (string, Range, Diagnostics) {
	oQuote := p.Read()
	if oQuote.Type != TokenOQuote {
		r := oQuote.Range
		return "", oQuote.Range, Diagnostics{{Summary: "Invalid string literal", Detail: "A string literal is expected here.", Subject: &r}}
	}
	var diags Diagnostics
	var ret bytes.Buffer
	var endRange Range
Token:
	for {
		tok := p.Read()
		switch tok.Type {
		case TokenCQuote:
			endRange = tok.Range
			break Token
		case TokenQuotedLit:
			s, sDiags := ParseStringLiteralToken(tok)
			diags = append(diags, sDiags...)
			ret.WriteString(s)
		case TokenTemplateControl, TokenTemplateInterp:
			which := "$"
			if tok.Type == TokenTemplateControl {
				which = "%"
			}
			r := tok.Range
			diags = append(diags, &Diagnostic{Summary: "Invalid string literal", Detail: fmt.Sprintf("Template sequences are not allowed in this string. To include a literal %q, double it (as \"%s%s\") to escape it.", which, which, which), Subject: &r})
			ret.WriteString(which)
			ret.WriteString("{ ... }")
			p.recover(TokenTemplateSeqEnd)
		case TokenEOF:
			r := tok.Range
			diags = append(diags, &Diagnostic{Summary: "Unterminated string literal", Detail: "Unable to find the closing quote mark before the end of the file.", Subject: &r})
			endRange = tok.Range
			break Token
		default:
			r := tok.Range
			diags = append(diags, &Diagnostic{Summary: "Invalid string literal", Detail: "This item is not valid in a string literal.", Subject: &r})
			p.recover(TokenCQuote)
			endRange = tok.Range
			break Token
		}
	}
	return ret.String(), RangeBetween(oQuote.Range, endRange), diags
}

// ParseStringLiteralToken decodes a quoted or string literal token.
func ParseStringLiteralToken(tok Token) (string, Diagnostics) {
	var quoted bool
	switch tok.Type {
	case TokenQuotedLit:
		quoted = true
	case TokenStringLit:
		quoted = false
	}
	buf := tok.Bytes
	var ret strings.Builder
	var diags Diagnostics
	i := 0
	for i < len(buf) {
		c := buf[i]
		if quoted && c == '\\' {
			if i+1 >= len(buf) {
				r := tok.Range
				diags = append(diags, &Diagnostic{Summary: "Invalid escape sequence", Detail: "Backslash must be followed by an escape sequence selector character.", Subject: &r})
				break
			}
			e := buf[i+1]
			switch e {
			case 'n':
				ret.WriteByte('\n')
				i += 2
				continue
			case 'r':
				ret.WriteByte('\r')
				i += 2
				continue
			case 't':
				ret.WriteByte('\t')
				i += 2
				continue
			case '"':
				ret.WriteByte('"')
				i += 2
				continue
			case '\\':
				ret.WriteByte('\\')
				i += 2
				continue
			case 'u', 'U':
				n := 4
				if e == 'U' {
					n = 8
				}
				if i+2+n <= len(buf) {
					var cp rune
					ok := true
					for _, h := range buf[i+2 : i+2+n] {
						cp <<= 4
						switch {
						case h >= '0' && h <= '9':
							cp |= rune(h - '0')
						case h >= 'a' && h <= 'f':
							cp |= rune(h-'a') + 10
						case h >= 'A' && h <= 'F':
							cp |= rune(h-'A') + 10
						default:
							ok = false
						}
					}
					if ok {
						ret.WriteRune(cp)
						i += 2 + n
						continue
					}
				}
				r := tok.Range
				diags = append(diags, &Diagnostic{Summary: "Invalid escape sequence", Detail: fmt.Sprintf("The \\%c escape sequence must be followed by %d hexadecimal digits.", e, n), Subject: &r})
				i += 2
				continue
			default:
				r := tok.Range
				diags = append(diags, &Diagnostic{Summary: "Invalid escape sequence", Detail: fmt.Sprintf("The symbol %q is not a valid escape sequence selector.", string(e)), Subject: &r})
				ret.WriteByte(e)
				i += 2
				continue
			}
		}
		if (c == '$' || c == '%') && i+2 < len(buf) && buf[i+1] == c && buf[i+2] == '{' {
			ret.WriteByte(c)
			ret.WriteByte('{')
			i += 3
			continue
		}
		ret.WriteByte(c)
		i++
	}
	return ret.String(), diags
}

// template parsing

type templateToken interface{}

type templateLiteralToken struct {
	Val      string
	SrcRange Range
}
type templateInterpToken struct {
	Expr     Expression
	SrcRange Range
}
type templateIfToken struct {
	CondExpr Expression
	SrcRange Range
}
type templateForToken struct {
	KeyVar, ValVar string
	CollExpr       Expression
	SrcRange       Range
}
type templateEndCtrlType int

const (
	templateEndIf templateEndCtrlType = iota
	templateElse
	templateEndFor
)

type templateEndCtrlToken struct {
	Type     templateEndCtrlType
	SrcRange Range
}
type templateEndToken struct {
	SrcRange Range
}

func (p *parser) parseTemplateInner(end TokenType, flushHeredoc bool) ([]Expression, bool, Diagnostics) {
	parts, diags := p.parseTemplateParts(end)
	if flushHeredoc {
		flushHeredocTemplateParts(parts)
	}
	tp := &templateParser{tokens: parts}
	exprs, passthru, more := tp.parse()
	diags = append(diags, more...)
	return exprs, passthru, diags
}

func flushHeredocTemplateParts(parts []templateToken) {
	if len(parts) == 0 {
		return
	}
	const maxInt = int(^uint(0) >> 1)
	minSpaces := maxInt
	newline := true
	var adjust []*templateLiteralToken
	for _, ttok := range parts {
		if newline {
			newline = false
			var spaces int
			if lit, ok := ttok.(*templateLiteralToken); ok {
				orig := lit.Val
				trimmed := strings.TrimLeftFunc(orig, unicode.IsSpace)
				spaces = len(orig) - len(trimmed)
				if trimmed == "" || trimmed == "\n" {
					// blank line
					if strings.HasSuffix(orig, "\n") {
						newline = true
					}
					adjust = append(adjust, lit)
					continue
				}
				adjust = append(adjust, lit)
			} else if _, ok := ttok.(*templateEndToken); ok {
				break
			} else {
				spaces = 0
			}
			if spaces < minSpaces {
				minSpaces = spaces
			}
		}
		if lit, ok := ttok.(*templateLiteralToken); ok {
			if strings.HasSuffix(lit.Val, "\n") {
				newline = true
			}
		}
	}
	if minSpaces == maxInt {
		minSpaces = 0
	}
	for _, lit := range adjust {
		if len(lit.Val) >= minSpaces {
			lit.Val = lit.Val[minSpaces:]
		} else {
			lit.Val = strings.TrimLeftFunc(lit.Val, unicode.IsSpace)
		}
	}
}

func (p *parser) parseTemplateParts(end TokenType) ([]templateToken, Diagnostics) {
	var parts []templateToken
	var diags Diagnostics
	startRange := p.NextRange()
	ltrimNext := false
	nextCanTrimPrev := false
Token:
	for {
		next := p.Read()
		if next.Type == end {
			parts = append(parts, &templateEndToken{SrcRange: next.Range})
			break
		}
		ltrim := ltrimNext
		ltrimNext = false
		canTrimPrev := nextCanTrimPrev
		nextCanTrimPrev = false
		switch next.Type {
		case TokenStringLit, TokenQuotedLit:
			str, strDiags := ParseStringLiteralToken(next)
			diags = append(diags, strDiags...)
			if ltrim {
				str = strings.TrimLeftFunc(str, unicode.IsSpace)
			}
			parts = append(parts, &templateLiteralToken{Val: str, SrcRange: next.Range})
			nextCanTrimPrev = true
		case TokenTemplateInterp:
			if canTrimPrev && len(next.Bytes) == 3 && next.Bytes[2] == '~' && len(parts) > 0 {
				if l, ok := parts[len(parts)-1].(*templateLiteralToken); ok {
					l.Val = strings.TrimRightFunc(l.Val, unicode.IsSpace)
				}
			}
			p.PushIncludeNewlines(false)
			expr, exprDiags := p.ParseExpression()
			diags = append(diags, exprDiags...)
			cl := p.Peek()
			if cl.Type != TokenTemplateSeqEnd {
				if !p.recovery {
					switch cl.Type {
					case TokenEOF:
						sr := startRange
						diags = append(diags, &Diagnostic{Summary: "Unclosed template interpolation sequence", Detail: "There is no closing brace for this interpolation sequence before the end of the file. This might be caused by incorrect nesting inside the given expression.", Subject: &sr})
					case TokenColon:
						r := cl.Range
						diags = append(diags, &Diagnostic{Summary: "Extra characters after interpolation expression", Detail: "Template interpolation doesn't expect a colon at this location. Did you intend this to be a literal sequence to be processed as part of another language? If so, you can escape it by starting with \"$${\" instead of just \"${\".", Subject: &r})
					default:
						if (cl.Type == TokenCQuote || cl.Type == TokenOQuote) && end == TokenCQuote {
							sr := startRange
							diags = append(diags, &Diagnostic{Summary: "Unclosed template interpolation sequence", Detail: "There is no closing brace for this interpolation sequence before the end of the quoted template. This might be caused by incorrect nesting inside the given expression.", Subject: &sr})
						} else {
							r := cl.Range
							diags = append(diags, &Diagnostic{Summary: "Extra characters after interpolation expression", Detail: "Expected a closing brace to end the interpolation expression, but found extra characters.\n\nThis can happen when you include interpolation syntax for another language, such as shell scripting, but forget to escape the interpolation start token. If this is an embedded sequence for another language, escape it by starting with \"$${\" instead of just \"${\".", Subject: &r})
						}
					}
				}
				p.recover(TokenTemplateSeqEnd)
			} else {
				p.Read()
				if len(cl.Bytes) == 2 && cl.Bytes[0] == '~' {
					ltrimNext = true
				}
			}
			p.PopIncludeNewlines()
			parts = append(parts, &templateInterpToken{Expr: expr, SrcRange: RangeBetween(next.Range, cl.Range)})
		case TokenTemplateControl:
			if canTrimPrev && len(next.Bytes) == 3 && next.Bytes[2] == '~' && len(parts) > 0 {
				if l, ok := parts[len(parts)-1].(*templateLiteralToken); ok {
					l.Val = strings.TrimRightFunc(l.Val, unicode.IsSpace)
				}
			}
			p.PushIncludeNewlines(false)
			kw := p.Peek()
			if kw.Type != TokenIdent {
				if !p.recovery {
					r := kw.Range
					diags = append(diags, &Diagnostic{Summary: "Invalid template directive", Detail: "A template directive keyword (\"if\", \"for\", etc) is expected at the beginning of a %{ sequence.", Subject: &r})
				}
				p.recover(TokenTemplateSeqEnd)
				p.PopIncludeNewlines()
				continue Token
			}
			p.Read()
			switch string(kw.Bytes) {
			case "if":
				condExpr, exprDiags := p.ParseExpression()
				diags = append(diags, exprDiags...)
				parts = append(parts, &templateIfToken{CondExpr: condExpr, SrcRange: RangeBetween(next.Range, p.NextRange())})
			case "else":
				parts = append(parts, &templateEndCtrlToken{Type: templateElse, SrcRange: RangeBetween(next.Range, p.NextRange())})
			case "endif":
				parts = append(parts, &templateEndCtrlToken{Type: templateEndIf, SrcRange: RangeBetween(next.Range, p.NextRange())})
			case "for":
				var keyName, valName string
				if p.Peek().Type != TokenIdent {
					if !p.recovery {
						r := p.Peek().Range
						diags = append(diags, &Diagnostic{Summary: "Invalid 'for' directive", Detail: "For directive requires variable name after 'for'.", Subject: &r})
					}
					p.recover(TokenTemplateSeqEnd)
					p.PopIncludeNewlines()
					continue Token
				}
				valName = string(p.Read().Bytes)
				if p.Peek().Type == TokenComma {
					keyName = valName
					p.Read()
					if p.Peek().Type != TokenIdent {
						if !p.recovery {
							r := p.Peek().Range
							diags = append(diags, &Diagnostic{Summary: "Invalid 'for' directive", Detail: "For directive requires value variable name after comma.", Subject: &r})
						}
						p.recover(TokenTemplateSeqEnd)
						p.PopIncludeNewlines()
						continue Token
					}
					valName = string(p.Read().Bytes)
				}
				if !isKeyword(p.Peek(), "in") {
					if !p.recovery {
						r := p.Peek().Range
						diags = append(diags, &Diagnostic{Summary: "Invalid 'for' directive", Detail: "For directive requires 'in' keyword after names.", Subject: &r})
					}
					p.recover(TokenTemplateSeqEnd)
					p.PopIncludeNewlines()
					continue Token
				}
				p.Read()
				collExpr, collDiags := p.ParseExpression()
				diags = append(diags, collDiags...)
				parts = append(parts, &templateForToken{KeyVar: keyName, ValVar: valName, CollExpr: collExpr, SrcRange: RangeBetween(next.Range, p.NextRange())})
			case "endfor":
				parts = append(parts, &templateEndCtrlToken{Type: templateEndFor, SrcRange: RangeBetween(next.Range, p.NextRange())})
			default:
				if !p.recovery {
					given := string(kw.Bytes)
					suggestion := nameSuggestion(given, []string{"if", "for", "else", "endif", "endfor"})
					if suggestion != "" {
						suggestion = fmt.Sprintf(" Did you mean %q?", suggestion)
					}
					r := kw.Range
					diags = append(diags, &Diagnostic{Summary: "Invalid template control keyword", Detail: fmt.Sprintf("%q is not a valid template control keyword.%s", given, suggestion), Subject: &r})
				}
				p.recover(TokenTemplateSeqEnd)
				p.PopIncludeNewlines()
				continue Token
			}
			cl := p.Peek()
			if cl.Type != TokenTemplateSeqEnd {
				if !p.recovery {
					r := cl.Range
					diags = append(diags, &Diagnostic{Summary: fmt.Sprintf("Extra characters in %s marker", kw.Bytes), Detail: "Expected a closing brace to end the sequence, but found extra characters.", Subject: &r})
				}
				p.recover(TokenTemplateSeqEnd)
			} else {
				p.Read()
				if len(cl.Bytes) == 2 && cl.Bytes[0] == '~' {
					ltrimNext = true
				}
			}
			p.PopIncludeNewlines()
		default:
			if !p.recovery {
				switch next.Type {
				case TokenEOF:
					sr := startRange
					diags = append(diags, &Diagnostic{Summary: "Unterminated template string", Detail: "No closing marker was found for the string.", Subject: &sr})
				default:
					r := next.Range
					diags = append(diags, &Diagnostic{Summary: "Unexpected token in template", Detail: "This token is not valid within a template.", Subject: &r})
				}
			}
			p.recover(end)
			break Token
		}
	}
	return parts, diags
}

type templateParser struct {
	tokens []templateToken
	pos    int
}

func (tp *templateParser) peek() templateToken {
	if tp.pos >= len(tp.tokens) {
		return nil
	}
	return tp.tokens[tp.pos]
}

func (tp *templateParser) read() templateToken {
	t := tp.peek()
	tp.pos++
	return t
}

func (tp *templateParser) parse() ([]Expression, bool, Diagnostics) {
	var diags Diagnostics
	var exprs []Expression
	// passthru: single interpolation, no literals
	nonEnd := 0
	for _, t := range tp.tokens {
		if _, ok := t.(*templateEndToken); !ok {
			nonEnd++
		}
	}
	if nonEnd == 1 {
		if it, ok := tp.tokens[0].(*templateInterpToken); ok {
			return []Expression{it.Expr}, true, nil
		}
	}
	for {
		next := tp.peek()
		if next == nil {
			break
		}
		if _, isEnd := next.(*templateEndToken); isEnd {
			tp.read()
			break
		}
		expr, d := tp.parseExpr()
		diags = append(diags, d...)
		if expr != nil {
			exprs = append(exprs, expr)
		}
	}
	if len(exprs) == 0 {
		exprs = append(exprs, &LiteralValueExpr{Val: StringVal("")})
	}
	return exprs, false, diags
}

func (tp *templateParser) parseExpr() (Expression, Diagnostics) {
	next := tp.read()
	switch t := next.(type) {
	case *templateLiteralToken:
		return &LiteralValueExpr{Val: StringVal(t.Val), SrcRange: t.SrcRange}, nil
	case *templateInterpToken:
		return t.Expr, nil
	case *templateIfToken:
		var trueParts, falseParts []Expression
		var diags Diagnostics
		inElse := false
	Loop:
		for {
			n := tp.peek()
			switch nt := n.(type) {
			case nil, *templateEndToken:
				r := t.SrcRange
				diags = append(diags, &Diagnostic{Summary: "Unterminated template string", Detail: "Missing endif for this if.", Subject: &r})
				break Loop
			case *templateEndCtrlToken:
				tp.read()
				if nt.Type == templateElse && !inElse {
					inElse = true
					continue
				}
				if nt.Type == templateEndIf {
					break Loop
				}
				r := nt.SrcRange
				diags = append(diags, &Diagnostic{Summary: "Unexpected end of template", Detail: "Unexpected template control.", Subject: &r})
				break Loop
			default:
				e, d := tp.parseExpr()
				diags = append(diags, d...)
				if inElse {
					falseParts = append(falseParts, e)
				} else {
					trueParts = append(trueParts, e)
				}
			}
		}
		te := &TemplateExpr{Parts: trueParts, SrcRange: t.SrcRange}
		if len(trueParts) == 0 {
			te.Parts = []Expression{&LiteralValueExpr{Val: StringVal("")}}
		}
		fe := &TemplateExpr{Parts: falseParts, SrcRange: t.SrcRange}
		if len(falseParts) == 0 {
			fe.Parts = []Expression{&LiteralValueExpr{Val: StringVal("")}}
		}
		return &ConditionalExpr{Condition: t.CondExpr, TrueResult: te, FalseResult: fe, SrcRange: t.SrcRange}, diags
	case *templateForToken:
		var body []Expression
		var diags Diagnostics
	Loop2:
		for {
			n := tp.peek()
			switch nt := n.(type) {
			case nil, *templateEndToken:
				r := t.SrcRange
				diags = append(diags, &Diagnostic{Summary: "Unterminated template string", Detail: "Missing endfor for this for.", Subject: &r})
				break Loop2
			case *templateEndCtrlToken:
				tp.read()
				if nt.Type == templateEndFor {
					break Loop2
				}
				r := nt.SrcRange
				diags = append(diags, &Diagnostic{Summary: "Unexpected end of template", Detail: "Unexpected template control.", Subject: &r})
				break Loop2
			default:
				e, d := tp.parseExpr()
				diags = append(diags, d...)
				body = append(body, e)
			}
		}
		be := &TemplateExpr{Parts: body, SrcRange: t.SrcRange}
		if len(body) == 0 {
			be.Parts = []Expression{&LiteralValueExpr{Val: StringVal("")}}
		}
		fe := &ForExpr{KeyVar: t.KeyVar, ValVar: t.ValVar, CollExpr: t.CollExpr, ValExpr: be, SrcRange: t.SrcRange, OpenRange: t.SrcRange, CloseRange: t.SrcRange}
		return &TemplateJoinExpr{Tuple: fe}, diags
	case *templateEndCtrlToken:
		r := t.SrcRange
		name := map[templateEndCtrlType]string{templateEndIf: "endif", templateElse: "else", templateEndFor: "endfor"}[t.Type]
		return nil, Diagnostics{{Summary: fmt.Sprintf("Unexpected %s directive", name), Detail: "The control directive is not expected here.", Subject: &r}}
	}
	return nil, nil
}

func nameSuggestion(given string, suggestions []string) string {
	for _, s := range suggestions {
		if levenshtein(given, s) < 3 {
			return s
		}
	}
	return ""
}

func levenshtein(a, b string) int {
	ra, rb := []rune(a), []rune(b)
	prev := make([]int, len(rb)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ra); i++ {
		cur := make([]int, len(rb)+1)
		cur[0] = i
		for j := 1; j <= len(rb); j++ {
			cost := 1
			if ra[i-1] == rb[j-1] {
				cost = 0
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		prev = cur
	}
	return prev[len(rb)]
}

func min3(a, b, c int) int {
	if b < a {
		a = b
	}
	if c < a {
		a = c
	}
	return a
}
