package hcl

import (
	"fmt"
	"math/big"
	"sort"
	"strings"
)

// Function is a callable HCL function.
type Function struct {
	// Params is the number of fixed params; -1 for variadic.
	Params   []string
	VarParam string
	Impl     func(args []Value, ctx *EvalContext, rng Range) (Value, Diagnostics)
}

// EvalContext holds variables and functions.
type EvalContext struct {
	Variables map[string]Value
	Functions map[string]*Function
	VarOrder  []string
	parent    *EvalContext
	// UnknownRootHook allows customizing unknown root errors.
	UnknownRoot func(name string, rng Range) (Value, Diagnostics, bool)
}

// NewChild creates a child context.
func (c *EvalContext) NewChild() *EvalContext { return &EvalContext{parent: c} }

// Parent returns the parent context.
func (c *EvalContext) Parent() *EvalContext { return c.parent }

func (c *EvalContext) lookupVar(name string) (Value, bool, []string, bool) {
	var suggestions []string
	hasNonNil := false
	for ctx := c; ctx != nil; ctx = ctx.parent {
		if ctx.Variables == nil {
			continue
		}
		hasNonNil = true
		if v, ok := ctx.Variables[name]; ok {
			return v, true, nil, true
		}
		if len(ctx.VarOrder) > 0 {
			suggestions = append(suggestions, ctx.VarOrder...)
		} else {
			keys := make([]string, 0, len(ctx.Variables))
			for k := range ctx.Variables {
				keys = append(keys, k)
			}
			sort.Strings(keys)
			suggestions = append(suggestions, keys...)
		}
	}
	return Value{}, false, suggestions, hasNonNil
}

func (c *EvalContext) lookupFunc(name string) (*Function, bool, bool) {
	hasNonNil := false
	for ctx := c; ctx != nil; ctx = ctx.parent {
		if ctx.Functions == nil {
			continue
		}
		hasNonNil = true
		if f, ok := ctx.Functions[name]; ok {
			return f, true, true
		}
	}
	return nil, false, hasNonNil
}

func diag(summary, detail string, r Range) Diagnostics {
	return Diagnostics{{Summary: summary, Detail: detail, Subject: &r}}
}

// Eval evaluates an expression.
func Eval(e Expression, ctx *EvalContext) (Value, Diagnostics) {
	switch e := e.(type) {
	case *LiteralValueExpr:
		return e.Val, nil
	case *ParenthesesExpr:
		return Eval(e.Expression, ctx)
	case *TemplateWrapExpr:
		return Eval(e.Wrapped, ctx)
	case *TemplateExpr:
		var buf strings.Builder
		var diags Diagnostics
		unknown := false
		for _, part := range e.Parts {
			v, d := Eval(part, ctx)
			diags = append(diags, d...)
			if d.HasErrors() {
				continue
			}
			if v.T == TNull {
				diags = append(diags, diag("Invalid template interpolation value", "The expression result is null. Cannot include a null value in a string template.", part.Range())...)
				continue
			}
			if v.T == TUnknown {
				unknown = true
				continue
			}
			s, err := ToString(v)
			if err != nil {
				diags = append(diags, diag("Invalid template interpolation value", fmt.Sprintf("Cannot include the given value in a string template: %s.", err), part.Range())...)
				continue
			}
			buf.WriteString(s)
		}
		if diags.HasErrors() || unknown {
			return UnknownVal, diags
		}
		return StringVal(buf.String()), nil
	case *TemplateJoinExpr:
		v, diags := Eval(e.Tuple, ctx)
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		var buf strings.Builder
		for _, x := range v.L {
			s, err := ToString(x)
			if err == nil {
				buf.WriteString(s)
			}
		}
		return StringVal(buf.String()), nil
	case *ScopeTraversalExpr:
		return evalTraversal(e.Traversal, ctx)
	case *RelativeTraversalExpr:
		src, diags := Eval(e.Source, ctx)
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		v, d := traverseRel(src, e.Traversal)
		return v, append(diags, d...)
	case *FunctionCallExpr:
		return evalCall(e, ctx)
	case *ConditionalExpr:
		cond, diags := Eval(e.Condition, ctx)
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		if cond.T != TBool {
			return UnknownVal, diag("Incorrect condition type", "The condition expression must be of type bool.", e.Condition.Range())
		}
		if cond.B {
			return Eval(e.TrueResult, ctx)
		}
		return Eval(e.FalseResult, ctx)
	case *UnaryOpExpr:
		v, diags := Eval(e.Val, ctx)
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		switch e.Op {
		case OpNegate:
			n, err := ToNumber(v)
			if err != nil {
				return UnknownVal, diag("Invalid operand", fmt.Sprintf("Unsuitable value for unary operand: %s.", err), e.Val.Range())
			}
			return NumberVal(new(big.Float).SetPrec(512).Neg(n.N)), nil
		case OpLogicalNot:
			b, err := ToBool(v)
			if err != nil {
				return UnknownVal, diag("Invalid operand", fmt.Sprintf("Unsuitable value for unary operand: %s.", err), e.Val.Range())
			}
			return BoolVal(!b.B), nil
		}
	case *BinaryOpExpr:
		return evalBinary(e, ctx)
	case *TupleConsExpr:
		var diags Diagnostics
		vals := make([]Value, 0, len(e.Exprs))
		for _, x := range e.Exprs {
			v, d := Eval(x, ctx)
			diags = append(diags, d...)
			vals = append(vals, v)
		}
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		return TupleVal(vals), nil
	case *ObjectConsExpr:
		var diags Diagnostics
		m := map[string]Value{}
		for _, item := range e.Items {
			k, d := Eval(item.KeyExpr, ctx)
			diags = append(diags, d...)
			v, d2 := Eval(item.ValueExpr, ctx)
			diags = append(diags, d2...)
			if d.HasErrors() || d2.HasErrors() {
				continue
			}
			if k.T == TNull {
				diags = append(diags, diag("Null value as key", "Can't use a null value as a key.", item.KeyExpr.Range())...)
				continue
			}
			ks, err := ToString(k)
			if err != nil {
				diags = append(diags, diag("Incorrect key type", fmt.Sprintf("Can't use this value as a key: %s.", err), item.KeyExpr.Range())...)
				continue
			}
			m[ks] = v
		}
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		return ObjectVal(m), nil
	case *ObjectConsKeyExpr:
		if !e.ForceNonLiteral {
			if st, ok := e.Wrapped.(*ScopeTraversalExpr); ok && len(st.Traversal) == 1 {
				return StringVal(st.Traversal.RootName()), nil
			}
		}
		return Eval(e.Wrapped, ctx)
	case *ForExpr:
		return evalFor(e, ctx)
	case *IndexExpr:
		coll, diags := Eval(e.Collection, ctx)
		key, d := Eval(e.Key, ctx)
		diags = append(diags, d...)
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		return index(coll, key, e.BracketRange)
	case *SplatExpr:
		src, diags := Eval(e.Source, ctx)
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		if src.T == TNull {
			return TupleVal(nil), nil
		}
		items := src.L
		if src.T != TTuple {
			items = []Value{src}
		}
		var out []Value
		for _, it := range items {
			child := ctx.NewChild()
			child.anon = &it
			v, d := Eval(e.Each, child)
			diags = append(diags, d...)
			out = append(out, v)
		}
		return TupleVal(out), diags
	case *AnonSymbolExpr:
		for c := ctx; c != nil; c = c.parent {
			if c.anon != nil {
				return *c.anon, nil
			}
		}
		return UnknownVal, nil
	}
	return UnknownVal, diag("Unsupported expression", "This expression is not supported.", e.Range())
}

func evalTraversal(t Traversal, ctx *EvalContext) (Value, Diagnostics) {
	root := t[0].(TraverseRoot)
	if ctx == nil {
		return UnknownVal, diag("Variables not allowed", "Variables may not be used here.", root.SrcRange)
	}
	v, ok, suggestions, hasNonNil := ctx.lookupVar(root.Name)
	if !ok {
		for c := ctx; c != nil; c = c.parent {
			if c.UnknownRoot != nil {
				if v, d, handled := c.UnknownRoot(root.Name, root.SrcRange); handled {
					if d.HasErrors() {
						return v, d
					}
					return traverseRel(v, t[1:])
				}
			}
		}
		if !hasNonNil {
			return UnknownVal, diag("Variables not allowed", "Variables may not be used here.", root.SrcRange)
		}
		s := nameSuggestion(root.Name, suggestions)
		if s != "" {
			s = fmt.Sprintf(" Did you mean %q?", s)
		}
		return UnknownVal, diag("Unknown variable", fmt.Sprintf("There is no variable named %q.%s", root.Name, s), root.SrcRange)
	}
	return traverseRel(v, t[1:])
}

// Traverser hooks for capsule values.
type AttrGetter interface {
	GetAttr(name string, rng Range) (Value, Diagnostics)
}

func traverseRel(v Value, t Traversal) (Value, Diagnostics) {
	for _, step := range t {
		switch s := step.(type) {
		case TraverseAttr:
			if v.T == TCapsule {
				if g, ok := v.Cap.(AttrGetter); ok {
					nv, d := g.GetAttr(s.Name, s.SrcRange)
					if d.HasErrors() {
						return UnknownVal, d
					}
					v = nv
					continue
				}
			}
			if v.T == TUnknown {
				return v, nil
			}
			if v.T == TNull {
				return UnknownVal, diag("Attempt to get attribute from null value", "This value is null, so it does not have any attributes.", s.SrcRange)
			}
			if v.T != TObject {
				return UnknownVal, diag("Unsupported attribute", fmt.Sprintf("Can't access attributes on a primitive-typed value (%s).", v.T.FriendlyName()), s.SrcRange)
			}
			nv, ok := v.M[s.Name]
			if !ok {
				return UnknownVal, diag("Unsupported attribute", fmt.Sprintf("This object does not have an attribute named %q.", s.Name), s.SrcRange)
			}
			v = nv
		case TraverseIndex:
			nv, d := index(v, s.Key, s.SrcRange)
			if d.HasErrors() {
				return UnknownVal, d
			}
			v = nv
		}
	}
	return v, nil
}

func index(coll, key Value, rng Range) (Value, Diagnostics) {
	if coll.T == TUnknown || key.T == TUnknown {
		return UnknownVal, nil
	}
	switch coll.T {
	case TTuple:
		n, err := ToNumber(key)
		if err != nil || !n.N.IsInt() {
			return UnknownVal, diag("Invalid index", "The given key does not identify an element in this collection value: a number is required.", rng)
		}
		i, _ := n.N.Int64()
		if i < 0 || int(i) >= len(coll.L) {
			return UnknownVal, diag("Invalid index", "The given key does not identify an element in this collection value: the given index is greater than or equal to the length of the collection.", rng)
		}
		return coll.L[i], nil
	case TObject:
		k, err := ToString(key)
		if err != nil {
			return UnknownVal, diag("Invalid index", "The given key does not identify an element in this collection value: a string is required.", rng)
		}
		v, ok := coll.M[k]
		if !ok {
			return UnknownVal, diag("Invalid index", "The given key does not identify an element in this collection value.", rng)
		}
		return v, nil
	case TNull:
		return UnknownVal, diag("Attempt to index null value", "This value is null, so it does not have any indices.", rng)
	}
	return UnknownVal, diag("Invalid index", "This value does not have any indices.", rng)
}

func evalCall(e *FunctionCallExpr, ctx *EvalContext) (Value, Diagnostics) {
	if ctx == nil {
		return UnknownVal, diag("Function calls not allowed", "Functions may not be called here.", e.Range())
	}
	f, ok, hasNonNil := ctx.lookupFunc(e.Name)
	if !ok {
		if !hasNonNil {
			return UnknownVal, diag("Function calls not allowed", "Functions may not be called here.", e.Range())
		}
		return UnknownVal, diag("Call to unknown function", fmt.Sprintf("There is no function named %q.", e.Name), RangeBetween(e.NameRange, e.OpenParen))
	}
	var diags Diagnostics
	var args []Value
	for i, a := range e.Args {
		v, d := Eval(a, ctx)
		diags = append(diags, d...)
		if e.ExpandFinal && i == len(e.Args)-1 && v.T == TTuple {
			args = append(args, v.L...)
			continue
		}
		args = append(args, v)
	}
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	if f.VarParam == "" && len(args) != len(f.Params) {
		if len(args) < len(f.Params) {
			missing := f.Params[len(args)]
			qual := ""
			return UnknownVal, diag("Not enough function arguments", fmt.Sprintf("Function %q expects %d argument(s). Missing value for %q.%s", e.Name, len(f.Params), missing, qual), RangeBetween(e.NameRange, e.CloseParen))
		}
		return UnknownVal, diag("Too many function arguments", fmt.Sprintf("Function %q expects only %d argument(s).", e.Name, len(f.Params)), e.Args[len(f.Params)].StartRange())
	}
	if f.VarParam != "" && len(args) < len(f.Params) {
		missing := f.Params[len(args)]
		return UnknownVal, diag("Not enough function arguments", fmt.Sprintf("Function %q expects at least %d argument(s). Missing value for %q.", e.Name, len(f.Params), missing), RangeBetween(e.NameRange, e.CloseParen))
	}
	v, d := f.Impl(args, ctx, RangeBetween(e.NameRange, e.CloseParen))
	return v, append(diags, d...)
}

func evalBinary(e *BinaryOpExpr, ctx *EvalContext) (Value, Diagnostics) {
	l, diags := Eval(e.LHS, ctx)
	r, d := Eval(e.RHS, ctx)
	diags = append(diags, d...)
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	switch e.Op {
	case OpEqual:
		return BoolVal(l.Equals(r)), nil
	case OpNotEqual:
		return BoolVal(!l.Equals(r)), nil
	case OpLogicalAnd, OpLogicalOr:
		lb, err := ToBool(l)
		if err != nil {
			return UnknownVal, diag("Invalid operand", fmt.Sprintf("Unsuitable value for left operand: %s.", err), e.LHS.Range())
		}
		rb, err := ToBool(r)
		if err != nil {
			return UnknownVal, diag("Invalid operand", fmt.Sprintf("Unsuitable value for right operand: %s.", err), e.RHS.Range())
		}
		if e.Op == OpLogicalAnd {
			return BoolVal(lb.B && rb.B), nil
		}
		return BoolVal(lb.B || rb.B), nil
	}
	ln, err := ToNumber(l)
	if err != nil {
		return UnknownVal, diag("Invalid operand", fmt.Sprintf("Unsuitable value for left operand: %s.", err), e.LHS.Range())
	}
	rn, err := ToNumber(r)
	if err != nil {
		return UnknownVal, diag("Invalid operand", fmt.Sprintf("Unsuitable value for right operand: %s.", err), e.RHS.Range())
	}
	a, b := ln.N, rn.N
	res := new(big.Float).SetPrec(512)
	switch e.Op {
	case OpAdd:
		return NumberVal(res.Add(a, b)), nil
	case OpSubtract:
		return NumberVal(res.Sub(a, b)), nil
	case OpMultiply:
		return NumberVal(res.Mul(a, b)), nil
	case OpDivide:
		if b.Sign() == 0 {
			return UnknownVal, diag("Error in function call", "Call to function \"divide\" failed: can't divide by zero.", e.Range())
		}
		return NumberVal(res.Quo(a, b)), nil
	case OpModulo:
		ai, _ := a.Int64()
		bi, _ := b.Int64()
		if bi == 0 {
			return UnknownVal, diag("Error in function call", "Call to function \"modulo\" failed: can't divide by zero.", e.Range())
		}
		return NumberIntVal(ai % bi), nil
	case OpGreaterThan:
		return BoolVal(a.Cmp(b) > 0), nil
	case OpGreaterThanOrEqual:
		return BoolVal(a.Cmp(b) >= 0), nil
	case OpLessThan:
		return BoolVal(a.Cmp(b) < 0), nil
	case OpLessThanOrEqual:
		return BoolVal(a.Cmp(b) <= 0), nil
	}
	return UnknownVal, nil
}

func evalFor(e *ForExpr, ctx *EvalContext) (Value, Diagnostics) {
	coll, diags := Eval(e.CollExpr, ctx)
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	type kv struct{ k, v Value }
	var items []kv
	switch coll.T {
	case TTuple:
		for i, x := range coll.L {
			items = append(items, kv{NumberIntVal(int64(i)), x})
		}
	case TObject:
		for _, k := range coll.Keys() {
			items = append(items, kv{StringVal(k), coll.M[k]})
		}
	default:
		return UnknownVal, diag("Iteration over non-iterable value", "A value of type "+coll.T.FriendlyName()+" cannot be used as the collection in a 'for' expression.", e.CollExpr.Range())
	}
	isObj := e.KeyExpr != nil
	var outL []Value
	outM := map[string]Value{}
	groups := map[string][]Value{}
	for _, it := range items {
		child := ctx.NewChild()
		child.Variables = map[string]Value{}
		if e.KeyVar != "" {
			child.Variables[e.KeyVar] = it.k
		}
		child.Variables[e.ValVar] = it.v
		if e.CondExpr != nil {
			c, d := Eval(e.CondExpr, child)
			diags = append(diags, d...)
			if d.HasErrors() {
				continue
			}
			cb, err := ToBool(c)
			if err != nil {
				diags = append(diags, diag("Invalid 'for' condition", "The 'if' clause value is invalid: "+err.Error()+".", e.CondExpr.Range())...)
				continue
			}
			if !cb.B {
				continue
			}
		}
		if isObj {
			k, d := Eval(e.KeyExpr, child)
			diags = append(diags, d...)
			v, d2 := Eval(e.ValExpr, child)
			diags = append(diags, d2...)
			ks, err := ToString(k)
			if err != nil {
				continue
			}
			if e.Group {
				groups[ks] = append(groups[ks], v)
			} else {
				if _, exists := outM[ks]; exists {
					diags = append(diags, diag("Duplicate object key", fmt.Sprintf("Two different items produced the key %q in this 'for' expression. If duplicates are expected, use the ellipsis (...) after the value expression to enable grouping by key.", ks), e.KeyExpr.Range())...)
					continue
				}
				outM[ks] = v
			}
		} else {
			v, d := Eval(e.ValExpr, child)
			diags = append(diags, d...)
			outL = append(outL, v)
		}
	}
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	if isObj {
		if e.Group {
			for k, g := range groups {
				outM[k] = TupleVal(g)
			}
		}
		return ObjectVal(outM), nil
	}
	return TupleVal(outL), nil
}

// ToString converts a primitive value to a string.
func ToString(v Value) (string, error) {
	switch v.T {
	case TString:
		return v.S, nil
	case TNumber:
		return NumberString(v.N), nil
	case TBool:
		if v.B {
			return "true", nil
		}
		return "false", nil
	case TNull:
		return "", fmt.Errorf("null value")
	}
	return "", fmt.Errorf("string required")
}

// ToNumber converts a value to number.
func ToNumber(v Value) (Value, error) {
	switch v.T {
	case TNumber:
		return v, nil
	case TString:
		f, _, err := big.ParseFloat(strings.TrimSpace(v.S), 10, 512, big.ToNearestEven)
		if err != nil {
			return UnknownVal, fmt.Errorf("a number is required")
		}
		return NumberVal(f), nil
	}
	return UnknownVal, fmt.Errorf("number required")
}

// ToBool converts a value to bool.
func ToBool(v Value) (Value, error) {
	switch v.T {
	case TBool:
		return v, nil
	case TString:
		switch v.S {
		case "true":
			return True, nil
		case "false":
			return False, nil
		}
		return UnknownVal, fmt.Errorf("a bool is required")
	}
	return UnknownVal, fmt.Errorf("bool required")
}
