func fnErr(name string, r Range, format string, args ...interface{}) Diagnostics {
	return diag("Error in function call", fmt.Sprintf("Call to function %q failed: %s.", name, fmt.Sprintf(format, args...)), r)
}

func strFn(name string, params []string, f func(args []string) (Value, error)) *Function {
	return &Function{Params: params, Impl: func(args []Value, _ *EvalContext, r Range) (Value, Diagnostics) {
		ss := make([]string, len(args))
		for i, a := range args {
			s, err := ToString(a)
			if err != nil {
				return UnknownVal, diag("Invalid function argument", fmt.Sprintf("Invalid value for %q parameter: string required.", params[i]), r)
			}
			ss[i] = s
		}
		v, err := f(ss)
		if err != nil {
			return UnknownVal, fnErr(name, r, "%s", err)
		}
		return v, nil
	}}
}

func numArg(v Value) (*big.Float, error) {
	n, err := ToNumber(v)
	if err != nil {
		return nil, err
	}
	return n.N, nil
