func toFloat(v Value) float64 {
	n, err := numArg(v)
	if err != nil {
		return 0
	}
	f, _ := n.Float64()
	return f
}

// ToGo converts a value to a Go value for JSON encoding.
func ToGo(v Value) interface{} {
	switch v.T {
	case TString:
		return v.S
	case TNumber:
		if v.N.IsInt() {
			i, _ := v.N.Int(nil)
			return json.Number(i.String())
		}
		return json.Number(v.N.Text('g', -1))
	case TBool:
		return v.B
	case TTuple:
		out := make([]interface{}, len(v.L))
		for i, x := range v.L {
			out[i] = ToGo(x)
		}
		return out
	case TObject:
		out := map[string]interface{}{}
		for k, x := range v.M {
			out[k] = ToGo(x)
		}
		return out
	}
	return nil
}

// FromGo converts a decoded JSON value to Value.
func FromGo(x interface{}) Value {
	switch x := x.(type) {
	case nil:
		return NullVal
	case string:
		return StringVal(x)
	case bool:
		return BoolVal(x)
	case float64:
		return NumberFloatVal(x)
	case json.Number:
		f, _, _ := big.ParseFloat(string(x), 10, 512, big.ToNearestEven)
		return NumberVal(f)
	case []interface{}:
		l := make([]Value, len(x))
		for i, e := range x {
			l[i] = FromGo(e)
		}
		return TupleVal(l)
	case map[string]interface{}:
		m := map[string]Value{}
		for k, e := range x {
			m[k] = FromGo(e)
		}
		return ObjectVal(m)
	}
	return NullVal
}

func listArg(v Value) []Value {
	if v.T == TTuple {
		return v.L
	}
	return nil
}

