func formatValues(f string, args []Value) (string, error) {
	var buf strings.Builder
	ai := 0
	for i := 0; i < len(f); i++ {
		c := f[i]
		if c != '%' {
			buf.WriteByte(c)
			continue
		}
		i++
		if i >= len(f) {
			return "", fmt.Errorf("format string ends with %%")
		}
		if f[i] == '%' {
			buf.WriteByte('%')
			continue
		}
		j := i
		for j < len(f) && strings.IndexByte("+-# 0123456789.", f[j]) >= 0 {
			j++
		}
		if j >= len(f) {
			return "", fmt.Errorf("unterminated format verb")
		}
		verb := f[j]
		flags := f[i:j]
		i = j
		if ai >= len(args) {
			return "", fmt.Errorf("not enough arguments for %%%c at %d", verb, i)
		}
		a := args[ai]
		ai++
		switch verb {
		case 's':
			s, _ := ToString(a)
			buf.WriteString(fmt.Sprintf("%"+flags+"s", s))
		case 'd':
			n, _ := numArg(a)
			if n == nil {
				return "", fmt.Errorf("unsupported value for %%d")
			}
			iv, _ := n.Int(nil)
			buf.WriteString(fmt.Sprintf("%"+flags+"d", iv))
		case 'f', 'g', 'e':
			n, _ := numArg(a)
			fv, _ := n.Float64()
			buf.WriteString(fmt.Sprintf("%"+flags+string(verb), fv))
		case 'q':
			s, _ := ToString(a)
			buf.WriteString(strconv.Quote(s))
		case 't':
			b, _ := ToBool(a)
			buf.WriteString(fmt.Sprint(b.B))
		case 'v':
			if a.T == TString {
				buf.WriteString(a.S)
			} else {
				bb, _ := json.Marshal(ToGo(a))
				buf.Write(bb)
			}
		default:
			return "", fmt.Errorf("unsupported format verb %q", verb)
		}
	}
	return buf.String(), nil
}
