package main

import (
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"atlasre/internal/hcl"
)

// typeCap is a capsule representing a variable type.
type typeCap struct {
	name string
	elem *typeCap
}

func (t *typeCap) String() string {
	if t.elem != nil {
		return t.name + "(" + t.elem.String() + ")"
	}
	return t.name
}

// refCap is a capsule representing a reference.
type refCap struct{ path string }

// Env is a selected environment from the project file.
type Env struct {
	Name  string
	Attrs map[string]hcl.Value
	// Blocks holds nested blocks evaluated as attributes maps.
	Blocks map[string][]*EnvBlock
	Ranges map[string]hcl.Range
}

// EnvBlock is a nested block inside env.
type EnvBlock struct {
	Labels []string
	Attrs  map[string]hcl.Value
	Blocks map[string][]*EnvBlock
	Ranges map[string]hcl.Range
}

// Project is a loaded project file.
type Project struct {
	Env      *Env
	Filename string
	Lint     *EnvBlock
	Diff     *EnvBlock
}

// cfgError formats a project decoding error.
func specErr(format string, args ...interface{}) error {
	return fmt.Errorf("schemahcl: failed reading spec as *cmdapi.Project: "+format, args...)
}

// configPath resolves the config URL into a file path.
func configPath(raw string) (string, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return "", err
	}
	if u.Scheme == "" {
		return "", fmt.Errorf("missing scheme for config file. Did you mean file://%s?", raw)
	}
	if u.Scheme != "file" {
		return "", fmt.Errorf("unsupported project file driver %q", u.Scheme)
	}
	p := filepath.Join(u.Host, u.Path)
	return p, nil
}

func typeVars() map[string]hcl.Value {
	return map[string]hcl.Value{
		"string": hcl.CapsuleVal(&typeCap{name: "string"}),
		"number": hcl.CapsuleVal(&typeCap{name: "number"}),
		"bool":   hcl.CapsuleVal(&typeCap{name: "bool"}),
		"int":    hcl.CapsuleVal(&typeCap{name: "int"}),
	}
}

func typeFuncs() map[string]*hcl.Function {
	mk := func(name string) *hcl.Function {
		return &hcl.Function{Params: []string{"elem_type"}, Impl: func(args []hcl.Value, _ *hcl.EvalContext, r hcl.Range) (hcl.Value, hcl.Diagnostics) {
			t, ok := args[0].Cap.(*typeCap)
			if !ok {
				return hcl.UnknownVal, hcl.Diagnostics{{Summary: "Invalid function argument", Detail: "Invalid value for \"elem_type\" parameter: type required.", Subject: &r}}
			}
			return hcl.CapsuleVal(&typeCap{name: name, elem: t}), nil
		}}
	}
	return map[string]*hcl.Function{"list": mk("list"), "set": mk("set"), "map": mk("map")}
}

func convertVar(name string, t *typeCap, vals []string, def *hcl.Value) (hcl.Value, error) {
	conv := func(t *typeCap, s string) (hcl.Value, error) {
		switch t.name {
		case "number", "int":
			n, err := hcl.ToNumber(hcl.StringVal(s))
			if err != nil {
				return n, fmt.Errorf("variable %q: a number is required", name)
			}
			return n, nil
		case "bool":
			b, err := hcl.ToBool(hcl.StringVal(s))
			if err != nil {
				return b, fmt.Errorf("variable %q: a bool is required", name)
			}
			return b, nil
		}
		return hcl.StringVal(s), nil
	}
	if t == nil {
		t = &typeCap{name: "string"}
	}
	switch t.name {
	case "list", "set":
		var out []hcl.Value
		for _, s := range vals {
			v, err := conv(t.elem, s)
			if err != nil {
				return v, err
			}
			out = append(out, v)
		}
		return hcl.TupleVal(out), nil
	}
	if len(vals) != 1 {
		return hcl.UnknownVal, fmt.Errorf("variable %q: %s required", name, t.name)
	}
	return conv(t, vals[0])
}

// LoadProject loads the project file and selects the given env.
func LoadProject(cfgURL, envName string, vars *varsFlag) (*Project, error) {
	path, err := configPath(cfgURL)
	if err != nil {
		return nil, err
	}
	src, err := os.ReadFile(path)
	if err != nil {
		if _, serr := os.Stat(path); serr != nil {
			return nil, fmt.Errorf("config file %q was not found: %w", path, serr)
		}
		return nil, err
	}
	f, diags := hcl.ParseConfig(src, path)
	if diags.HasErrors() {
		return nil, diags
	}
	body := f.Body
	base := &hcl.EvalContext{Variables: typeVars(), Functions: hcl.Stdlib()}
	for k, fn := range typeFuncs() {
		base.Functions[k] = fn
	}
	// variables
	varVals := map[string]hcl.Value{}
	for _, b := range body.Blocks {
		if b.Type != "variable" || len(b.Labels) == 0 {
			continue
		}
		name := b.Labels[0]
		for _, a := range b.Body.AttrOrder {
			switch a.Name {
			case "type", "default", "description", "nullable", "sensitive":
			default:
				r := a.NameRange
				return nil, hcl.Diagnostics{{Summary: "Unsupported argument", Detail: fmt.Sprintf("An argument named %q is not expected here.", a.Name), Subject: &r}}
			}
		}
		ta, ok := b.Body.Attributes["type"]
		if !ok {
			r := hcl.Range{Filename: b.Body.SrcRange.Filename, Start: b.Body.SrcRange.Start, End: b.Body.SrcRange.Start}
			return nil, hcl.Diagnostics{{Summary: "Missing required argument", Detail: "The argument \"type\" is required, but no definition was found.", Subject: &r}}
		}
		tv, d := hcl.Eval(ta.Expr, base)
		if d.HasErrors() {
			return nil, d
		}
		tc, _ := tv.Cap.(*typeCap)
		var def *hcl.Value
		if da, ok := b.Body.Attributes["default"]; ok {
			dv, d := hcl.Eval(da.Expr, base)
			if d.HasErrors() {
				return nil, d
			}
			def = &dv
		}
		if vs, ok := vars.values[name]; ok {
			v, err := convertVar(name, tc, vs, def)
			if err != nil {
				return nil, err
			}
			varVals[name] = v
		} else if def != nil {
			varVals[name] = *def
		} else {
			return nil, fmt.Errorf("missing value for required variable %q", name)
		}
	}
	ctx := base.NewChild()
	ctx.Variables = map[string]hcl.Value{
		"var":   hcl.ObjectVal(varVals),
		"atlas": hcl.ObjectVal(map[string]hcl.Value{"env": hcl.StringVal(envName)}),
		"env":   hcl.CapsuleVal(&refCap{path: "env"}),
	}
	// locals
	var localAttrs []*hcl.Attribute
	hasLocals := false
	for _, b := range body.Blocks {
		if b.Type == "locals" {
			hasLocals = true
			localAttrs = append(localAttrs, b.Body.AttrOrder...)
		}
	}
	if hasLocals {
		if err := evalLocals(ctx, localAttrs); err != nil {
			return nil, err
		}
	}
	// top-level attributes and non-env blocks
	for _, a := range body.AttrOrder {
		if _, d := hcl.Eval(a.Expr, ctx); d.HasErrors() {
			return nil, d
		}
	}
	proj := &Project{Filename: path}
	var selected []*hcl.Block
	for _, b := range body.Blocks {
		switch b.Type {
		case "variable", "locals":
			continue
		case "env":
			name := ""
			if len(b.Labels) > 0 {
				name = b.Labels[0]
			}
			if na, ok := b.Body.Attributes["name"]; ok {
				v, d := hcl.Eval(na.Expr, ctx)
				if d.HasErrors() {
					return nil, d
				}
				if v.T != hcl.TString {
					return nil, specErr("value of attr \"name\" cannot be read as string: string value is required")
				}
				name = v.S
			}
			if name == envName && envName != "" {
				selected = append(selected, b)
			}
			continue
		case "lint", "diff":
			eb, err := evalEnvBlock(b, ctx)
			if err != nil {
				return nil, err
			}
			if b.Type == "lint" {
				proj.Lint = eb
			} else {
				proj.Diff = eb
			}
			continue
		}
		if _, err := evalEnvBlock(b, ctx); err != nil {
			return nil, err
		}
	}
	if envName == "" {
		return proj, nil
	}
	switch len(selected) {
	case 0:
		return nil, fmt.Errorf("env %q not defined in config file", envName)
	case 1:
	default:
		return nil, fmt.Errorf("multiple envs found for %q", envName)
	}
	eb, err := evalEnvBlock(selected[0], ctx)
	if err != nil {
		return nil, err
	}
	proj.Env = &Env{Name: envName, Attrs: eb.Attrs, Blocks: eb.Blocks, Ranges: eb.Ranges}
	return proj, nil
}

func evalLocals(ctx *hcl.EvalContext, attrs []*hcl.Attribute) error {
	locals := map[string]hcl.Value{}
	pending := map[string]*hcl.Attribute{}
	for _, a := range attrs {
		pending[a.Name] = a
	}
	ctx.Variables["local"] = hcl.ObjectVal(locals)
	// iterate until fixed point
	for len(pending) > 0 {
		progress := false
		var lastDiags hcl.Diagnostics
		names := make([]string, 0, len(pending))
		for n := range pending {
			names = append(names, n)
		}
		sort.Strings(names)
		for _, n := range names {
			a := pending[n]
			v, d := hcl.Eval(a.Expr, ctx)
			if d.HasErrors() {
				lastDiags = d
				continue
			}
			locals[n] = v
			delete(pending, n)
			progress = true
			ctx.Variables["local"] = hcl.ObjectVal(locals)
		}
		if !progress {
			// re-evaluate the first in source order to get its error
			for _, a := range attrs {
				if _, ok := pending[a.Name]; ok {
					_, d := hcl.Eval(a.Expr, ctx)
					if d.HasErrors() {
						return d
					}
				}
			}
			return lastDiags
		}
	}
	return nil
}

func evalEnvBlock(b *hcl.Block, ctx *hcl.EvalContext) (*EnvBlock, error) {
	eb := &EnvBlock{Labels: b.Labels, Attrs: map[string]hcl.Value{}, Blocks: map[string][]*EnvBlock{}, Ranges: map[string]hcl.Range{}}
	for _, a := range b.Body.AttrOrder {
		v, d := hcl.Eval(a.Expr, ctx)
		if d.HasErrors() {
			return nil, d
		}
		if v.T == hcl.TTuple && len(v.L) > 1 {
			for _, e := range v.L[1:] {
				if e.T != v.L[0].T {
					return nil, fmt.Errorf("%s: mixed list types used in %q attribute", a.SrcRange.String(), a.Name)
				}
			}
		}
		eb.Attrs[a.Name] = v
		eb.Ranges[a.Name] = a.SrcRange
	}
	for _, nb := range b.Body.Blocks {
		cb, err := evalEnvBlock(nb, ctx)
		if err != nil {
			return nil, err
		}
		eb.Blocks[nb.Type] = append(eb.Blocks[nb.Type], cb)
	}
	return eb, nil
}

// String returns a string attribute of the block.
func (b *EnvBlock) String(name string) (string, bool, error) {
	v, ok := b.Attrs[name]
	if !ok || v.T == hcl.TNull {
		return "", false, nil
	}
	return attrString(name, v)
}

func attrString(name string, v hcl.Value) (string, bool, error) {
	switch v.T {
	case hcl.TString:
		return v.S, true, nil
	case hcl.TCapsule:
		switch v.Cap.(type) {
		case *refCap:
			return "", false, specErr("value of attr %q cannot be read as string: incorrect type ref", name)
		case *typeCap:
			return "", false, specErr("value of attr %q cannot be read as string: incorrect type type", name)
		}
	}
	return "", false, specErr("value of attr %q cannot be read as string: string value is required", name)
}

func attrStrings(name string, v hcl.Value) ([]string, error) {
	switch v.T {
	case hcl.TNull:
		return nil, nil
	case hcl.TTuple:
		var out []string
		for _, e := range v.L {
			if e.T != hcl.TString {
				return nil, specErr("cannot read attribute %q of type \"list of %s\" as string list: string value is required", name, e.T.FriendlyName())
			}
			out = append(out, e.S)
		}
		return out, nil
	}
	return nil, specErr("schemahcl: field is of type slice but attr %q is type: %s", name, v.T.FriendlyName())
}

// Block returns the first nested block by type.
func (b *EnvBlock) Block(name string) *EnvBlock {
	if bs := b.Blocks[name]; len(bs) > 0 {
		return bs[0]
	}
	return nil
}

func (e *Env) block() *EnvBlock {
	return &EnvBlock{Attrs: e.Attrs, Blocks: e.Blocks, Ranges: e.Ranges}
}

// envString returns a string attribute from env, or nested path like migration.dir.
func (e *Env) str(path ...string) (string, bool, error) {
	if e == nil {
		return "", false, nil
	}
	b := e.block()
	for _, p := range path[:len(path)-1] {
		v, ok := b.Attrs[p]
		if ok && v.T != hcl.TNull && v.T != hcl.TObject {
			return "", false, specErr("set field %q: converting cty.Value to *cmdapi.%s: object or tuple value is required", p, strings.Title(p))
		}
		b = b.Block(p)
		if b == nil {
			return "", false, nil
		}
	}
	return b.String(path[len(path)-1])
}

func (e *Env) strs(name string) ([]string, bool, error) {
	if e == nil {
		return nil, false, nil
	}
	v, ok := e.Attrs[name]
	if !ok {
		return nil, false, nil
	}
	s, err := attrStrings(name, v)
	return s, ok, err
}

