	}
	// deterministic order
	order := []string{"url", "dev-url", "to", "schema", "exclude", "dir", "dir-format", "revisions-schema", "baseline", "exec-order", "lock-timeout", "format"}
	for _, name := range order {
		path, ok := m[name]
		if !ok {
			continue
		}
		fl := cmd.Flags().Lookup(name)
		if fl == nil || fl.Changed {
			continue
		}
		if name == "format" {
			if lf := cmd.Flags().Lookup("log"); lf != nil && lf.Changed {
				continue
			}
		}
		switch name {
		case "to":
			vals, err := envSrc(env)
			if err != nil {
				return err
			}
			for _, v := range vals {
				if err := cmd.Flags().Set(name, v); err != nil {
					return err
				}
			}
		case "schema", "exclude":
			vals, ok, err := env.strs(path[0])
			if err != nil {
				return err
			}
			if ok {
				for _, v := range vals {
					if err := cmd.Flags().Set(name, v); err != nil {
						return err
					}
				}
			}
		case "lock-timeout":
			s, ok, err := env.str(path...)
			if err != nil {
				return err
			}
			if ok {
				if _, err := time.ParseDuration(s); err != nil {
					return err
				}
				if err := cmd.Flags().Set(name, s); err != nil {
					return err
				}
			}
		default:
			s, ok, err := env.str(path...)
			if err != nil {
				return err
			}
			if ok {
				if err := cmd.Flags().Set(name, s); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

func envSrc(env *Env) ([]string, error) {
	if v, ok := env.Attrs["src"]; ok {
		switch v.T {
		case hcl.TString:
			return []string{v.S}, nil
		case hcl.TTuple:
			var out []string
			for _, e := range v.L {
				if e.T != hcl.TString {
					return nil, fmt.Errorf("expected src to be either a string or strings, got: %s", describeType(v))
				}
				out = append(out, e.S)
			}
			return out, nil
		case hcl.TNull:
		default:
			return nil, fmt.Errorf("expected src to be either a string or strings, got: %s", describeType(v))
		}
	}
	if b := env.block().Block("schema"); b != nil {
		if v, ok := b.Attrs["src"]; ok {
			switch v.T {
			case hcl.TString:
				return []string{v.S}, nil
			case hcl.TTuple:
				var out []string
				for _, e := range v.L {
					if e.T == hcl.TString {
						out = append(out, e.S)
					}
				}
				return out, nil
			}
		}
	}
	return nil, nil
}

func describeType(v hcl.Value) string {
	switch v.T {
	case hcl.TTuple:
		var parts []string
		for _, e := range v.L {
			parts = append(parts, e.T.FriendlyName())
		}
		return "tuple"
	}
	return v.T.FriendlyName()
}

