package main

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"atlasre/internal/hcl"

	"github.com/spf13/cobra"
)

func runSchemaFmt(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		args = []string{"./"}
	}
	for _, p := range args {
		fi, err := os.Stat(p)
		if err != nil {
			return err
		}
		var files []string
		if fi.IsDir() {
			entries, err := os.ReadDir(p)
			if err != nil {
				return err
			}
			for _, e := range entries {
				if e.IsDir() || !strings.HasSuffix(e.Name(), ".hcl") {
					continue
				}
				files = append(files, filepath.Join(p, e.Name()))
			}
		} else if strings.HasSuffix(p, ".hcl") {
			files = append(files, p)
		}
		for _, f := range files {
			changed, err := fmtFile(f)
			if err != nil {
				return err
			}
			if changed {
				fmt.Fprintln(cmd.OutOrStdout(), f)
			}
		}
	}
	return nil
}

func fmtFile(path string) (bool, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return false, err
	}
	out := hcl.Format(b)
	if bytes.Equal(out, b) {
		return false, nil
	}
	st, err := os.Stat(path)
	if err != nil {
		return false, err
	}
	if err := os.WriteFile(path, out, st.Mode()); err != nil {
		return false, err
	}
	return true, nil
}
