#!/usr/bin/env python3
"""Compare original and reimplementation.
usage: cmp.py [--setup 'shell cmds'] [--home fresh|quiet] -- cmd args...
Runs in a temp dir for each binary, with the fixture setup applied."""
import subprocess, sys, os, tempfile, shutil, filecmp, re, argparse

ORIG = '/workspace/executable'
MINE = '/tmp/myatlas'

def run(binary, setup, cmd, home_mode, fixture):
    d = tempfile.mkdtemp(prefix='cmp')
    home = tempfile.mkdtemp(prefix='home')
    if home_mode == 'quiet':
        os.makedirs(home + '/.atlas')
        open(home + '/.atlas/community_error.json', 'w').write('{"last_suggested":"2099-01-01T00:00:00Z"}')
        open(home + '/.atlas/local-community.json', 'w').write('{"v1.us":"2099-01-01T00:00:00Z"}')
    if fixture:
        for f in os.listdir(fixture):
            s = os.path.join(fixture, f)
            if os.path.isdir(s): shutil.copytree(s, os.path.join(d, f))
            else: shutil.copy(s, d)
    env = dict(os.environ, HOME=home, ATLAS=binary)
    if setup:
        subprocess.run(setup, shell=True, cwd=d, env=env, check=False, capture_output=True)
    p = subprocess.run(cmd.replace('ATLAS', binary), shell=True, cwd=d, env=env, capture_output=True, timeout=60)
    return d, p

def tree(d):
    out = {}
    for root, dirs, files in os.walk(d):
        for f in files:
            p = os.path.join(root, f)
            rel = os.path.relpath(p, d)
            if rel.endswith('.db') or rel.endswith('.db-journal'):
                out[rel] = '<db>'
                continue
            try: out[rel] = open(p, 'rb').read()
            except Exception as e: out[rel] = str(e)
    return out

def norm(b, d):
