}
static int bind_blob(sqlite3_stmt *s, int i, const void *v, int n) {
	return sqlite3_bind_blob(s, i, v, n, SQLITE_TRANSIENT);
}
*/
import "C"

import (
	"errors"
	"fmt"
	"strings"
	"unsafe"
)

// Conn is a SQLite connection.
type Conn struct {
	db *C.sqlite3
}

// Error is a SQLite error.
type Error struct {
	Code int
	Msg  string
}

func (e *Error) Error() string { return e.Msg }

// Open opens a SQLite database with the given URI-style DSN.
func Open(dsn string) (*Conn, error) {
	cs := C.CString(dsn)
	defer C.free(unsafe.Pointer(cs))
	var db *C.sqlite3
	flags := C.SQLITE_OPEN_READWRITE | C.SQLITE_OPEN_CREATE | C.SQLITE_OPEN_URI | C.SQLITE_OPEN_FULLMUTEX
	rc := C.sqlite3_open_v2(cs, &db, C.int(flags), nil)
	if rc != C.SQLITE_OK {
		msg := "unable to open database file"
		if db != nil {
			msg = C.GoString(C.sqlite3_errmsg(db))
			C.sqlite3_close_v2(db)
		}
		return nil, &Error{Code: int(rc), Msg: msg}
	}
	C.sqlite3_busy_timeout(db, 5000)
	return &Conn{db: db}, nil
}

// OpenFlags opens a database with explicit flags (readonly etc.).
func OpenFlags(dsn string, readonly bool) (*Conn, error) {
	if !readonly {
		return Open(dsn)
	}
	cs := C.CString(dsn)
	defer C.free(unsafe.Pointer(cs))
	var db *C.sqlite3
	flags := C.SQLITE_OPEN_READONLY | C.SQLITE_OPEN_URI | C.SQLITE_OPEN_FULLMUTEX
	rc := C.sqlite3_open_v2(cs, &db, C.int(flags), nil)
	if rc != C.SQLITE_OK {
		msg := "unable to open database file"
		if db != nil {
			msg = C.GoString(C.sqlite3_errmsg(db))
			C.sqlite3_close_v2(db)
		}
		return nil, &Error{Code: int(rc), Msg: msg}
	}
	return &Conn{db: db}, nil
}

// Close closes the connection.
func (c *Conn) Close() error {
	if c.db != nil {
		C.sqlite3_close_v2(c.db)
		c.db = nil
	}
	return nil
}

func (c *Conn) errmsg() string { return C.GoString(C.sqlite3_errmsg(c.db)) }

// Rows is a fully-materialized result set.
type Rows struct {
	Columns []string
	Values  [][]interface{}
}

func (c *Conn) prepare(query string) (*C.sqlite3_stmt, string, error) {
	cs := C.CString(query)
	defer C.free(unsafe.Pointer(cs))
	var stmt *C.sqlite3_stmt
	var tail *C.char
	rc := C.sqlite3_prepare_v2(c.db, cs, C.int(len(query)), &stmt, &tail)
	if rc != C.SQLITE_OK {
		return nil, "", &Error{Code: int(rc), Msg: c.errmsg()}
	}
	rest := ""
	if tail != nil {
		off := uintptr(unsafe.Pointer(tail)) - uintptr(unsafe.Pointer(cs))
		if int(off) < len(query) {
			rest = query[off:]
		}
	}
	return stmt, rest, nil
}

func (c *Conn) bind(stmt *C.sqlite3_stmt, args []interface{}) error {
	for i, a := range args {
		idx := C.int(i + 1)
		var rc C.int
		switch v := a.(type) {
		case nil:
			rc = C.sqlite3_bind_null(stmt, idx)
		case int:
			rc = C.sqlite3_bind_int64(stmt, idx, C.sqlite3_int64(v))
		case int64:
			rc = C.sqlite3_bind_int64(stmt, idx, C.sqlite3_int64(v))
		case bool:
			b := 0
			if v {
				b = 1
			}
			rc = C.sqlite3_bind_int64(stmt, idx, C.sqlite3_int64(b))
		case float64:
			rc = C.sqlite3_bind_double(stmt, idx, C.double(v))
		case string:
			cs := C.CString(v)
			rc = C.bind_text(stmt, idx, cs, C.int(len(v)))
			C.free(unsafe.Pointer(cs))
		case []byte:
			if len(v) == 0 {
				rc = C.bind_blob(stmt, idx, nil, 0)
			} else {
				rc = C.bind_blob(stmt, idx, unsafe.Pointer(&v[0]), C.int(len(v)))
			}
		default:
			return fmt.Errorf("unsupported bind type %T", a)
		}
		if rc != C.SQLITE_OK {
			return &Error{Code: int(rc), Msg: c.errmsg()}
		}
	}
	return nil
}

// Query runs a query and returns all rows.
func (c *Conn) Query(query string, args ...interface{}) (*Rows, error) {
	stmt, _, err := c.prepare(query)
	if err != nil {
		return nil, err
	}
	if stmt == nil {
		return &Rows{}, nil
	}
	defer C.sqlite3_finalize(stmt)
	if err := c.bind(stmt, args); err != nil {
		return nil, err
	}
	n := int(C.sqlite3_column_count(stmt))
	rows := &Rows{}
	for i := 0; i < n; i++ {
		rows.Columns = append(rows.Columns, C.GoString(C.sqlite3_column_name(stmt, C.int(i))))
	}
	for {
		rc := C.sqlite3_step(stmt)
		if rc == C.SQLITE_DONE {
			break
		}
		if rc != C.SQLITE_ROW {
			return nil, &Error{Code: int(rc), Msg: c.errmsg()}
		}
		row := make([]interface{}, n)
		for i := 0; i < n; i++ {
			switch C.sqlite3_column_type(stmt, C.int(i)) {
			case C.SQLITE_INTEGER:
				row[i] = int64(C.sqlite3_column_int64(stmt, C.int(i)))
			case C.SQLITE_FLOAT:
				row[i] = float64(C.sqlite3_column_double(stmt, C.int(i)))
			case C.SQLITE_TEXT:
				p := C.sqlite3_column_text(stmt, C.int(i))
