	return sqlite3_bind_text(s, i, v, n, SQLITE_TRANSIENT);
}
static int bind_blob(sqlite3_stmt *s, int i, const void *v, int n) {
	return sqlite3_bind_blob(s, i, v, n, SQLITE_TRANSIENT);
}
