func (c *Conn) prepare(query string) (*C.sqlite3_stmt, string, error) {
	cs := C.CString(query)
	defer C.free(unsafe.Pointer(cs))
	var stmt *C.sqlite3_stmt
	var tail *C.char
	rc := C.sqlite3_prepare_v2(c.db, cs, C.int(len(query)), &stmt, &tail)
	if rc != C.SQLITE_OK {
		return nil, "", &Error{Code: int(rc), Msg: c.errmsg()}
	}
	rest := ""
	if tail != nil {
		off := uintptr(unsafe.Pointer(tail)) - uintptr(unsafe.Pointer(cs))
		if int(off) < len(query) {
			rest = query[off:]
		}
	}
	return stmt, rest, nil
}

func (c *Conn) bind(stmt *C.sqlite3_stmt, args []interface{}) error {
	for i, a := range args {
		idx := C.int(i + 1)
		var rc C.int
		switch v := a.(type) {
		case nil:
			rc = C.sqlite3_bind_null(stmt, idx)
		case int:
			rc = C.sqlite3_bind_int64(stmt, idx, C.sqlite3_int64(v))
		case int64:
			rc = C.sqlite3_bind_int64(stmt, idx, C.sqlite3_int64(v))
		case bool:
			b := 0
			if v {
				b = 1
			}
			rc = C.sqlite3_bind_int64(stmt, idx, C.sqlite3_int64(b))
		case float64:
			rc = C.sqlite3_bind_double(stmt, idx, C.double(v))
		case string:
			cs := C.CString(v)
			rc = C.bind_text(stmt, idx, cs, C.int(len(v)))
			C.free(unsafe.Pointer(cs))
		case []byte:
			if len(v) == 0 {
				rc = C.bind_blob(stmt, idx, nil, 0)
			} else {
				rc = C.bind_blob(stmt, idx, unsafe.Pointer(&v[0]), C.int(len(v)))
			}
		default:
			return fmt.Errorf("unsupported bind type %T", a)
