					e := matchParen(toks, j)
					var out []string
					for _, part := range splitTop(toks, j+1, e) {
						if len(part) == 0 {
							out = append(out, "")
							continue
						}
						// strip trailing ASC/DESC/COLLATE
						end := len(part)
						for end > 1 && (part[end-1].is("ASC") || part[end-1].is("DESC")) {
							end--
						}
						for k := 1; k < end; k++ {
							if part[k].is("COLLATE") {
								end = k
								break
							}
						}
						out = append(out, sql[part[0].start:part[end-1].end])
					}
					return out
				}
			}
		}
	}
	return nil
}
