			for i := 0; i < len(inner); i++ {
				if inner[i] == q {
					if i+1 < len(inner) && inner[i+1] == q {
						i++
						continue
					}
					if q == '"' && i > 0 && inner[i-1] == '\\' {
						continue
					}
					ok = false
					break
				}
			}
			if ok {
				return true
			}
		}
	}
	return false
}

// Unquote unquotes a SQL string literal.
func Unquote(s string) string {
	if len(s) < 2 {
		return s
	}
	q := s[0]
	inner := s[1 : len(s)-1]
	switch q {
	case '\'':
		return strings.ReplaceAll(inner, "''", "'")
	case '"':
		if u, err := strconv.Unquote(s); err == nil {
			return u
		}
		return strings.ReplaceAll(inner, `""`, `"`)
	}
	return inner
}

func stripParens(x string) string {
	if len(x) >= 2 && x[0] == '(' && x[len(x)-1] == ')' {
		depth := 0
		for i := 0; i < len(x); i++ {
			switch x[i] {
			case '(':
				depth++
			case ')':
				depth--
				if depth == 0 && i != len(x)-1 {
					return x
				}
			}
		}
		return x[1 : len(x)-1]
	}
	return x
}

func defaultExpr(x string) schema.Expr {
	switch {
	case IsLiteralBool(x), IsLiteralNumber(x), IsQuoted(x, '"', '\''), reBlob.MatchString(x):
		return &schema.Literal{V: x}
	default:
		return &schema.RawExpr{X: stripParens(x)}
	}
}

func asString(v interface{}) string {
	switch v := v.(type) {
	case string:
		return v
	case []byte:
		return string(v)
	case int64:
		return strconv.FormatInt(v, 10)
	case float64:
		return strconv.FormatFloat(v, 'g', -1, 64)
	}
	return ""
}

func asInt(v interface{}) int64 {
	switch v := v.(type) {
	case int64:
		return v
	case string:
		i, _ := strconv.ParseInt(v, 10, 64)
		return i
	}
	return 0
}

// InspectResult holds the inspection result and extra info.
type InspectResult struct {
	Realm    *schema.Realm
	HasViews bool
}

// InspectRealm inspects the "main" schema of the connected database.
func InspectRealm(c *Conn) (*InspectResult, error) {
	s := &schema.Schema{Name: "main"}
	r := &schema.Realm{Schemas: []*schema.Schema{s}}
	s.Realm = r
	res := &InspectResult{Realm: r}
	rows, err := c.Query("SELECT name, sql, type FROM sqlite_master WHERE type IN ('table', 'view') AND name NOT LIKE 'sqlite_%'")
	if err != nil {
		return nil, err
	}
	for _, row := range rows.Values {
		name, sql, typ := asString(row[0]), asString(row[1]), asString(row[2])
		if typ == "view" {
			res.HasViews = true
			s.Views = append(s.Views, &schema.View{Name: name, Def: sql})
			continue
		}
		s.AddTables(&schema.Table{Name: name, SQL: sql})
	}
	trig, err := c.Query("SELECT name FROM sqlite_master WHERE type = 'trigger'")
	if err == nil && len(trig.Values) > 0 {
		res.HasViews = true
	}
	for _, t := range s.Tables {
		if err := inspectColumns(c, t); err != nil {
			return nil, err
		}
	}
	for _, t := range s.Tables {
		if err := inspectIndexes(c, t); err != nil {
			return nil, err
		}
	}
	for _, t := range s.Tables {
		if err := inspectFKs(c, t, s); err != nil {
			return nil, err
		}
	}
	return res, nil
}

func inspectColumns(c *Conn, t *schema.Table) error {
	rows, err := c.Query("SELECT name, type, \"notnull\", dflt_value, pk, hidden FROM pragma_table_xinfo(?)", t.Name)
	if err != nil {
		return fmt.Errorf("sqlite: query table %q columns: %w", t.Name, err)
	}
	ddl := parseCreateTable(t.SQL)
	t.WithoutRowID = ddl.withoutRowID
	t.Strict = ddl.strict
	ddlCols := map[string]*ddlColumn{}
	for _, dc := range ddl.columns {
		ddlCols[dc.name] = dc
	}
	type pkc struct {
		c   *schema.Column
		seq int64
	}
	var pks []pkc
	for _, row := range rows.Values {
		name, typ := asString(row[0]), asString(row[1])
		notnull := asInt(row[2]) != 0
		hidden := asInt(row[5])
		if hidden == 1 {
			continue
		}
		ct, err := ParseType(typ)
		if err != nil {
			return err
		}
		col := &schema.Column{Name: name, Type: &schema.ColumnType{Type: ct, Raw: typ, Null: !notnull}}
		if row[3] != nil {
			col.Default = defaultExpr(asString(row[3]))
		}
		if dc, ok := ddlCols[name]; ok {
			if hidden == 2 || hidden == 3 {
				g := &schema.Generated{Expr: dc.genExpr, Type: "VIRTUAL"}
				if hidden == 3 {
					g.Type = "STORED"
				}
				col.Generated = g
			}
			col.Collation = dc.collation
			if dc.autoInc {
				col.AutoIncrement = true
			}
		}
		if pk := asInt(row[4]); pk > 0 {
			pks = append(pks, pkc{col, pk})
		}
		t.Columns = append(t.Columns, col)
	}
	if len(pks) > 0 {
		// sort by pk sequence
		for i := 1; i < len(pks); i++ {
			for j := i; j > 0 && pks[j].seq < pks[j-1].seq; j-- {
				pks[j], pks[j-1] = pks[j-1], pks[j]
			}
		}
		pk := &schema.Index{Unique: true, Table: t}
		for i, p := range pks {
			pk.Parts = append(pk.Parts, &schema.IndexPart{SeqNo: i + 1, C: p.c})
		}
		t.PrimaryKey = pk
	}
	if !ddl.autoInc {
		for _, col := range t.Columns {
			col.AutoIncrement = false
		}
	}
	for _, ch := range ddl.checks {
		t.Checks = append(t.Checks, &schema.Check{Name: ch.name, Expr: ch.expr})
	}
	return nil
}

func inspectIndexes(c *Conn, t *schema.Table) error {
	rows, err := c.Query("SELECT il.name, il.\"unique\", il.origin, il.partial, m.sql FROM pragma_index_list(?) AS il LEFT JOIN sqlite_master AS m ON m.type = 'index' AND m.name = il.name ORDER BY il.seq DESC", t.Name)
	if err != nil {
		return fmt.Errorf("sqlite: query table %q indexes: %w", t.Name, err)
	}
	for _, row := range rows.Values {
		name, origin, sql := asString(row[0]), asString(row[2]), asString(row[4])
		idx := &schema.Index{Name: name, Unique: asInt(row[1]) != 0, Table: t, Origin: origin}
		if asInt(row[3]) != 0 {
			i := strings.Index(sql, "WHERE")
			if i == -1 {
				return fmt.Errorf("sqlite: scan %q indexes: missing partial WHERE clause in: %s", t.Name, sql)
			}
			idx.Where = strings.TrimSpace(sql[i+5:])
		}
		parts, err := c.Query("SELECT seqno, cid, name, \"desc\" FROM pragma_index_xinfo(?) WHERE key = 1 ORDER BY seqno", name)
		if err != nil {
			return err
		}
		var exprs []string
		for i, p := range parts.Values {
			part := &schema.IndexPart{SeqNo: i + 1, Desc: asInt(p[3]) != 0}
			cid := asInt(p[1])
			switch {
			case cid == -2:
				if exprs == nil {
					exprs = parseIndexParts(sql)
				}
				x := ""
				if i < len(exprs) {
					x = exprs[i]
				}
				part.X = &schema.RawExpr{X: x}
			default:
				cn := asString(p[2])
				col, ok := t.Column(cn)
				if !ok {
					return fmt.Errorf("sqlite: column %q was not found for index %q", cn, name)
				}
				part.C = col
				col.Indexes = append(col.Indexes, idx)
			}
			idx.Parts = append(idx.Parts, part)
		}
		if origin == "pk" {
			if t.PrimaryKey != nil {
				t.PrimaryKey.Name = name
				// apply desc info
				for i, p := range idx.Parts {
					if i < len(t.PrimaryKey.Parts) {
						t.PrimaryKey.Parts[i].Desc = p.Desc
					}
				}
			}
			continue
		}
		t.Indexes = append(t.Indexes, idx)
	}
	return nil
}

func inspectFKs(c *Conn, t *schema.Table, s *schema.Schema) error {
	rows, err := c.Query("SELECT id, \"table\", \"from\", \"to\", on_update, on_delete FROM pragma_foreign_key_list(?) ORDER BY id, seq", t.Name)
	if err != nil {
		return fmt.Errorf("sqlite: query table %q foreign-keys: %w", t.Name, err)
	}
	ddl := parseCreateTable(t.SQL)
	byID := map[int64]*schema.ForeignKey{}
	var order []int64
	for _, row := range rows.Values {
		if row[3] == nil {
			return fmt.Errorf("sqlite: scan %q foreign-keys: sql: Scan error on column index 2, name \"to\": converting NULL to string is unsupported", t.Name)
		}
		id := asInt(row[0])
		refName, from, to := asString(row[1]), asString(row[2]), asString(row[3])
		fk, ok := byID[id]
		if !ok {
			fk = &schema.ForeignKey{Symbol: strconv.FormatInt(id, 10), Table: t, OnUpdate: asString(row[4]), OnDelete: asString(row[5])}
			ref, ok := s.Table(refName)
			if !ok {
				ref = &schema.Table{Name: refName, Schema: s}
			}
			fk.RefTable = ref
			byID[id] = fk
			order = append(order, id)
		}
		col, ok := t.Column(from)
		if !ok {
			return fmt.Errorf("sqlite: column %q was not found for fk", from)
		}
		fk.Columns = append(fk.Columns, col)
		rc, ok := fk.RefTable.Column(to)
		if !ok {
			rc = &schema.Column{Name: to}
			fk.RefTable.Columns = append(fk.RefTable.Columns, rc)
		}
		fk.RefColumns = append(fk.RefColumns, rc)
	}
	for _, id := range order {
		fk := byID[id]
		for _, d := range ddl.fks {
			if d.name == "" || !validName(d.name) {
				continue
			}
			if eqNames(d.columns, fk.Columns) && strings.EqualFold(d.refTable, fk.RefTable.Name) {
				fk.Symbol = d.name
				break
			}
		}
		t.ForeignKeys = append(t.ForeignKeys, fk)
		for _, col := range fk.Columns {
			col.ForeignKeys = append(col.ForeignKeys, fk)
		}
	}
	return nil
}

func eqNames(names []string, cols []*schema.Column) bool {
	if len(names) != len(cols) {
		return false
	}
	for i := range names {
		if names[i] != cols[i].Name {
			return false
		}
	}
	return true
}
