// validIdent reports whether s is a valid HCL identifier.
func validIdent(s string) bool {
	if s == "" {
		return false
	}
	toks := hcl.Lex([]byte(s), "")
	return len(toks) == 2 && toks[0].Type == hcl.TokenIdent && string(toks[0].Bytes) == s
}

func refStep(kind, name string) string {
	if validIdent(name) {
		return kind + "." + name
	}
	return kind + "[" + QuoteHCL(name) + "]"
}

func colRef(c *schema.Column) string { return refStep("column", c.Name) }

func tableColRef(t *schema.Table, c *schema.Column) string {
	return refStep("table", t.Name) + "." + refStep("column", c.Name)
}

// TypeSpec returns the HCL representation of a column type.
func TypeSpec(ct *schema.ColumnType) string {
	switch t := ct.Type.(type) {
	case *schema.StringType:
		n := hclTypeName(t.T)
		if t.Size > 0 {
			return fmt.Sprintf("%s(%d)", n, t.Size)
		}
		return n
	case *schema.DecimalType:
		n := hclTypeName(t.T)
		switch {
		case t.Precision > 0 && t.Scale > 0:
			return fmt.Sprintf("%s(%d,%d)", n, t.Precision, t.Scale)
		case t.Precision > 0:
			return fmt.Sprintf("%s(%d)", n, t.Precision)
		}
		return n
	case *schema.UnsupportedType:
		if t.T == "" {
			return "blob"
		}
		return "sql(" + QuoteHCL(t.T) + ")"
	case nil:
		return "blob"
	}
	return hclTypeName(sqlite.TypeName(ct.Type))
}

func hclTypeName(t string) string {
	return strings.ReplaceAll(strings.ToLower(t), " ", "_")
}

// DefaultSpec returns the HCL representation of a column default.
func DefaultSpec(c *schema.Column) (string, error) {
	switch x := c.Default.(type) {
	case *schema.Literal:
		v := x.V
		switch {
		case hasPrefixAny(v, "0x", "0X", "0b", "0B", "b'", "B'", "x'", "X'"):
			return "sql(" + QuoteHCL(v) + ")", nil
		case sqlite.IsQuoted(v, '\'', '"'):
			return QuoteHCL(sqlite.Unquote(v)), nil
		case sqlite.IsLiteralBool(v):
			return strings.ToLower(v), nil
		case c.Type != nil && isStringType(c.Type.Type):
			return QuoteHCL(v), nil
		case strings.Contains(v, "."):
			f, err := strconv.ParseFloat(v, 64)
			if err != nil {
				return "", err
			}
			return formatFloat(f), nil
		default:
			i, err := strconv.ParseInt(v, 10, 64)
			if err != nil {
				return "", err
			}
			return strconv.FormatInt(i, 10), nil
		}
	case *schema.RawExpr:
		return "sql(" + QuoteHCL(x.X) + ")", nil
	}
	return "", fmt.Errorf("converting expr %T to literal value", c.Default)
}

func formatFloat(f float64) string {
	bf := new(big.Float).SetFloat64(f)
	return hcl.NumberString(bf)
}

func isStringType(t schema.Type) bool {
	_, ok := t.(*schema.StringType)
	return ok
}

func hasPrefixAny(s string, ps ...string) bool {
	for _, p := range ps {
		if strings.HasPrefix(s, p) {
			return true
		}
	}
	return false
}

// MarshalHCL renders the realm in Atlas HCL.
func MarshalHCL(r *schema.Realm) (string, error) {
	w := &writer{}
	for _, s := range r.Schemas {
		for _, t := range s.Tables {
			if err := marshalTable(w, t, len(r.Schemas) > 1); err != nil {
				return "", err
			}
		}
	}
	for _, s := range r.Schemas {
		w.open("schema %s", QuoteHCL(s.Name))
		w.close()
	}
	return string(hcl.Format([]byte(w.b.String()))), nil
}

func marshalTable(w *writer, t *schema.Table, qualified bool) error {
	w.open("table %s", QuoteHCL(t.Name))
	w.line("schema = %s", refStep("schema", t.Schema.Name))
	for _, c := range t.Columns {
		w.open("column %s", QuoteHCL(c.Name))
		w.line("null = %v", c.Type.Null)
		w.line("type = %s", TypeSpec(c.Type))
		if c.Default != nil {
			d, err := DefaultSpec(c)
			if err != nil {
				return fmt.Errorf("specutil: failed converting schema to spec: %w", err)
			}
			w.line("default = %s", d)
		}
		if c.AutoIncrement {
			w.line("auto_increment = true")
		}
		if c.Generated != nil {
			w.open("as")
			w.line("expr = %s", QuoteHCL(c.Generated.Expr))
			w.line("type = %s", c.Generated.Type)
			w.close()
		}
		w.close()
	}
	if pk := t.PrimaryKey; pk != nil {
		w.open("primary_key")
		writeParts(w, pk, t)
		w.close()
	}
	for _, fk := range t.ForeignKeys {
		w.open("foreign_key %s", QuoteHCL(fk.Symbol))
		var cols, refs []string
		for _, c := range fk.Columns {
			cols = append(cols, colRef(c))
		}
		for _, c := range fk.RefColumns {
			refs = append(refs, tableColRef(fk.RefTable, c))
		}
		w.line("columns = [%s]", strings.Join(cols, ", "))
		w.line("ref_columns = [%s]", strings.Join(refs, ", "))
		w.line("on_update = %s", refAction(fk.OnUpdate))
		w.line("on_delete = %s", refAction(fk.OnDelete))
		w.close()
	}
	for _, idx := range t.Indexes {
		w.open("index %s", QuoteHCL(idx.Name))
		if idx.Unique {
			w.line("unique = true")
		}
		writeParts(w, idx, t)
		if idx.Where != "" {
			w.line("where = %s", QuoteHCL(idx.Where))
		}
		w.close()
	}
	for _, ch := range t.Checks {
		if ch.Name != "" {
			w.open("check %s", QuoteHCL(ch.Name))
		} else {
			w.open("check")
		}
		w.line("expr = %s", QuoteHCL(ch.Expr))
		w.close()
	}
	if t.WithoutRowID {
		w.line("without_rowid = true")
	}
	if t.Strict {
		w.line("strict = true")
	}
	w.close()
	return nil
}

func refAction(a string) string {
	if a == "" {
		return "NO_ACTION"
	}
	return strings.ReplaceAll(strings.ToUpper(a), " ", "_")
}

func writeParts(w *writer, idx *schema.Index, t *schema.Table) {
	simple := true
	for _, p := range idx.Parts {
		if p.Desc || p.C == nil {
			simple = false
		}
	}
	if simple {
		var cols []string
		for _, p := range idx.Parts {
			cols = append(cols, colRef(p.C))
		}
		w.line("columns = [%s]", strings.Join(cols, ", "))
		return
	}
	for _, p := range idx.Parts {
		w.open("on")
		if p.Desc {
			w.line("desc = true")
		}
		if p.C != nil {
			w.line("column = %s", colRef(p.C))
		} else if x, ok := p.X.(*schema.RawExpr); ok {
			w.line("expr = %s", QuoteHCL(x.X))
		}
		w.close()
	}
}
