// RealmJSON converts the realm into its JSON representation.
func RealmJSON(r *schema.Realm) interface{} {
	var jr jsonRealm
	for _, s := range r.Schemas {
		js := jsonSchema{Name: s.Name}
		for _, t := range s.Tables {
			jt := jsonTable{Name: t.Name}
			for _, c := range t.Columns {
				jt.Columns = append(jt.Columns, jsonColumn{Name: c.Name, Type: c.Type.Raw, Null: c.Type.Null})
			}
			for _, idx := range t.Indexes {
				jt.Indexes = append(jt.Indexes, jsonIdx(idx, true))
			}
			if t.PrimaryKey != nil {
				pk := jsonIdx(t.PrimaryKey, false)
				jt.PrimaryKey = &pk
			}
			for _, fk := range t.ForeignKeys {
				jf := jsonForeignKey{Name: fk.Symbol, References: jsonReference{Table: fk.RefTable.Name}}
				for _, c := range fk.Columns {
					jf.Columns = append(jf.Columns, c.Name)
				}
				for _, c := range fk.RefColumns {
					jf.References.Columns = append(jf.References.Columns, c.Name)
				}
				jt.ForeignKeys = append(jt.ForeignKeys, jf)
			}
			js.Tables = append(js.Tables, jt)
		}
		jr.Schemas = append(jr.Schemas, js)
	}
	return jr
}

// sqlMarshaler is implemented by payloads that can be rendered as SQL.
type sqlMarshaler interface {
	MarshalSQL(indent ...string) (string, error)
}

// Funcs are the template functions.
var Funcs = template.FuncMap{
	"json": func(v interface{}, args ...string) (string, error) {
		var (
			b   []byte
			err error
		)
		switch len(args) {
		case 0:
			b, err = json.Marshal(v)
		case 1:
			b, err = json.MarshalIndent(v, "", args[0])
		default:
			b, err = json.MarshalIndent(v, args[0], args[1])
		}
		return string(b), err
	},
	"sql": func(v interface{}, indent ...string) (string, error) {
		m, ok := v.(sqlMarshaler)
		if !ok {
			return "", fmt.Errorf("unsupported type %T", v)
		}
		return m.MarshalSQL(indent...)
	},
	"mermaid": func(v interface{}, _ ...string) (string, error) {
		s, ok := v.(*SchemaInspect)
		if !ok {
			return "", fmt.Errorf("unsupported type %T", v)
		}
		return Mermaid(s.Realm), nil
	},
	"upper": strings.ToUpper,
	"lower": strings.ToLower,
	"add": func(a, b int) int { return a + b },
}

// Mermaid renders the realm as a mermaid ERD.
func Mermaid(r *schema.Realm) string {
	var b bytes.Buffer
	b.WriteString("erDiagram\n")
	under := func(s string) string { return strings.ReplaceAll(s, " ", "_") }
	for _, s := range r.Schemas {
		for _, t := range s.Tables {
			fmt.Fprintf(&b, "    %s {\n", t.Name)
			for _, c := range t.Columns {
				var keys []string
				if t.PrimaryKey != nil {
					for _, p := range t.PrimaryKey.Parts {
						if p.C == c {
							keys = append(keys, "PK")
						}
					}
				}
				if len(c.ForeignKeys) > 0 {
					keys = append(keys, "FK")
				}
				typ, _ := sqlite.FormatType(c.Type.Type)
				line := fmt.Sprintf("      %s %s", under(typ), under(c.Name))
				if len(keys) > 0 {
					line += " " + strings.Join(keys, ",")
				}
				b.WriteString(line + "\n")
			}
			b.WriteString("    }\n")
			for _, fk := range t.ForeignKeys {
				left := "}o"
				if fkUnique(t, fk) {
					left = "|o"
				}
				fmt.Fprintf(&b, "    %s %s--o| %s : %s\n", t.Name, left, fk.RefTable.Name, fk.Symbol)
			}
		}
	}
	return b.String()
}

func fkUnique(t *schema.Table, fk *schema.ForeignKey) bool {
	match := func(idx *schema.Index) bool {
		if idx == nil || len(idx.Parts) != len(fk.Columns) {
			return false
		}
		for i, p := range idx.Parts {
			if p.C != fk.Columns[i] {
				return false
			}
		}
		return true
	}
	if match(t.PrimaryKey) {
		return true
	}
	for _, idx := range t.Indexes {
		if idx.Unique && match(idx) {
			return true
		}
	}
	return false
}
