package sqlite

import (
	"fmt"
	"strings"
	"unicode"

	"atlasre/internal/schema"
)

// PlanChange is a single planned statement.
type PlanChange struct {
	Cmd     string
	Comment string
	Reverse string
}

// Plan is a list of planned statements.
type Plan struct {
	Changes []*PlanChange
	// Transactional reports whether the plan can run in a transaction.
	Transactional bool
}

// Ident quotes an identifier.
func Ident(s string) string { return "`" + strings.ReplaceAll(s, "`", "``") + "`" }

// Capitalize upper-cases the first letter.
func Capitalize(s string) string {
	for i, r := range s {
		return string(unicode.ToUpper(r)) + s[i+len(string(r)):]
	}
	return s
}

type planner struct {
	indent  string
	changes []*PlanChange
	skipFKs bool
}

func (p *planner) add(cmd, comment string) {
	p.changes = append(p.changes, &PlanChange{Cmd: cmd, Comment: comment})
}

// PlanChanges converts schema changes into SQL statements.
func PlanChanges(changes []schema.Change, indent string) (*Plan, error) {
	p := &planner{indent: indent}
	for _, c := range changes {
		var err error
		switch c := c.(type) {
		case *schema.AddTable:
			err = p.addTable(c.T)
		case *schema.DropTable:
			p.skipFKs = true
			p.add("DROP TABLE "+Ident(c.T.Name), fmt.Sprintf("drop %q table", c.T.Name))
		case *schema.ModifyTable:
			err = p.modifyTable(c)
		default:
			err = fmt.Errorf("unsupported change %T", c)
		}
		if err != nil {
			return nil, err
		}
	}
	if p.skipFKs {
		p.changes = append([]*PlanChange{{Cmd: "PRAGMA foreign_keys = off", Comment: "disable the enforcement of foreign-keys constraints"}}, p.changes...)
		p.add("PRAGMA foreign_keys = on", "enable back the enforcement of foreign-keys constraints")
	}
	return &Plan{Changes: p.changes, Transactional: true}, nil
}

func (p *planner) wrap(items []string) string {
	if p.indent == "" {
		return "(" + strings.Join(items, ", ") + ")"
	}
	return "(\n" + p.indent + strings.Join(items, ",\n"+p.indent) + "\n)"
}

func quoteLiteral(s string) string {
	if IsQuoted(s, '\'') {
		return s
	}
	if IsQuoted(s, '"') {
		s = Unquote(s)
	}
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

// DefaultValue formats the default value of the column.
func DefaultValue(c *schema.Column) string {
	switch x := c.Default.(type) {
	case *schema.Literal:
		if c.Type != nil && IsStringish(c.Type.Type) {
			return quoteLiteral(x.V)
		}
		return x.V
	case *schema.RawExpr:
		return "(" + x.X + ")"
	}
	return ""
}

func autoIncPK(t *schema.Table) *schema.Column {
	if t.PrimaryKey != nil && len(t.PrimaryKey.Parts) == 1 && t.PrimaryKey.Parts[0].C != nil && t.PrimaryKey.Parts[0].C.AutoIncrement {
		return t.PrimaryKey.Parts[0].C
	}
	return nil
}

// ColumnDef formats a column definition.
func ColumnDef(c *schema.Column, t *schema.Table) (string, error) {
	typ, err := FormatType(c.Type.Type)
	if err != nil {
		return "", err
	}
	var b strings.Builder
	b.WriteString(Ident(c.Name))
	if typ != "" {
		b.WriteString(" " + typ)
	}
	if c.Type.Null {
		b.WriteString(" NULL")
	} else {
		b.WriteString(" NOT NULL")
	}
	if c.Default != nil {
		b.WriteString(" DEFAULT " + DefaultValue(c))
	}
	if c.Generated != nil {
		x := c.Generated.Expr
		if !strings.HasPrefix(x, "(") || stripParens(x) == x {
			x = "(" + x + ")"
		}
		b.WriteString(" AS " + x)
		if c.Generated.Type != "" {
			b.WriteString(" " + strings.ToUpper(c.Generated.Type))
		}
	}
	if c.Collation != "" {
		b.WriteString(" COLLATE " + c.Collation)
	}
	if t != nil && autoIncPK(t) == c {
		b.WriteString(" PRIMARY KEY AUTOINCREMENT")
	}
	return b.String(), nil
}

func identList(cols []*schema.Column) string {
	var parts []string
	for _, c := range cols {
		parts = append(parts, Ident(c.Name))
	}
	return strings.Join(parts, ", ")
}

func refAction(a string) string { return strings.ReplaceAll(strings.ToUpper(a), "_", " ") }

func fkDef(fk *schema.ForeignKey) string {
	var b strings.Builder
	if fk.Symbol != "" {
		b.WriteString("CONSTRAINT " + Ident(fk.Symbol) + " ")
	}
	b.WriteString("FOREIGN KEY (" + identList(fk.Columns) + ") REFERENCES " + Ident(fk.RefTable.Name) + " (" + identList(fk.RefColumns) + ")")
	if fk.OnUpdate != "" {
		b.WriteString(" ON UPDATE " + refAction(fk.OnUpdate))
	}
	if fk.OnDelete != "" {
		b.WriteString(" ON DELETE " + refAction(fk.OnDelete))
	}
	return b.String()
}

func checkDef(c *schema.Check) string {
	x := c.Expr
	if !strings.HasPrefix(x, "(") || stripParens(x) == x {
		x = "(" + x + ")"
	}
	if c.Name != "" {
		return "CONSTRAINT " + Ident(c.Name) + " CHECK " + x
	}
	return "CHECK " + x
}

