cd /workspace/cmd/atlas && cat > client.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"net"
	"net/url"
	"strings"

	"atlasre/internal/sqlite"
)

// Client is an open database connection.
type Client struct {
	URL    *url.URL
	Driver string
	Conn   *sqlite.Conn
	DSN    string
}

func parseURL(raw string) (*url.URL, error) {
	u, err := url.Parse(raw)
	if err != nil {
		var ue *url.Error
		if errors.As(err, &ue) {
			return nil, ue.Err
		}
		return nil, err
	}
	return u, nil
}

func isSQLiteScheme(s string) bool {
	switch s {
	case "sqlite", "sqlite3":
		return true
	}
	return false
}

// OpenClient opens a client for the given URL.
func OpenClient(raw string) (*Client, error) {
	u, err := parseURL(raw)
	if err != nil {
		return nil, err
	}
	if u.Scheme == "" {
		return nil, errors.New("missing scheme. See: https://atlasgo.io/url")
	}
	switch u.Scheme {
	case "sqlite", "sqlite3":
		dsn := "file:" + strings.TrimPrefix(u.String(), u.Scheme+"://")
		// remove driver specific params
		dsn, pragmas := splitDSN(dsn)
		conn, err := sqlite.Open(dsn)
		if err != nil {
			return nil, fmt.Errorf("sqlite: querying schemas: %w", err)
		}
		for _, p := range pragmas {
			if _, err := conn.Exec(p); err != nil {
				conn.Close()
				return nil, err
			}
		}
		// verify the connection.
		if _, err := conn.Query("SELECT 1 FROM sqlite_master LIMIT 1"); err != nil {
			conn.Close()
			return nil, fmt.Errorf("sqlite: querying schemas: %w", err)
		}
		return &Client{URL: u, Driver: "sqlite", Conn: conn, DSN: dsn}, nil
	case "mysql", "maria", "mariadb", "mysql+unix":
		return nil, dialErr(u, "3306", "mysql: query system variables")
	case "postgres", "postgresql":
		return nil, dialErr(u, "5432", "postgres: scanning system variables")
	case "docker":
		return nil, fmt.Errorf("unsupported docker image %q", u.Host)
	case "libsql", "libsql+ws", "libsql+wss":
		return nil, fmt.Errorf("sqlite: querying schemas: failed to execute SQL: unsupported driver %q", u.Scheme)
	}
	return nil, fmt.Errorf("sql/sqlclient: unknown driver %q. See: https://atlasgo.io/url", u.Scheme)
}

func dialErr(u *url.URL, port, prefix string) error {
	if u.Scheme == "mysql+unix" {
		_, err := net.Dial("unix", u.Path)
		if err == nil {
			return fmt.Errorf("%s: unsupported", prefix)
		}
		return fmt.Errorf("%s: %w", prefix, err)
	}
	host := u.Hostname()
	if host == "" {
		host = "localhost"
	}
	p := u.Port()
	if p == "" {
		p = port
	}
	conn, err := net.Dial("tcp", net.JoinHostPort(host, p))
	if err != nil {
		return fmt.Errorf("%s: %w", prefix, err)
	}
	conn.Close()
	return fmt.Errorf("%s: unsupported database server", prefix)
}

// splitDSN extracts mattn-style pragma params from the DSN.
func splitDSN(dsn string) (string, []string) {
	i := strings.IndexByte(dsn, '?')
	if i < 0 {
		return dsn, nil
	}
	q, err := url.ParseQuery(dsn[i+1:])
	if err != nil {
		return dsn, nil
	}
	var pragmas []string
	keep := url.Values{}
	for k, vs := range q {
		v := vs[len(vs)-1]
		switch k {
		case "_fk", "_foreign_keys":
			pragmas = append(pragmas, "PRAGMA foreign_keys = "+boolPragma(v))
		case "_journal_mode", "_journal":
			pragmas = append(pragmas, "PRAGMA journal_mode = "+v)
		case "_busy_timeout", "_timeout":
			pragmas = append(pragmas, "PRAGMA busy_timeout = "+v)
		case "_sync", "_synchronous":
			pragmas = append(pragmas, "PRAGMA synchronous = "+v)
