package cmdlog

import (
	"strings"

	"atlasre/internal/schema"
	"atlasre/internal/sqlite"
)

// RealmSQL renders the DDL statements creating the realm.
func RealmSQL(r *schema.Realm, indent ...string) (string, error) {
	var changes []schema.Change
	for _, s := range r.Schemas {
		for _, t := range s.Tables {
			changes = append(changes, &schema.AddTable{T: t})
		}
	}
	ind := ""
	if len(indent) > 0 {
		ind = indent[0]
	}
	plan, err := sqlite.PlanChanges(changes, ind)
	if err != nil {
		return "", err
	}
	return PlanSQL(plan), nil
}

// PlanSQL renders the statements of the plan with their comments.
func PlanSQL(plan *sqlite.Plan) string {
	var b strings.Builder
	for _, c := range plan.Changes {
		if c.Comment != "" {
			b.WriteString("-- " + sqlite.Capitalize(c.Comment) + "\n")
		}
		b.WriteString(c.Cmd + ";\n")
	}
	return b.String()
}
