// applyExclude filters the realm by the given glob patterns.
func applyExclude(r *schema.Realm, patterns []string) error {
	for _, p := range patterns {
		full := "main." + p
		parts := strings.Split(p, ".")
		if len(parts) > 2 {
			return fmt.Errorf("too many parts in pattern: %q", full)
		}
		tpat, ttype := splitSelector(parts[0])
		for _, s := range r.Schemas {
			if len(parts) == 1 {
				if ttype != "" && ttype != "table" {
					continue
				}
				var keep []*schema.Table
				for _, t := range s.Tables {
					if ok, _ := path.Match(tpat, t.Name); !ok {
						keep = append(keep, t)
					}
				}
				s.Tables = keep
				continue
			}
			cpat, ctype := splitSelector(parts[1])
			for _, t := range s.Tables {
				if ok, _ := path.Match(tpat, t.Name); !ok {
					continue
				}
				excludeInTable(t, cpat, ctype)
			}
		}
	}
