		}
		ok, _ := path.Match(pat, name)
		return ok
	}
	var cols []*schema.Column
	removed := map[*schema.Column]bool{}
	for _, c := range t.Columns {
		if match(c.Name, "column") {
			removed[c] = true
			continue
		}
		cols = append(cols, c)
	}
	t.Columns = cols
	usesRemoved := func(idx *schema.Index) bool {
		for _, p := range idx.Parts {
			if p.C != nil && removed[p.C] {
				return true
			}
		}
		return false
	}
	if t.PrimaryKey != nil && usesRemoved(t.PrimaryKey) {
		t.PrimaryKey = nil
	}
	var idxs []*schema.Index
	for _, idx := range t.Indexes {
		if match(idx.Name, "index") || usesRemoved(idx) {
			continue
		}
		idxs = append(idxs, idx)
	}
	t.Indexes = idxs
	var fks []*schema.ForeignKey
	for _, fk := range t.ForeignKeys {
		bad := match(fk.Symbol, "fk") || match(fk.Symbol, "foreign_key")
		for _, c := range fk.Columns {
			if removed[c] {
				bad = true
			}
		}
		if !bad {
			fks = append(fks, fk)
		}
	}
	t.ForeignKeys = fks
	var checks []*schema.Check
	for _, ch := range t.Checks {
		if ch.Name != "" && match(ch.Name, "check") {
			continue
		}
		checks = append(checks, ch)
	}
	t.Checks = checks
}

