func baseFuncs() map[string]*hcl.Function {
	fns := hcl.Stdlib()
	fns["sql"] = &hcl.Function{Params: []string{"def"}, Impl: func(args []hcl.Value, _ *hcl.EvalContext, r hcl.Range) (hcl.Value, hcl.Diagnostics) {
		s, err := hcl.ToString(args[0])
		if err != nil {
			return hcl.UnknownVal, diag("Invalid function argument", "Invalid value for \"def\" parameter: string required.", r)
		}
		return hcl.CapsuleVal(&RawSQL{X: s}), nil
	}}
	return fns
}

type blockRef struct {
	b    *hcl.Block
	name string
}

// Unmarshal evaluates the doc into a realm.
func (d *Doc) Unmarshal(opts Options) (*schema.Realm, error) {
	var schemaBlocks, tableBlocks []*hcl.Block
	var varBlocks, localAttrs []*hcl.Block
	var topAttrs []*hcl.Attribute
	_ = topAttrs
	for _, f := range d.Files {
		for _, b := range f.Body.Blocks {
			switch b.Type {
			case "schema":
				schemaBlocks = append(schemaBlocks, b)
			case "table":
				tableBlocks = append(tableBlocks, b)
			case "variable":
				varBlocks = append(varBlocks, b)
			case "locals":
				localAttrs = append(localAttrs, b)
			}
		}
	}
	base := &hcl.EvalContext{Functions: baseFuncs()}
	ctx := base.NewChild()
	ctx.Variables = map[string]hcl.Value{}
	// variables
	if len(varBlocks) > 0 {
		vars := map[string]hcl.Value{}
		for _, b := range varBlocks {
			if len(b.Labels) == 0 {
				continue
			}
			name := b.Labels[0]
			if vs, ok := opts.Vars[name]; ok {
				if len(vs) == 1 {
					vars[name] = hcl.StringVal(vs[0])
				} else {
					var l []hcl.Value
					for _, v := range vs {
						l = append(l, hcl.StringVal(v))
					}
					vars[name] = hcl.TupleVal(l)
				}
				if ta, ok := b.Body.Attributes["type"]; ok {
					if st, ok := ta.Expr.(*hcl.ScopeTraversalExpr); ok && len(vs) == 1 {
						switch st.Traversal.RootName() {
						case "number", "int":
							n, err := hcl.ToNumber(hcl.StringVal(vs[0]))
							if err != nil {
								return nil, fmt.Errorf("variable %q: a number is required", name)
							}
							vars[name] = n
						case "bool":
							bv, err := hcl.ToBool(hcl.StringVal(vs[0]))
							if err != nil {
								return nil, fmt.Errorf("variable %q: a bool is required", name)
							}
							vars[name] = bv
						}
					}
				}
				continue
			}
			if da, ok := b.Body.Attributes["default"]; ok {
				v, diags := hcl.Eval(da.Expr, ctx)
				if diags.HasErrors() {
					return nil, diags
				}
				vars[name] = v
				continue
			}
			return nil, fmt.Errorf("missing value for required variable %q", name)
		}
		ctx.Variables["var"] = hcl.ObjectVal(vars)
	}
	if len(localAttrs) > 0 {
		locals := map[string]hcl.Value{}
		ctx.Variables["local"] = hcl.ObjectVal(locals)
		var attrs []*hcl.Attribute
		for _, b := range localAttrs {
			attrs = append(attrs, b.Body.AttrOrder...)
		}
		pending := attrs
		for len(pending) > 0 {
			var next []*hcl.Attribute
			var lastErr hcl.Diagnostics
			for _, a := range pending {
				v, diags := hcl.Eval(a.Expr, ctx)
				if diags.HasErrors() {
					next = append(next, a)
					lastErr = diags
					continue
				}
				locals[a.Name] = v
				ctx.Variables["local"] = hcl.ObjectVal(locals)
			}
			if len(next) == len(pending) {
				return nil, lastErr
			}
			pending = next
		}
	}
	// schemas
	realm := &schema.Realm{}
	if len(schemaBlocks) > 0 {
		sm := map[string]hcl.Value{}
		for _, b := range schemaBlocks {
			if len(b.Labels) == 0 {
				continue
			}
			name := b.Labels[0]
			if _, ok := realm.Schema(name); ok {
				continue
			}
			s := &schema.Schema{Name: name, Realm: realm}
			realm.Schemas = append(realm.Schemas, s)
			sm[name] = hcl.CapsuleVal(&SchemaRef{Name: name})
		}
		ctx.Variables["schema"] = hcl.ObjectVal(sm)
	}
	// tables
	type tdef struct {
		b    *hcl.Block
		t    *schema.Table
		cols hcl.Value
	}
	var tdefs []*tdef
	tm := map[string]hcl.Value{}
	for _, b := range tableBlocks {
		if len(b.Labels) == 0 {
			continue
		}
		name := b.Labels[0]
		t := &schema.Table{Name: name}
		cm := map[string]hcl.Value{}
		for _, cb := range b.Body.Blocks {
			if cb.Type == "column" && len(cb.Labels) > 0 {
				cm[cb.Labels[0]] = hcl.CapsuleVal(&ColRef{Table: name, Column: cb.Labels[0]})
			}
		}
		cols := hcl.ObjectVal(cm)
		tm[name] = hcl.CapsuleVal(&TableRef{Name: name, cols: cols})
		tdefs = append(tdefs, &tdef{b: b, t: t, cols: cols})
	}
	if len(tableBlocks) > 0 {
		ctx.Variables["table"] = hcl.ObjectVal(tm)
	}
	tables := map[string]*schema.Table{}
	for _, td := range tdefs {
		tables[td.t.Name] = td.t
	}
	// first pass: columns and table-level attributes
	for _, td := range tdefs {
		tctx := ctx.NewChild()
		tctx.Variables = map[string]hcl.Value{"column": td.cols}
		if err := convertTable(td.b, td.t, tctx, realm); err != nil {
			return nil, err
		}
	}
	// second pass: keys, indexes, foreign keys
	for _, td := range tdefs {
		tctx := ctx.NewChild()
		tctx.Variables = map[string]hcl.Value{"column": td.cols}
		if err := convertTableKeys(td.b, td.t, tctx, tables); err != nil {
			return nil, err
		}
	}
	return realm, nil
}

func evalAttr(b *hcl.Body, name string, ctx *hcl.EvalContext) (hcl.Value, bool, error) {
	a, ok := b.Attributes[name]
	if !ok {
		return hcl.NullVal, false, nil
	}
	v, diags := hcl.Eval(a.Expr, ctx)
	if diags.HasErrors() {
		return v, true, diags
	}
	return v, true, nil
}

func boolAttr(b *hcl.Body, name string, ctx *hcl.EvalContext) (bool, error) {
	v, ok, err := evalAttr(b, name, ctx)
	if err != nil || !ok || v.T == hcl.TNull {
		return false, err
	}
	if v.T != hcl.TBool {
		return false, specErr("value of attr %q cannot be read as bool: bool value is required", name)
	}
	return v.B, nil
}

func stringAttr(b *hcl.Body, name string, ctx *hcl.EvalContext) (string, bool, error) {
	v, ok, err := evalAttr(b, name, ctx)
	if err != nil || !ok || v.T == hcl.TNull {
		return "", false, err
	}
	switch v.T {
	case hcl.TString:
		return v.S, true, nil
	case hcl.TCapsule:
		if r, ok := v.Cap.(*RawSQL); ok {
			return r.X, true, nil
		}
	}
	return "", false, specErr("value of attr %q cannot be read as string: string value is required", name)
}

func evalType(b *hcl.Block, ctx *hcl.EvalContext) (*schema.ColumnType, error) {
	a, ok := b.Body.Attributes["type"]
	if !ok {
		return nil, nil
	}
	tctx := ctx.NewChild()
	tctx.Variables = map[string]hcl.Value{}
	tctx.VarOrder = typeOrder
	tctx.Functions = map[string]*hcl.Function{}
	for _, n := range typeOrder {
		name := n
		tctx.Variables[name] = hcl.CapsuleVal(&TypeSpecVal{Name: name})
		max := typeAttrs[name]
		tctx.Functions[name] = &hcl.Function{VarParam: "args", Impl: func(args []hcl.Value, _ *hcl.EvalContext, r hcl.Range) (hcl.Value, hcl.Diagnostics) {
			if max == 0 {
				return hcl.UnknownVal, diag("Call to unknown function", fmt.Sprintf("Type %q does not accept attributes", name), r)
			}
			if len(args) > max {
				return hcl.UnknownVal, diag("Error in function call", fmt.Sprintf("Call to function %q failed: too many arguments for type definition %q.", name, name), r)
			}
			return hcl.CapsuleVal(&TypeSpecVal{Name: name, Args: args}), nil
		}}
	}
	if st, ok := a.Expr.(*hcl.ScopeTraversalExpr); ok && len(st.Traversal) == 1 {
		root := st.Traversal.RootName()
		if _, known := typeAttrs[root]; !known {
			switch root {
			case "string", "number":
				return nil, specErr("set field \"type\": converting cty.Value to *schemahcl.Type: incorrect type type")
			}
			s := hclSuggest(root, typeOrder)
			if s != "" {
				s = fmt.Sprintf(" Did you mean %q?", s)
			}
			return nil, diag("Unknown "+b.Type+".type", fmt.Sprintf("There is no type named %q.%s", root, s), st.SrcRange)
		}
	}
	v, diags := hcl.Eval(a.Expr, tctx)
	if diags.HasErrors() {
		return nil, diags
	}
	var raw string
	switch x := v.Cap.(type) {
	case *TypeSpecVal:
		raw = strings.ReplaceAll(x.Name, "_", " ")
		if len(x.Args) > 0 {
			var parts []string
			for _, a := range x.Args {
				s, err := hcl.ToString(a)
				if err != nil {
					return nil, specErr("invalid type argument")
				}
				parts = append(parts, s)
			}
			raw += "(" + strings.Join(parts, ",") + ")"
		}
	case *RawSQL:
		raw = x.X
	default:
		return nil, specErr("set field \"type\": converting cty.Value to *schemahcl.Type: incorrect type")
	}
	t, err := sqlite.ParseType(raw)
	if err != nil {
		return nil, err
	}
	return &schema.ColumnType{Type: t, Raw: raw}, nil
}

func hclSuggest(given string, cands []string) string {
	for _, c := range cands {
		if levenshtein(given, c) < 3 {
			return c
		}
	}
	return ""
}

func levenshtein(a, b string) int {
	ra, rb := []rune(a), []rune(b)
	prev := make([]int, len(rb)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ra); i++ {
		cur := make([]int, len(rb)+1)
		cur[0] = i
		for j := 1; j <= len(rb); j++ {
			cost := 1
			if ra[i-1] == rb[j-1] {
				cost = 0
			}
			cur[j] = min(prev[j]+1, min(cur[j-1]+1, prev[j-1]+cost))
		}
		prev = cur
	}
	return prev[len(rb)]
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func evalEnum(b *hcl.Block, name string, allowed []string, ctx *hcl.EvalContext) (string, error) {
	a, ok := b.Body.Attributes[name]
	if !ok {
		return "", nil
	}
	if st, ok := a.Expr.(*hcl.ScopeTraversalExpr); ok && len(st.Traversal) == 1 {
		root := st.Traversal.RootName()
		for _, x := range allowed {
			if x == root {
				return root, nil
			}
		}
		s := hclSuggest(root, allowed)
		if s != "" {
			s = fmt.Sprintf(" Did you mean %q?", s)
		}
		return "", diag("Unknown "+b.Type+"."+name, fmt.Sprintf("There is no %s named %q.%s", name, root, s), st.SrcRange)
	}
	v, diags := hcl.Eval(a.Expr, ctx)
	if diags.HasErrors() {
		return "", diags
	}
	if v.T == hcl.TString {
		return v.S, nil
	}
	return "", specErr("value of attr %q cannot be read as string: string value is required", name)
}

func convertTable(b *hcl.Block, t *schema.Table, ctx *hcl.EvalContext, realm *schema.Realm) error {
	body := b.Body
	sv, ok, err := evalAttr(body, "schema", ctx)
	if err != nil {
		return err
	}
	if !ok || sv.T != hcl.TCapsule {
		return convErr("cannot extract schema name for table %q: schemahcl: type \"schema\" was not found in nil reference", t.Name)
	}
	sr, isRef := sv.Cap.(*SchemaRef)
	if !isRef {
		return convErr("cannot extract schema name for table %q", t.Name)
	}
	s, _ := realm.Schema(sr.Name)
	s.AddTables(t)
	for _, cb := range body.Blocks {
		if cb.Type != "column" || len(cb.Labels) == 0 {
			continue
		}
		c := &schema.Column{Name: cb.Labels[0]}
		ct, err := evalType(cb, ctx)
		if err != nil {
			return err
		}
		null, err := boolAttr(cb.Body, "null", ctx)
		if err != nil {
			return err
		}
		if ct == nil {
			return convErr("cannot convert table %q: specutil: nil type", t.Name)
		}
		ct.Null = null
		c.Type = ct
		if dv, ok, err := evalAttr(cb.Body, "default", ctx); err != nil {
			return err
		} else if ok {
			switch dv.T {
			case hcl.TString:
				c.Default = &schema.Literal{V: dv.S}
			case hcl.TNumber:
				c.Default = &schema.Literal{V: hcl.NumberString(dv.N)}
			case hcl.TBool:
				c.Default = &schema.Literal{V: fmt.Sprint(dv.B)}
			case hcl.TCapsule:
				if r, ok := dv.Cap.(*RawSQL); ok {
					c.Default = &schema.RawExpr{X: r.X}
				}
			}
		}
		ai, err := boolAttr(cb.Body, "auto_increment", ctx)
		if err != nil {
			return err
		}
		c.AutoIncrement = ai
		if x, ok, err := stringAttr(cb.Body, "collate", ctx); err != nil {
			return err
		} else if ok {
			c.Collation = x
		}
		if a, ok := cb.Body.Attributes["as"]; ok {
			v, diags := hcl.Eval(a.Expr, ctx)
			if diags.HasErrors() {
				return diags
			}
			if v.T == hcl.TString {
				c.Generated = &schema.Generated{Expr: v.S, Type: "VIRTUAL"}
			}
		}
		for _, ab := range cb.Body.Blocks {
			if ab.Type == "as" {
				x, _, err := stringAttr(ab.Body, "expr", ctx)
				if err != nil {
					return err
				}
				typ, err := evalEnum(ab, "type", []string{"VIRTUAL", "STORED"}, ctx)
				if err != nil {
					return err
				}
				if typ == "" {
					typ = "VIRTUAL"
				}
				c.Generated = &schema.Generated{Expr: x, Type: typ}
			}
		}
		t.Columns = append(t.Columns, c)
	}
	wr, err := boolAttr(body, "without_rowid", ctx)
	if err != nil {
		return err
	}
	t.WithoutRowID = wr
	st, err := boolAttr(body, "strict", ctx)
	if err != nil {
		return err
	}
	t.Strict = st
	return nil
}

func colRefs(v hcl.Value, name string) ([]*ColRef, error) {
	if v.T == hcl.TNull {
		return nil, nil
	}
	if v.T != hcl.TTuple {
		return nil, specErr("expected list of references for attr %q", name)
	}
	var out []*ColRef
	for _, e := range v.L {
		r, ok := e.Cap.(*ColRef)
		if !ok {
			return nil, specErr("expected reference for attr %q", name)
		}
		out = append(out, r)
	}
	return out, nil
}

func indexParts(b *hcl.Block, t *schema.Table, ctx *hcl.EvalContext) ([]*schema.IndexPart, error) {
	var parts []*schema.IndexPart
	if v, ok, err := evalAttr(b.Body, "columns", ctx); err != nil {
		return nil, err
	} else if ok {
		refs, err := colRefs(v, "columns")
		if err != nil {
			return nil, err
		}
		for _, r := range refs {
			c, ok := t.Column(r.Column)
			if !ok {
				return nil, convErr("column %q was not found in table %q", r.Column, t.Name)
			}
			parts = append(parts, &schema.IndexPart{SeqNo: len(parts) + 1, C: c})
		}
	}
	for _, ob := range b.Body.Blocks {
		if ob.Type != "on" {
			continue
		}
		p := &schema.IndexPart{SeqNo: len(parts) + 1}
		desc, err := boolAttr(ob.Body, "desc", ctx)
		if err != nil {
			return nil, err
		}
		p.Desc = desc
		if v, ok, err := evalAttr(ob.Body, "column", ctx); err != nil {
			return nil, err
		} else if ok {
			r, isRef := v.Cap.(*ColRef)
			if !isRef {
				return nil, specErr("expected reference for attr \"column\"")
			}
			c, ok := t.Column(r.Column)
			if !ok {
				return nil, convErr("column %q was not found in table %q", r.Column, t.Name)
			}
			p.C = c
		}
		if x, ok, err := stringAttr(ob.Body, "expr", ctx); err != nil {
			return nil, err
		} else if ok {
			p.X = &schema.RawExpr{X: x}
		}
		parts = append(parts, p)
	}
	return parts, nil
}

func convertTableKeys(b *hcl.Block, t *schema.Table, ctx *hcl.EvalContext, tables map[string]*schema.Table) error {
	body := b.Body
	for _, kb := range body.Blocks {
		switch kb.Type {
		case "primary_key":
			parts, err := indexParts(kb, t, ctx)
			if err != nil {
				return err
			}
			t.PrimaryKey = &schema.Index{Unique: true, Table: t, Parts: parts}
		case "index":
			idx := &schema.Index{Table: t}
			if len(kb.Labels) > 0 {
				idx.Name = kb.Labels[0]
			}
			u, err := boolAttr(kb.Body, "unique", ctx)
			if err != nil {
				return err
			}
			idx.Unique = u
			parts, err := indexParts(kb, t, ctx)
			if err != nil {
				return err
			}
			idx.Parts = parts
			if w, ok, err := stringAttr(kb.Body, "where", ctx); err != nil {
				return err
			} else if ok {
				idx.Where = w
			}
			for _, p := range parts {
				if p.C != nil {
					p.C.Indexes = append(p.C.Indexes, idx)
				}
			}
			t.Indexes = append(t.Indexes, idx)
		case "foreign_key":
			fk := &schema.ForeignKey{Table: t}
			if len(kb.Labels) > 0 {
				fk.Symbol = kb.Labels[0]
			}
			v, _, err := evalAttr(kb.Body, "columns", ctx)
			if err != nil {
				return err
			}
			refs, err := colRefs(v, "columns")
			if err != nil {
				return err
			}
			for _, r := range refs {
				c, ok := t.Column(r.Column)
				if !ok {
					return convErr("column %q was not found in table %q", r.Column, t.Name)
				}
				fk.Columns = append(fk.Columns, c)
				c.ForeignKeys = append(c.ForeignKeys, fk)
			}
			v, _, err = evalAttr(kb.Body, "ref_columns", ctx)
			if err != nil {
				return err
			}
			refs, err = colRefs(v, "ref_columns")
			if err != nil {
				return err
			}
			for _, r := range refs {
				rt, ok := tables[r.Table]
				if !ok {
					return convErr("referenced table %q was not found", r.Table)
				}
				c, ok := rt.Column(r.Column)
				if !ok {
					return convErr("column %q was not found in table %q", r.Column, rt.Name)
				}
				fk.RefTable = rt
				fk.RefColumns = append(fk.RefColumns, c)
			}
			if fk.RefTable == nil {
				fk.RefTable = t
			}
			actions := []string{"NO_ACTION", "RESTRICT", "CASCADE", "SET_NULL", "SET_DEFAULT"}
			if fk.OnUpdate, err = evalEnum(kb, "on_update", actions, ctx); err != nil {
				return err
			}
			if fk.OnDelete, err = evalEnum(kb, "on_delete", actions, ctx); err != nil {
				return err
			}
			fk.OnUpdate = strings.ReplaceAll(fk.OnUpdate, "_", " ")
			fk.OnDelete = strings.ReplaceAll(fk.OnDelete, "_", " ")
			t.ForeignKeys = append(t.ForeignKeys, fk)
		case "check":
			ch := &schema.Check{}
			if len(kb.Labels) > 0 {
				ch.Name = kb.Labels[0]
			}
			x, _, err := stringAttr(kb.Body, "expr", ctx)
			if err != nil {
				return err
			}
			ch.Expr = x
			t.Checks = append(t.Checks, ch)
		}
	}
	return nil
}
