// DiffSchemas computes the changes needed to move from -> to.
func DiffSchemas(from, to *schema.Schema) []schema.Change {
	var changes []schema.Change
	for _, t1 := range from.Tables {
		t2, ok := to.Table(t1.Name)
		if !ok {
			changes = append(changes, &schema.DropTable{T: t1})
			continue
		}
