			changes = append(changes, &schema.ModifyTable{T: t2, From: t1, Changes: c})
		}
	}
	for _, t2 := range to.Tables {
		if _, ok := from.Table(t2.Name); !ok {
			changes = append(changes, &schema.AddTable{T: t2})
		}
	}
	return changes
}

