	d2, ok2 := defaultValue(to)
	if ok1 != ok2 {
		return true
	}
	if d1 == d2 {
		return false
	}
	x1, _ := unquoteLit(d1)
	x2, _ := unquoteLit(d2)
	return x1 != x2
}

func normExpr(x string) string {
	x = strings.TrimSpace(x)
	for {
		y := stripParens(x)
		if y == x {
			return x
		}
		x = strings.TrimSpace(y)
	}
}

