package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"atlasre/internal/schema"
	"atlasre/internal/spec"
	"atlasre/internal/sqlite"

	"github.com/spf13/cobra"
)

var errDevEmptySQL = errors.New("--dev-url cannot be empty. See: https://atlasgo.io/atlas-schema/sql#dev-database")

type stateKind int

const (
	stateHCL stateKind = iota
	stateSQL
	stateMigrateDir
	stateDB
)

func filePath(raw string) (string, error) {
	u, err := parseURL(raw)
	if err != nil {
		return "", err
	}
	return filepath.Join(u.Host, u.Path), nil
}

// classify returns the kind of a file:// state URL.
func classify(p string) (stateKind, error) {
	fi, err := os.Stat(p)
	if err != nil {
		return 0, err
	}
	if fi.IsDir() {
		entries, err := os.ReadDir(p)
		if err != nil {
			return 0, err
		}
		for _, e := range entries {
			if !e.IsDir() && strings.HasSuffix(e.Name(), ".hcl") {
				return stateHCL, nil
			}
		}
		return stateMigrateDir, nil
	}
	switch filepath.Ext(p) {
	case ".hcl":
		return stateHCL, nil
	case ".sql":
		return stateSQL, nil
	}
	return 0, fmt.Errorf("unknown schema file: %q", filepath.Base(p))
}

// devConn returns a connection used as a dev database.
func openDev(devURL string) (*sqlite.Conn, error) {
	if devURL != "" {
		c, err := OpenClient(devURL)
		if err != nil {
			return nil, err
		}
