// Package migrate implements versioned migration directories.
package migrate

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// HashFileName is the name of the sum file.
const HashFileName = "atlas.sum"

// File is a migration file.
type File struct {
	Name  string
	Bytes []byte
}

// Version returns the version part of the file name.
func (f *File) Version() string {
	n := strings.TrimSuffix(f.Name, ".sql")
	if i := strings.Index(n, "_"); i >= 0 {
		return n[:i]
	}
	return n
}

// Desc returns the description part of the file name.
func (f *File) Desc() string {
	n := strings.TrimSuffix(f.Name, ".sql")
	if i := strings.Index(n, "_"); i >= 0 {
		return n[i+1:]
	}
	return ""
}

// Dir is a local migration directory.
type Dir struct {
	Path string
}

// OpenDir opens a local directory, verifying it exists.
func OpenDir(path string) (*Dir, error) {
	fi, err := os.Stat(path)
	if err != nil {
		return nil, fmt.Errorf("sql/migrate: %w", err)
	}
	if !fi.IsDir() {
		return nil, fmt.Errorf("sql/migrate: %q is not a dir", path)
	}
	return &Dir{Path: path}, nil
}

// Files returns the migration files sorted by name.
func (d *Dir) Files() ([]*File, error) {
	entries, err := os.ReadDir(d.Path)
	if err != nil {
		return nil, err
	}
	var files []*File
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".sql") {
			continue
		}
		b, err := os.ReadFile(filepath.Join(d.Path, e.Name()))
		if err != nil {
			return nil, err
		}
		files = append(files, &File{Name: e.Name(), Bytes: b})
	}
	sort.Slice(files, func(i, j int) bool { return files[i].Name < files[j].Name })
	return files, nil
}

// WriteFile writes a file to the directory.
func (d *Dir) WriteFile(name string, b []byte) error {
	return os.WriteFile(filepath.Join(d.Path, name), b, 0644)
}

// HashEntry is a single line of the sum file.
type HashEntry struct{ N, H string }

// HashFile is the content of atlas.sum.
type HashFile []HashEntry

// NewHashFile computes the hash file of the given files.
func NewHashFile(files []*File) HashFile {
	var hs HashFile
	h := sha256.New()
	for _, f := range files {
		h.Write([]byte(f.Name))
		if mode, ok := directive(string(f.Bytes), "sum"); ok && mode == "ignore" {
			continue
		}
		h.Write(f.Bytes)
		hs = append(hs, HashEntry{f.Name, base64.StdEncoding.EncodeToString(h.Sum(nil))})
	}
	return hs
}

