func dirPath(raw string) (string, error) {
	u, err := parseURL(raw)
	if err != nil {
		return "", err
	}
	if u.Scheme == "" {
		return "", fmt.Errorf("missing scheme for dir url. Did you mean %q? ", "file://"+raw)
	}
	if u.Scheme != "file" {
		return "", fmt.Errorf("unsupported driver %q", u.Scheme)
	}
	return filepath.Join(u.Host, u.Path), nil
}

func checkDirFormat(f string) error {
	switch f {
	case "", "atlas":
		return nil
	case "golang-migrate", "goose", "flyway", "liquibase", "dbmate":
		return nil
	}
	return fmt.Errorf("unknown dir format %q", f)
}

func openMigrateDir(raw, format string, create bool) (*migrate.Dir, error) {
	if err := checkDirFormat(format); err != nil {
		return nil, err
	}
	p, err := dirPath(raw)
	if err != nil {
		return nil, err
	}
	if create {
		if err := os.MkdirAll(p, 0755); err != nil {
			return nil, err
		}
	}
	return migrate.OpenDir(p)
}

// validateDir checks the checksum, printing the report on failure.
func validateDir(cmd *cobra.Command, d *migrate.Dir) error {
	if err := d.Validate(); err != nil {
		var ce *migrate.ChecksumError
		if errors.As(err, &ce) {
			fmt.Fprint(cmd.OutOrStdout(), ce.Report())
		}
		return err
	}
	return nil
}

func runMigrateHash(cmd *cobra.Command, f *migrateFlags) error {
	d, err := openMigrateDir(f.dir, f.dirFormat, false)
	if err != nil {
		return err
	}
	return d.WriteSum()
}

func runMigrateNew(cmd *cobra.Command, f *migrateFlags, args []string) error {
	if len(args) > 1 {
		return cobra.MaximumNArgs(1)(cmd, args)
	}
	d, err := openMigrateDir(f.dir, f.dirFormat, true)
	if err != nil {
		return err
	}
	if err := validateDir(cmd, d); err != nil {
		return err
	}
	name := time.Now().UTC().Format("20060102150405")
	if len(args) > 0 && args[0] != "" {
		name += "_" + args[0]
	}
	if err := d.WriteFile(name+".sql", nil); err != nil {
		return err
	}
	return d.WriteSum()
}

func runMigrateValidate(cmd *cobra.Command, f *migrateFlags) error {
	d, err := openMigrateDir(f.dir, f.dirFormat, false)
	if err != nil {
		return err
	}
	if err := validateDir(cmd, d); err != nil {
		return err
	}
	if f.devURL != "" {
		if _, err := replayDir(d.Path, f.devURL, ""); err != nil {
			return fmt.Errorf("replaying the migration directory: %w", err)
		}
	}
	return nil
}

// checkClean verifies the dev database is clean.
func checkClean(c *sqlite.Conn) error {
	rows, err := c.Query("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'")
	if err != nil {
		return err
	}
	if len(rows.Values) > 0 {
		return fmt.Errorf("sql/migrate: connected database is not clean: found table %q", sqliteStr(rows.Values[0][0]))
	}
	return nil
}

func sqliteStr(v interface{}) string {
	switch v := v.(type) {
	case string:
		return v
	case []byte:
		return string(v)
	case int64:
		return strconv.FormatInt(v, 10)
	}
	return ""
}

// replayDir executes the migration directory on a dev database and inspects it.
func replayDir(path, devURL, toVersion string) (*schema.Realm, error) {
	c, err := OpenClient(devURL)
	if err != nil {
		return nil, err
	}
	if err := checkClean(c.Conn); err != nil {
		c.Close()
		return nil, fmt.Errorf("sql/migrate: taking database snapshot: %w", err)
	}
	c.Close()
	conn, err := sqlite.Open("file:atlas_replay?mode=memory")
	if err != nil {
		return nil, err
	}
	defer conn.Close()
	d, err := migrate.OpenDir(path)
	if err != nil {
		return nil, err
	}
	files, err := d.Files()
	if err != nil {
		return nil, err
	}
	for _, f := range files {
		stmts, err := migrate.Stmts(string(f.Bytes))
		if err != nil {
			return nil, err
		}
		for _, s := range stmts {
			if _, err := conn.Exec(s.Text); err != nil {
				return nil, fmt.Errorf("sql/migrate: executing statement %q from version %q: %s", s.Text, f.Version(), err)
			}
		}
		if toVersion != "" && f.Version() == toVersion {
			break
		}
	}
	res, err := sqlite.InspectRealm(conn)
	if err != nil {
		return nil, err
	}
	return res.Realm, nil
}

func splitStatements(s string) ([]string, error) {
	stmts, err := migrate.Stmts(s)
	if err != nil {
		return nil, err
	}
	var out []string
	for _, st := range stmts {
		out = append(out, st.Text)
	}
	return out, nil
}

// lockFile acquires the migrate execution lock.
func lockFile(timeout time.Duration) (func(), error) {
	p := filepath.Join(os.TempDir(), "atlas_migrate_execute.lock")
	deadline := time.Now().Add(timeout)
	for {
		f, err := os.OpenFile(p, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0644)
		if err == nil {
			fmt.Fprintf(f, "%d", time.Now().UnixNano()^int64(os.Getpid())<<20)
			f.Close()
			return func() { os.Remove(p) }, nil
		}
		if !os.IsExist(err) || time.Now().After(deadline) {
			return nil, errors.New("acquiring database lock: sql/sqlite: lock on \"atlas_migrate_execute\" already taken")
		}
		time.Sleep(100 * time.Millisecond)
	}
}

func ensureRevisions(c *sqlite.Conn) error {
	rows, err := c.Query("SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?", revTable)
	if err != nil {
		return err
	}
	if len(rows.Values) > 0 {
		return nil
	}
	_, err = c.Exec(revTableDDL)
	return err
}

func readRevisions(c *sqlite.Conn) ([]*Revision, error) {
	rows, err := c.Query("SELECT `version`, `description`, `type`, `applied`, `total`, `executed_at`, `execution_time`, `error`, `error_stmt`, `hash`, `operator_version` FROM `atlas_schema_revisions` ORDER BY `version`")
	if err != nil {
		return nil, err
	}
	var revs []*Revision
	for _, r := range rows.Values {
		rev := &Revision{
			Version: sqliteStr(r[0]), Description: sqliteStr(r[1]), Type: toInt(r[2]), Applied: toInt(r[3]), Total: toInt(r[4]),
			ExecutedAt: sqliteStr(r[5]), ExecutionTime: toInt(r[6]), Error: sqliteStr(r[7]), ErrorStmt: sqliteStr(r[8]), Hash: sqliteStr(r[9]), OperatorVersion: sqliteStr(r[10]),
		}
		revs = append(revs, rev)
	}
	return revs, nil
}

func toInt(v interface{}) int64 {
	switch v := v.(type) {
	case int64:
		return v
	case float64:
		return int64(v)
	case string:
		i, _ := strconv.ParseInt(v, 10, 64)
		return i
	}
	return 0
}

const timeFormat = "2006-01-02 15:04:05.999999999-07:00"

func writeRevision(c *sqlite.Conn, r *Revision) error {
	_, err := c.Exec("INSERT INTO `atlas_schema_revisions` (`version`, `description`, `type`, `applied`, `total`, `executed_at`, `execution_time`, `error`, `error_stmt`, `hash`, `partial_hashes`, `operator_version`) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (`version`) DO UPDATE SET `description` = excluded.`description`, `type` = excluded.`type`, `applied` = excluded.`applied`, `total` = excluded.`total`, `executed_at` = excluded.`executed_at`, `execution_time` = excluded.`execution_time`, `error` = excluded.`error`, `error_stmt` = excluded.`error_stmt`, `hash` = excluded.`hash`, `partial_hashes` = excluded.`partial_hashes`, `operator_version` = excluded.`operator_version`",
		r.Version, r.Description, r.Type, r.Applied, r.Total, r.ExecutedAt, r.ExecutionTime, r.Error, r.ErrorStmt, r.Hash, []byte("null"), r.OperatorVersion)
	return err
}

func deleteRevision(c *sqlite.Conn, version string) error {
	_, err := c.Exec("DELETE FROM `atlas_schema_revisions` WHERE `version` = ?", version)
	return err
}

// dbCleanCheck verifies a fresh database is clean for migration.
func dbCleanCheck(c *sqlite.Conn) error {
	rows, err := c.Query("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'")
	if err != nil {
		return err
	}
	switch n := len(rows.Values); {
	case n > 1:
		return fmt.Errorf("sql/migrate: connected database is not clean: found multiple tables: %d. baseline version or allow-dirty is required", n)
	case n == 1 && sqliteStr(rows.Values[0][0]) != revTable:
		return fmt.Errorf("sql/migrate: connected database is not clean: found table %q. baseline version or allow-dirty is required", sqliteStr(rows.Values[0][0]))
	}
	return nil
}

func plural(n int, s string) string {
	if n == 1 {
		return fmt.Sprintf("%d %s", n, s)
	}
	return fmt.Sprintf("%d %ss", n, s)
}

func indentStmt(s string) string {
	return strings.ReplaceAll(s, "\n", "\n       ")
}

func fileHashes(files []*migrate.File) map[string]string {
	hf := migrate.NewHashFile(files)
	m := map[string]string{}
	for _, e := range hf {
		m[e.N] = e.H
	}
	return m
}

func revisionsSchemaCheck(name string) error {
	if name != "" && name != "main" {
		return fmt.Errorf("cannot store revisions-table in a separate schema (%q) with SQLite driver", name)
	}
	return nil
}

func runMigrateApply(cmd *cobra.Command, f *migrateFlags, args []string) error {
	if len(args) > 1 {
		return cobra.MaximumNArgs(1)(cmd, args)
	}
	d, err := openMigrateDir(f.dir, "", false)
	if err != nil {
		return err
	}
	if err := validateDir(cmd, d); err != nil {
		return err
	}
	amount := 0
	if len(args) > 0 {
		n, err := strconv.ParseUint(args[0], 10, 64)
		if err != nil {
			var ne *strconv.NumError
			reason := err.Error()
			if errors.As(err, &ne) {
				reason = ne.Err.Error()
			}
			return fmt.Errorf("invalid amount argument %q (%s). Omit the argument or pass a valid integer instead", args[0], reason)
		}
		if n == 0 {
			return fmt.Errorf("cannot apply '0' migration files")
		}
		amount = int(n)
	}
	if f.url == "" {
		return errors.New("required flag \"url\" not set")
	}
	switch f.execOrder {
	case "linear", "linear-skip", "non-linear":
	default:
		return fmt.Errorf("unknown execution order: %q", f.execOrder)
	}
	c, err := OpenClient(f.url)
	if err != nil {
		return err
	}
	defer c.Close()
	if err := revisionsSchemaCheck(f.revSchema); err != nil {
		return err
	}
	unlock, err := lockFile(f.lockTimeout)
	if err != nil {
		return err
	}
	defer unlock()
	if err := ensureRevisions(c.Conn); err != nil {
		return err
	}
	revs, err := readRevisions(c.Conn)
	if err != nil {
		return err
	}
	files, err := d.Files()
	if err != nil {
		return err
	}
	hashes := fileHashes(files)
	if len(revs) == 0 {
		if f.baseline != "" {
			var bf *migrate.File
			for _, fl := range files {
				if fl.Version() == f.baseline {
					bf = fl
				}
			}
			if bf == nil {
				return fmt.Errorf("baseline version %q not found", f.baseline)
			}
			rev := &Revision{Version: bf.Version(), Description: bf.Desc(), Type: revTypeBaseline, ExecutedAt: time.Now().Format(timeFormat), OperatorVersion: operatorVersion}
			if !f.dryRun {
				if err := writeRevision(c.Conn, rev); err != nil {
					return err
				}
			}
			revs = append(revs, rev)
		} else if !f.allowDirty {
			if err := dbCleanCheck(c.Conn); err != nil {
				return err
			}
		}
	}
	applied := map[string]*Revision{}
	var lastApplied string
	for _, r := range revs {
		applied[r.Version] = r
		if r.Version > lastApplied {
			lastApplied = r.Version
		}
	}
	var pending []*migrate.File
	for _, fl := range files {
		if r, ok := applied[fl.Version()]; ok && (r.Type&revTypeBaseline != 0 || r.Type&revTypeResolved != 0 || r.Applied == r.Total) {
			continue
		}
		if f.baseline != "" && fl.Version() <= f.baseline {
			continue
		}
		if f.execOrder == "linear" || f.execOrder == "" {
			if lastApplied != "" && fl.Version() < lastApplied {
				continue
			}
		}
		pending = append(pending, fl)
	}
	if amount > 0 && amount < len(pending) {
		pending = pending[:amount]
	}
	out := cmd.OutOrStdout()
	if len(pending) == 0 {
		fmt.Fprintln(out, "No migration files to execute")
		return nil
	}
	start := time.Now()
	target := pending[len(pending)-1].Version()
	if lastApplied != "" {
		fmt.Fprintf(out, "Migrating to version %s from %s (%d migrations in total):\n\n", target, lastApplied, len(pending))
	} else {
		fmt.Fprintf(out, "Migrating to version %s (%d migrations in total):\n\n", target, len(pending))
	}
	switch f.txMode {
	case "file", "none", "all":
	default:
		fmt.Fprintf(out, "    unknown tx-mode %q\n\n", f.txMode)
		fmt.Fprintf(out, "  -------------------------\n  -- %s\n", time.Duration(-1<<63))
		return fmt.Errorf("unknown tx-mode %q", f.txMode)
	}
	var (
		okFiles, errFiles int
		okStmts, errStmts int
		execErr           error
	)
	if f.txMode == "all" && !f.dryRun {
		if _, err := c.Conn.Exec("BEGIN"); err != nil {
			return err
		}
	}
	for _, fl := range pending {
		fmt.Fprintf(out, "  -- migrating version %s\n", fl.Version())
		stmts, err := migrate.Stmts(string(fl.Bytes))
		if err != nil {
			return err
		}
		fstart := time.Now()
		if f.txMode == "file" && !f.dryRun {
			if _, err := c.Conn.Exec("BEGIN"); err != nil {
				return err
			}
		}
		var failed error
		var failedStmt string
		n := 0
		for _, s := range stmts {
			fmt.Fprintf(out, "    -> %s\n", indentStmt(s.Text))
			if f.dryRun {
				n++
				continue
			}
			if _, err := c.Conn.Exec(s.Text); err != nil {
				failed = err
				failedStmt = s.Text
				break
			}
			n++
		}
		okStmts += n
		if failed != nil {
			errStmts++
			errFiles++
			fmt.Fprintf(out, "    %s\n\n", failed)
			if f.txMode == "file" || f.txMode == "all" {
				c.Conn.Exec("ROLLBACK")
			} else {
				rev := &Revision{Version: fl.Version(), Description: fl.Desc(), Type: revTypeExecute, Applied: int64(n), Total: int64(len(stmts)), ExecutedAt: fstart.Format(timeFormat), ExecutionTime: int64(time.Since(fstart)), Error: failed.Error(), ErrorStmt: failedStmt, Hash: hashes[fl.Name], OperatorVersion: operatorVersion}
				writeRevision(c.Conn, rev)
			}
			execErr = fmt.Errorf("sql/migrate: executing statement %q from version %q: %s", failedStmt, fl.Version(), failed)
			break
		}
		if !f.dryRun {
			rev := &Revision{Version: fl.Version(), Description: fl.Desc(), Type: revTypeExecute, Applied: int64(n), Total: int64(len(stmts)), ExecutedAt: fstart.Format(timeFormat), ExecutionTime: int64(time.Since(fstart)), Hash: hashes[fl.Name], OperatorVersion: operatorVersion}
			if err := writeRevision(c.Conn, rev); err != nil {
				return err
			}
			if f.txMode == "file" {
				if _, err := c.Conn.Exec("COMMIT"); err != nil {
					return err
				}
			}
		}
		okFiles++
		fmt.Fprintf(out, "  -- ok (%s)\n\n", time.Since(fstart))
	}
	if f.txMode == "all" && !f.dryRun {
		if execErr != nil {
			c.Conn.Exec("ROLLBACK")
		} else if _, err := c.Conn.Exec("COMMIT"); err != nil {
			return err
		}
	}
	fmt.Fprintf(out, "  -------------------------\n")
	fmt.Fprintf(out, "  -- %s\n", time.Since(start))
	if execErr != nil {
		switch {
		case okFiles > 0:
			fmt.Fprintf(out, "  -- %s ok, %d with errors\n", plural(okFiles, "migration"), errFiles)
		default:
			fmt.Fprintf(out, "  -- %d migration with errors\n", errFiles)
		}
		if okStmts > 0 {
			fmt.Fprintf(out, "  -- %s ok, %d with errors\n", plural(okStmts, "sql statement"), errStmts)
		} else {
			fmt.Fprintf(out, "  -- %d sql statement with errors\n", errStmts)
		}
		return execErr
	}
	fmt.Fprintf(out, "  -- %s\n", plural(okFiles, "migration"))
	fmt.Fprintf(out, "  -- %s\n", plural(okStmts, "sql statement"))
	return nil
}

const operatorVersion = "Atlas CLI - development"

func runMigrateStatus(cmd *cobra.Command, f *migrateFlags) error {
	d, err := openMigrateDir(f.dir, f.dirFormat, false)
	if err != nil {
		return err
	}
	if err := validateDir(cmd, d); err != nil {
		return err
	}
	if f.url == "" {
		return errors.New("sql/sqlclient: missing driver. See: https://atlasgo.io/url")
	}
	c, err := OpenClient(f.url)
	if err != nil {
		return err
	}
	defer c.Close()
	if err := revisionsSchemaCheck(f.revSchema); err != nil {
		return err
	}
	if err := ensureRevisions(c.Conn); err != nil {
		return err
	}
	revs, err := readRevisions(c.Conn)
	if err != nil {
		return err
	}
	if len(revs) == 0 {
		if err := dbCleanCheck(c.Conn); err != nil {
			return err
		}
	}
	files, err := d.Files()
	if err != nil {
		return err
	}
	applied := map[string]*Revision{}
	var current string
	for _, r := range revs {
		applied[r.Version] = r
		if r.Version > current {
			current = r.Version
		}
	}
	var pending []*migrate.File
	executed := 0
	for _, fl := range files {
		if r, ok := applied[fl.Version()]; ok {
			if r.Type&revTypeBaseline == 0 {
				executed++
			}
			continue
		}
		if current != "" && fl.Version() < current {
			continue
		}
		pending = append(pending, fl)
	}
	out := cmd.OutOrStdout()
	status := "OK"
	if len(pending) > 0 {
		status = "PENDING"
	}
	cur := current
	if cur == "" {
		cur = "No migration applied yet"
	}
	next := "Already at latest version"
	if len(pending) > 0 {
		next = pending[0].Version()
	}
	fmt.Fprintf(out, "Migration Status: %s\n", status)
	fmt.Fprintf(out, "  -- Current Version: %s\n", cur)
	fmt.Fprintf(out, "  -- Next Version:    %s\n", next)
	fmt.Fprintf(out, "  -- Executed Files:  %d\n", executed)
	fmt.Fprintf(out, "  -- Pending Files:   %d\n", len(pending))
	return nil
}

func runMigrateSet(cmd *cobra.Command, f *migrateFlags, args []string) error {
	if len(args) > 1 {
		return cobra.ExactArgs(1)(cmd, args)
	}
	d, err := openMigrateDir(f.dir, f.dirFormat, false)
	if err != nil {
		return err
	}
	if err := validateDir(cmd, d); err != nil {
		return err
	}
	if f.url == "" {
		return errors.New("sql/sqlclient: missing driver. See: https://atlasgo.io/url")
	}
	c, err := OpenClient(f.url)
	if err != nil {
		return err
	}
	defer c.Close()
	if err := revisionsSchemaCheck(f.revSchema); err != nil {
		return err
	}
	files, err := d.Files()
	if err != nil {
		return err
	}
	var target *migrate.File
	if len(args) == 0 {
		if len(files) > 0 {
			target = files[len(files)-1]
		}
	} else {
		for _, fl := range files {
			if fl.Version() == args[0] {
				target = fl
			}
		}
		if target == nil {
			return fmt.Errorf("migration with version %q not found", args[0])
		}
	}
	if target == nil {
		return errors.New("no migration files found")
	}
	if err := ensureRevisions(c.Conn); err != nil {
		return err
	}
	revs, err := readRevisions(c.Conn)
	if err != nil {
		return err
	}
	applied := map[string]*Revision{}
	for _, r := range revs {
		applied[r.Version] = r
	}
	hashes := fileHashes(files)
	var set, removed []*migrate.File
	for _, fl := range files {
		if fl.Version() <= target.Version() {
			if _, ok := applied[fl.Version()]; !ok {
				set = append(set, fl)
			}
		} else if _, ok := applied[fl.Version()]; ok {
			removed = append(removed, fl)
		}
	}
	for _, fl := range set {
		rev := &Revision{Version: fl.Version(), Description: fl.Desc(), Type: revTypeResolved, ExecutedAt: time.Now().Format(timeFormat), Hash: hashes[fl.Name], OperatorVersion: operatorVersion}
		if err := writeRevision(c.Conn, rev); err != nil {
			return err
		}
	}
	for _, fl := range removed {
		if err := deleteRevision(c.Conn, fl.Version()); err != nil {
			return err
		}
	}
	if len(set) == 0 && len(removed) == 0 {
		return nil
	}
	out := cmd.OutOrStdout()
	var parts []string
	if len(set) > 0 {
		parts = append(parts, fmt.Sprintf("%d set", len(set)))
	}
	if len(removed) > 0 {
		parts = append(parts, fmt.Sprintf("%d removed", len(removed)))
	}
	fmt.Fprintf(out, "Current version is %s (%s):\n\n", target.Version(), strings.Join(parts, ", "))
	for _, fl := range set {
		fmt.Fprintf(out, "  + %s (%s)\n", fl.Version(), fl.Desc())
	}
	for _, fl := range removed {
		fmt.Fprintf(out, "  - %s (%s)\n", fl.Version(), fl.Desc())
	}
	fmt.Fprintln(out)
	return nil
}

func runMigrateImport(cmd *cobra.Command, f *migrateFlags) error {
	if err := checkDirFormat(f.dirFormat); err != nil {
		return err
	}
	if _, err := dirPath(f.from); err != nil {
		return err
	}
	if f.dirFormat == "atlas" || f.dirFormat == "" {
		u, _ := parseURL(f.from)
		if u.Query().Get("format") == "" || u.Query().Get("format") == "atlas" {
			return errors.New("cannot import a migration directory already in \"atlas\" format")
		}
	}
	return errors.New("import is not supported")
}
