)

// mainSchema returns the single schema of a realm, validating HCL schemas.
func targetSchema(r *schema.Realm, fromHCL bool) (*schema.Schema, error) {
	if len(r.Schemas) == 0 {
		return &schema.Schema{Name: "main", Realm: r}, nil
	}
	if len(r.Schemas) > 1 {
		return nil, errors.New("cannot use HCL with more than 1 schema when url is limited to schema \"main\"")
	}
	s := r.Schemas[0]
	if fromHCL && s.Name != "main" {
		return nil, fmt.Errorf("mismatched HCL and database schemas: %q <> %q", "main", s.Name)
	}
	return s, nil
}

func isHCLURLs(urls []string) bool {
	for _, raw := range urls {
		u, err := parseURL(raw)
		if err != nil || u.Scheme != "file" {
			return false
		}
		p, _ := filePath(raw)
		if k, err := classify(p); err == nil && k == stateHCL {
			return true
		}
	}
	return false
}

func planOutput(plan *sqlite.Plan) string {
	return cmdlog.PlanSQL(plan)
}

func runSchemaApply(cmd *cobra.Command, f *schemaFlags) error {
	format := f.format
	if f.logFormat != "" {
		format = f.logFormat
	}
	var tmpl *template.Template
	if format != "" {
		t, err := template.New("format").Funcs(cmdlog.Funcs).Parse(format)
		if err != nil {
			return fmt.Errorf("parse format: %w", err)
		}
		tmpl = t
	}
	if len(f.to) == 0 {
		return errors.New("one of flag(s) \"file\" or \"to\" is required")
	}
	switch f.txMode {
	case "none", "file":
	default:
		return fmt.Errorf("unknown tx-mode %q", f.txMode)
	}
	c, err := OpenClient(f.url)
	if err != nil {
		return err
	}
	defer c.Close()
	res, err := sqlite.InspectRealm(c.Conn)
	if err != nil {
		return err
	}
	if res.HasViews {
		maybeViewsNotice()
	}
	fromHCL := isHCLURLs(f.to)
	desired, _, err := loadState(f.to, f.devURL, true)
	if err != nil {
		return err
	}
	cur := res.Realm.Schemas[0]
	to, err := targetSchema(desired, fromHCL)
	if err != nil {
		return err
	}
	if err := applyExclude(res.Realm, f.exclude); err != nil {
		return err
	}
	if err := applyExclude(desired, f.exclude); err != nil {
		return err
	}
	changes := sqlite.DiffSchemas(cur, to)
	out := cmd.OutOrStdout()
	if len(changes) == 0 {
		if tmpl != nil {
			return tmpl.Execute(out, &cmdlog.SchemaApply{})
		}
		fmt.Fprintln(out, "Schema is synced, no changes to be made")
		return nil
	}
	plan, err := sqlite.PlanChanges(changes, "  ")
	if err != nil {
		return err
	}
	if tmpl != nil && f.dryRun {
		return tmpl.Execute(out, cmdlog.NewSchemaApply(plan, nil))
	}
	if tmpl == nil {
		fmt.Fprintln(out, "-- Planned Changes:")
		fmt.Fprint(out, planOutput(plan))
	}
	if f.dryRun {
		return nil
	}
	if !f.autoApprove {
		ok, err := promptApply(out)
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	applied, err := execPlan(c, plan, f.txMode)
	if tmpl != nil {
		return tmpl.Execute(out, cmdlog.NewSchemaApply(plan, applied))
	}
	return err
}

// execPlan executes the plan statements on the client.
func execPlan(c *Client, plan *sqlite.Plan, txMode string) ([]*sqlite.PlanChange, error) {
	var applied []*sqlite.PlanChange
	tx := txMode != "none"
	// PRAGMA foreign_keys is a no-op inside transactions; execute it outside.
	var pre, post []*sqlite.PlanChange
	body := plan.Changes
	if len(body) > 0 && strings.HasPrefix(body[0].Cmd, "PRAGMA foreign_keys") {
		pre = body[:1]
		body = body[1:]
	}
	if len(body) > 0 && strings.HasPrefix(body[len(body)-1].Cmd, "PRAGMA foreign_keys") {
		post = body[len(body)-1:]
		body = body[:len(body)-1]
	}
	for _, p := range pre {
		if _, err := c.Conn.Exec(p.Cmd); err != nil {
			return applied, err
		}
		applied = append(applied, p)
	}
	if tx {
		if _, err := c.Conn.Exec("BEGIN"); err != nil {
			return applied, err
		}
	}
	for _, ch := range body {
		if _, err := c.Conn.Exec(ch.Cmd); err != nil {
			if tx {
				c.Conn.Exec("ROLLBACK")
			}
			return applied, fmt.Errorf("%s", err)
		}
		applied = append(applied, ch)
	}
	if tx {
		if _, err := c.Conn.Exec("COMMIT"); err != nil {
			return applied, err
		}
	}
	for _, p := range post {
		if _, err := c.Conn.Exec(p.Cmd); err != nil {
			return applied, err
		}
		applied = append(applied, p)
	}
	return applied, nil
}

func runSchemaDiff(cmd *cobra.Command, f *schemaFlags) error {
	format := f.format
	tmpl, err := parseFormat("diff", format, "{{ sql . }}")
	if err != nil {
		return err
	}
	fromHCL, toHCL := isHCLURLs(f.from), isHCLURLs(f.to)
	if (fromHCL || toHCL) && f.devURL == "" {
		return errors.New("--dev-url cannot be empty")
	}
	from, _, err := loadState(f.from, f.devURL, true)
	if err != nil {
		return err
	}
	to, _, err := loadState(f.to, f.devURL, true)
	if err != nil {
		return err
	}
	if err := applyExclude(from, f.exclude); err != nil {
		return err
	}
	if err := applyExclude(to, f.exclude); err != nil {
		return err
	}
	fs, err := targetSchema(from, fromHCL)
	if err != nil {
		return err
	}
	ts, err := targetSchema(to, toHCL)
	if err != nil {
		return err
	}
	changes := sqlite.DiffSchemas(fs, ts)
	out := cmd.OutOrStdout()
	d := cmdlog.NewSchemaDiff(changes)
	if len(changes) == 0 && format == "" {
		fmt.Fprintln(out, "Schemas are synced, no changes to be made.")
		return nil
	}
	return tmpl.Execute(out, d)
}

func runSchemaClean(cmd *cobra.Command, f *schemaFlags) error {
	if f.dryRun {
		fmt.Fprint(cmd.ErrOrStderr(), "Abort: 'atlas schema clean --dry-run' is not supported by the community version.\n\nTo install the non-community version of Atlas, use the following command:\n\n\tcurl -sSf https://atlasgo.sh | sh\n\nOr, visit the website to see all installation options:\n\n\thttps://atlasgo.io/docs#installation\n\n")
		return silentError{code: 1}
	}
	c, err := OpenClient(f.url)
	if err != nil {
		return err
	}
	defer c.Close()
	res, err := sqlite.InspectRealm(c.Conn)
	if err != nil {
		return err
	}
	cur := res.Realm.Schemas[0]
	var changes []schema.Change
	for _, t := range cur.Tables {
		changes = append(changes, &schema.DropTable{T: t})
	}
	out := cmd.OutOrStdout()
	if len(changes) == 0 {
		fmt.Fprintln(out, "Nothing to drop")
		return nil
	}
	plan, err := sqlite.PlanChanges(changes, "  ")
	if err != nil {
		return err
	}
	fmt.Fprintln(out, "-- Planned Changes:")
	fmt.Fprint(out, planOutput(plan))
	if !f.autoApprove {
		ok, err := promptApply(out)
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	_, err = execPlan(c, plan, "file")
	return err
}
