	if f.dryRun {
		fmt.Fprint(cmd.ErrOrStderr(), "Abort: 'atlas schema clean --dry-run' is not supported by the community version.\n\nTo install the non-community version of Atlas, use the following command:\n\n\tcurl -sSf https://atlasgo.sh | sh\n\nOr, visit the website to see all installation options:\n\n\thttps://atlasgo.io/docs#installation\n\n")
		return silentError{code: 1}
	}
	c, err := OpenClient(f.url)
	if err != nil {
		return err
	}
	defer c.Close()
	res, err := sqlite.InspectRealm(c.Conn)
	if err != nil {
		return err
	}
	cur := res.Realm.Schemas[0]
	var changes []schema.Change
	for _, t := range cur.Tables {
		changes = append(changes, &schema.DropTable{T: t})
	}
	out := cmd.OutOrStdout()
	if len(changes) == 0 {
		fmt.Fprintln(out, "Nothing to drop")
		return nil
	}
	plan, err := sqlite.PlanChanges(changes, "  ")
	if err != nil {
		return err
	}
	fmt.Fprintln(out, "-- Planned Changes:")
	fmt.Fprint(out, planOutput(plan))
	if !f.autoApprove {
		ok, err := promptApply(out)
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	_, err = execPlan(c, plan, "file")
	return err
}
