type Changes struct {
	Applied []string `json:"Applied,omitempty"`
	Pending []string `json:"Pending,omitempty"`
	Error   *StmtError `json:"Error,omitempty"`
}

// StmtError is a statement execution error.
type StmtError struct {
	Stmt string `json:"Stmt,omitempty"`
	Text string `json:"Text,omitempty"`
}

// SchemaApply is the payload of 'schema apply'.
type SchemaApply struct {
	*Env
	Changes Changes `json:"Changes,omitempty"`
	Error   string  `json:"Error,omitempty"`
}

// NewSchemaApply creates the payload.
func NewSchemaApply(u *url.URL, plan *sqlite.Plan, applied []*sqlite.PlanChange, execErr error) *SchemaApply {
	a := &SchemaApply{Env: &Env{Driver: "sqlite", URL: &URL{URL: *u, Schema: "main"}}}
	if applied == nil {
		for _, c := range plan.Changes {
			a.Changes.Pending = append(a.Changes.Pending, c.Cmd)
		}
	} else {
		for _, c := range applied {
			a.Changes.Applied = append(a.Changes.Applied, c.Cmd)
		}
		if len(applied) < len(plan.Changes) {
			for _, c := range plan.Changes[len(applied)+1:] {
				a.Changes.Pending = append(a.Changes.Pending, c.Cmd)
			}
		}
	}
	if execErr != nil {
		a.Error = execErr.Error()
		if len(applied) < len(plan.Changes) {
			a.Changes.Error = &StmtError{Stmt: plan.Changes[len(applied)].Cmd, Text: execErr.Error()}
		}
	}
	return a
}

// SchemaDiff is the payload of 'schema diff'.
