#!/usr/bin/env python3
"""Run many comparison cases. Each case: (name, setup_files dict, setup_cmds, cmd)."""
import subprocess, sys, os, tempfile, shutil, re, json, difflib

ORIG = '/workspace/executable'
MINE = '/tmp/myatlas'

def norm(s, d):
    s = s.replace(d, '<DIR>')
    s = re.sub(r'\d+(\.\d+)?(ms|µs|s|ns|m)\b', '<DUR>', s)
    s = re.sub(r'-?\d+h\d+m[\d.]+s', '<DUR>', s)
    s = re.sub(r'20\d{12}', '<TS>', s)
    return s

def run(binary, files, setup, cmd):
    d = tempfile.mkdtemp(prefix='rc')
    home = tempfile.mkdtemp(prefix='home')
    os.makedirs(home + '/.atlas')
    open(home + '/.atlas/community_error.json', 'w').write('{"last_suggested":"2099-01-01T00:00:00Z"}')
    open(home + '/.atlas/local-community.json', 'w').write('{"v1.us":"2099-01-01T00:00:00Z"}')
    for name, content in files.items():
        p = os.path.join(d, name)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        open(p, 'w').write(content)
    env = dict(os.environ, HOME=home)
    for s in setup:
        if s.startswith('sql:'):
            db, script = s[4:].split(':', 1)
            import sqlite3
            c = sqlite3.connect(os.path.join(d, db)); c.executescript(script); c.commit(); c.close()
        else:
            subprocess.run(s.replace('ATLAS', ORIG), shell=True, cwd=d, env=env, capture_output=True)
    p = subprocess.run(cmd.replace('ATLAS', binary), shell=True, cwd=d, env=env, capture_output=True, timeout=60)
    out = norm(p.stdout.decode(errors='replace'), d)
    err = norm(p.stderr.decode(errors='replace'), d)
    # collect files
    tree = {}
    for root, dirs, fs in os.walk(d):
        for f in fs:
            rel = os.path.relpath(os.path.join(root, f), d)
            if rel.endswith('.db'):
                # dump schema
                import sqlite3
                try:
                    c = sqlite3.connect(os.path.join(root, f))
                    tree[rel] = repr(c.execute("select type, name, tbl_name, sql from sqlite_master where name != 'atlas_schema_revisions' order by name").fetchall())
                    try:
                        tree[rel] += repr(c.execute("select version, description, type, applied, total, error, error_stmt, hash, operator_version from atlas_schema_revisions").fetchall())
                    except Exception: pass
                    c.close()
                except Exception as e:
                    tree[rel] = 'ERR ' + str(e)
            else:
                try: tree[re.sub(r'20\d{12}', '<TS>', rel)] = norm(open(os.path.join(root, f), errors='replace').read(), d)
                except Exception as e: tree[rel] = str(e)
    shutil.rmtree(d, ignore_errors=True); shutil.rmtree(home, ignore_errors=True)
    return out, err, p.returncode, tree

def compare(case, verbose=False):
    name, files, setup, cmd = case
    o = run(ORIG, files, setup, cmd)
    m = run(MINE, files, setup, cmd)
    problems = []
    for label, a, b in [('stdout', o[0], m[0]), ('stderr', o[1], m[1])]:
        if a != b:
            problems.append(f'--- {label}\n' + '\n'.join(difflib.unified_diff(a.splitlines(), b.splitlines(), 'orig', 'mine', lineterm='')))
    if o[2] != m[2]:
        problems.append(f'--- rc orig={o[2]} mine={m[2]}')
    t1 = {k: v for k, v in o[3].items() if not k.endswith('atlas.sum')}
    t2 = {k: v for k, v in m[3].items() if not k.endswith('atlas.sum')}
    if set(t1) != set(t2):
        problems.append(f'--- files differ: {sorted(set(t1) ^ set(t2))}')
    for k in sorted(set(t1) & set(t2)):
        if t1[k] != t2[k]:
            problems.append(f'--- file {k}\n orig: {t1[k][:1500]}\n mine: {t2[k][:1500]}')
    if problems:
        print(f'FAIL {name}: {cmd}')
        for p in problems: print(p)
        if verbose: print('orig stdout:', o[0]); print('orig stderr:', o[1])
        return False
    if verbose:
        print(f'OK {name}'); print(o[0]); print(o[1])
    return True

if __name__ == '__main__':
    import importlib.util
    spec = importlib.util.spec_from_file_location('cases', sys.argv[1])
    mod = importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
    only = sys.argv[2] if len(sys.argv) > 2 else None
    ok = fail = 0
    for c in mod.CASES:
        if only and only not in c[0]: continue
        if compare(c, verbose=bool(only)): ok += 1
        else: fail += 1
    print(f'{ok} ok, {fail} failed')
EOF
