{"command":"cd /workspace/internal/cmdlog && cat > migrate.go <<'EOF'
package cmdlog

import (
	"encoding/json"
	"time"
)

// File is a migration file reference.
type File struct {
	Name        string
	Version     string
	Description string
}

// MarshalJSON implements json.Marshaler.
func (f File) MarshalJSON() ([]byte, error) {
	type T struct {
		Name        string `json:"Name,omitempty"`
		Version     string `json:"Version,omitempty"`
		Description string `json:"Description,omitempty"`
	}
	return json.Marshal(T{f.Name, f.Version, f.Description})
}

// AppliedFile is a file applied by 'migrate apply'.
type AppliedFile struct {
	File
	Start   time.Time
	End     time.Time
	Skipped int        `json:"Skipped,omitempty"`
	Applied []string   `json:"Applied,omitempty"`
	Error   *StmtError `json:"Error,omitempty"`
}

// MarshalJSON implements json.Marshaler.
func (a *AppliedFile) MarshalJSON() ([]byte, error) {
	type T struct {
		Name        string     `json:"Name,omitempty"`
		Version     string     `json:"Version,omitempty"`
		Description string     `json:"Description,omitempty"`
		Start       time.Time  `json:"Start"`
		End         time.Time  `json:"End"`
		Skipped     int        `json:"Skipped,omitempty"`
		Applied     []string   `json:"Applied,omitempty"`
		Error       *StmtError `json:"Error,omitempty"`
	}
	return json.Marshal(T{a.Name, a.Version, a.Description, a.Start, a.End, a.Skipped, a.Applied, a.Error})
}

// MigrateApply is the payload of 'migrate apply'.
type MigrateApply struct {
	*Env
	Dir     string         `json:"Dir,omitempty"`
	Pending []File         `json:"Pending,omitempty"`
	Applied []*AppliedFile `json:"Applied,omitempty"`
