	}
	if f.url == "" {
		return errors.New("sql/sqlclient: missing driver. See: https://atlasgo.io/url")
	}
	c, err := OpenClient(f.url)
	if err != nil {
		return err
	}
	defer c.Close()
	if err := revisionsSchemaCheck(f.revSchema); err != nil {
		return err
	}
