		return err
	}
	var revs []*Revision
	exists, err := revisionsExist(c.Conn)
	if err != nil {
		return err
	}
	if exists {
		if revs, err = readRevisions(c.Conn); err != nil {
			return err
		}
		if len(revs) == 0 {
			if err := dbCleanCheck(c.Conn); err != nil {
				return err
			}
		}
	}
	files, err := d.Files()
	if err != nil {
		return err
	}
	applied := map[string]*Revision{}
	var last *Revision
	for _, r := range revs {
		applied[r.Version] = r
		if last == nil || r.Version > last.Version {
			last = r
		}
	}
	st := &cmdlog.MigrateStatus{Env: cmdlog.StatusEnv{Driver: "sqlite", URL: &cmdlog.URL{URL: *c.URL, Schema: "main"}, Dir: dirWithFormat(f.dir)}}
	var pending []*migrate.File
	executed := 0
	for _, fl := range files {
		st.Available = append(st.Available, toCmdFile(fl))
		if r, ok := applied[fl.Version()]; ok {
			executed++
			if r.Applied < r.Total && r.Type&revTypeResolved == 0 {
				pending = append(pending, fl)
			}
			continue
		}
		if last != nil && fl.Version() < last.Version {
			continue
		}
		pending = append(pending, fl)
	}
	for _, r := range revs {
		cr := &cmdlog.Revision{Version: r.Version, Description: r.Description, Type: revTypeName(r.Type), Applied: int(r.Applied), Total: int(r.Total), ExecutionTime: r.ExecutionTime, Error: r.Error, ErrorStmt: r.ErrorStmt, OperatorVersion: r.OperatorVersion}
