			cr.ExecutedAt = t
		}
		st.Applied = append(st.Applied, cr)
	}
	for _, fl := range pending {
		st.Pending = append(st.Pending, toCmdFile(fl))
	}
	st.Status = "OK"
	if len(pending) > 0 {
		st.Status = "PENDING"
	}
	cur, next := "No migration applied yet", "Already at latest version"
	partial := last != nil && last.Applied < last.Total && last.Type&revTypeResolved == 0
	if last != nil {
		st.Current = last.Version
		cur = last.Version
	}
	if len(pending) > 0 {
		st.Next = pending[0].Version()
		next = pending[0].Version()
	}
	execStr := strconv.Itoa(executed)
	if partial {
		st.Count = int(last.Applied)
		st.Total = int(last.Total)
		cur = fmt.Sprintf("%s (%d statements applied)", last.Version, last.Applied)
		next = fmt.Sprintf("%s (%d statements left)", next, last.Total-last.Applied)
		execStr += " (last one partially)"
	}
	if last != nil && last.Error != "" {
		st.Error = last.Error
		st.SQL = last.ErrorStmt
	}
	out := cmd.OutOrStdout()
	if tmpl != nil {
		return tmpl.Execute(out, st)
	}
	fmt.Fprintf(out, "Migration Status: %s\\n", st.Status)
	fmt.Fprintf(out, "  -- Current Version: %s\\n", cur)
	fmt.Fprintf(out, "  -- Next Version:    %s\\n", next)
	fmt.Fprintf(out, "  -- Executed Files:  %s\\n", execStr)
	fmt.Fprintf(out, "  -- Pending Files:   %d\\n", len(pending))
	if st.Error != "" {
		fmt.Fprintf(out, "\\nLast migration attempt had errors:\\n")
		fmt.Fprintf(out, "  -- SQL:   %s\\n", st.SQL)
		fmt.Fprintf(out, "  -- ERROR: %s\\n", st.Error)
	}
	return nil
}

func dirWithFormat(raw string) string {
	u, err := parseURL(raw)
	if err != nil {
		return raw
	}
	q := u.Query()
	if q.Get("format") == "" {
		q.Set("format", "atlas")
	}
	u.RawQuery = q.Encode()
	return u.String()
}

