			}
			return fmt.Errorf("invalid amount argument %q (%s). Omit the argument or pass a valid integer instead", args[0], reason)
		}
		if n == 0 {
			return fmt.Errorf("cannot apply '0' migration files")
		}
		amount = int(n)
	}
	if f.url == "" {
		return errors.New("required flag \\"url\\" not set")
	}
	switch f.execOrder {
	case "linear", "linear-skip", "non-linear":
	default:
		return fmt.Errorf("unknown execution order: %q", f.execOrder)
	}
	c, err := OpenClient(f.url)
	if err != nil {
		return err
	}
	defer c.Close()
	if err := revisionsSchemaCheck(f.revSchema); err != nil {
		return err
	}
	if err := c.Connect(); err != nil {
		return err
	}
	unlock, err := lockFile(f.lockTimeout)
	if err != nil {
		return err
	}
	defer unlock()
	if err := ensureRevisions(c.Conn); err != nil {
		return err
	}
	revs, err := readRevisions(c.Conn)
	if err != nil {
		return err
	}
	files, err := d.Files()
	if err != nil {
		return err
	}
	hashes := fileHashes(files)
	if len(revs) == 0 {
		if f.baseline != "" {
			var bf *migrate.File
			for _, fl := range files {
				if fl.Version() == f.baseline {
					bf = fl
				}
			}
			if bf == nil {
				return fmt.Errorf("baseline version %q not found", f.baseline)
			}
			rev := &Revision{Version: bf.Version(), Description: bf.Desc(), Type: revTypeBaseline, ExecutedAt: time.Now().Format(timeFormat), OperatorVersion: operatorVersion}
			if !f.dryRun {
				if err := writeRevision(c.Conn, rev, nil); err != nil {
					return err
				}
			}
			revs = append(revs, rev)
		} else if !f.allowDirty {
			if err := dbCleanCheck(c.Conn); err != nil {
				return err
			}
		}
	}
	applied := map[string]*Revision{}
	var lastApplied string
	for _, r := range revs {
		applied[r.Version] = r
		if r.Version > lastApplied {
			lastApplied = r.Version
		}
	}
	var pending []*migrate.File
	for _, fl := range files {
		if r, ok := applied[fl.Version()]; ok && (r.Type&revTypeBaseline != 0 || r.Type&revTypeResolved != 0 || r.Applied >= r.Total) {
			continue
		}
		if r, ok := applied[fl.Version()]; !ok || r.Applied >= r.Total {
			if f.baseline != "" && fl.Version() <= f.baseline && len(revs) == 1 && revs[0].Type == revTypeBaseline {
				continue
			}
			if f.execOrder == "linear" {
				if lastApplied != "" && fl.Version() < lastApplied {
					continue
				}
			}
		}
		pending = append(pending, fl)
	}
	if amount > 0 && amount < len(pending) {
		pending = pending[:amount]
	}
	out := cmd.OutOrStdout()
	text := out
	if tmpl != nil {
		text = io.Discard
	}
	if len(pending) == 0 {
		if tmpl == nil {
			fmt.Fprintln(out, "No migration files to execute")
			return nil
		}
		return tmpl.Execute(out, &cmdlog.MigrateApply{Env: &cmdlog.Env{Driver: "sqlite", URL: &cmdlog.URL{URL: *c.URL, Schema: "main"}}, Dir: f.dir, Current: lastApplied, Start: time.Now(), End: time.Now()})
	}
	start := time.Now()
	target := pending[len(pending)-1].Version()
	payload := &cmdlog.MigrateApply{Env: &cmdlog.Env{Driver: "sqlite", URL: &cmdlog.URL{URL: *c.URL, Schema: "main"}}, Dir: f.dir, Current: lastApplied, Target: target, Start: start}
	for _, fl := range pending {
		payload.Pending = append(payload.Pending, toCmdFile(fl))
	}
	if lastApplied != "" {
		fmt.Fprintf(text, "Migrating to version %s from %s (%d migrations in total):\\n\\n", target, lastApplied, len(pending))
	} else {
		fmt.Fprintf(text, "Migrating to version %s (%d migrations in total):\\n\\n", target, len(pending))
	}
	switch f.txMode {
	case "file", "none", "all":
	default:
		fmt.Fprintf(text, "    unknown tx-mode %q\\n\\n", f.txMode)
		fmt.Fprintf(text, "  -------------------------\\n  -- %s\\n", time.Duration(-1<<63))
		return fmt.Errorf("unknown tx-mode %q", f.txMode)
	}
	var (
		okFiles, errFiles int
		okStmts, errStmts int
		execErr           error
	)
	if f.txMode == "all" && !f.dryRun {
		if _, err := c.Conn.Exec("BEGIN"); err != nil {
			return err
		}
	}
	for _, fl := range pending {
		fmt.Fprintf(text, "  -- migrating version %s\\n", fl.Version())
		stmts, err := migrate.Stmts(string(fl.Bytes))
		if err != nil {
			return err
		}
		skip := 0
		if r, ok := applied[fl.Version()]; ok && r.Applied < r.Total {
			skip = int(r.Applied)
		}
		fstart := time.Now()
		af := &cmdlog.AppliedFile{File: toCmdFile(fl), Start: fstart, Skipped: skip}
		payload.Applied = append(payload.Applied, af)
		if f.txMode == "file" && !f.dryRun {
			if _, err := c.Conn.Exec("BEGIN"); err != nil {
				return err
			}
		}
		var failed error
		var failedStmt string
		n := skip
		for _, s := range stmts[skip:] {
			fmt.Fprintf(text, "    -> %s\\n", indentStmt(s.Text))
			af.Applied = append(af.Applied, s.Text)
			if f.dryRun {
				n++
				continue
			}
			if _, err := c.Conn.Exec(s.Text); err != nil {
				failed = err
				failedStmt = s.Text
				break
			}
			n++
		}
		okStmts += n - skip
		af.End = time.Now()
		if failed != nil {
			errStmts++
			errFiles++
			af.Error = &cmdlog.StmtError{Stmt: failedStmt, Text: failed.Error()}
			fmt.Fprintf(text, "    %s\\n\\n", failed)
			if f.txMode == "file" || f.txMode == "all" {
				c.Conn.Exec("ROLLBACK")
			} else {
				rev := &Revision{Version: fl.Version(), Description: fl.Desc(), Type: revTypeExecute, Applied: int64(n), Total: int64(len(stmts)), ExecutedAt: fstart.Format(timeFormat), ExecutionTime: int64(time.Since(fstart)), Error: failed.Error(), ErrorStmt: failedStmt, Hash: hashes[fl.Name], OperatorVersion: operatorVersion}
				writeRevision(c.Conn, rev, partialHashes(stmts, n))
			}
			execErr = fmt.Errorf("sql/migrate: executing statement %q from version %q: %s", failedStmt, fl.Version(), failed)
			break
		}
		if !f.dryRun {
			rev := &Revision{Version: fl.Version(), Description: fl.Desc(), Type: revTypeExecute, Applied: int64(n), Total: int64(len(stmts)), ExecutedAt: fstart.Format(timeFormat), ExecutionTime: int64(time.Since(fstart)), Hash: hashes[fl.Name], OperatorVersion: operatorVersion}
			if err := writeRevision(c.Conn, rev, nil); err != nil {
				return err
			}
			if f.txMode == "file" {
				if _, err := c.Conn.Exec("COMMIT"); err != nil {
					return err
				}
			}
		}
		okFiles++
		fmt.Fprintf(text, "  -- ok (%s)\\n\\n", time.Since(fstart))
	}
	if f.txMode == "all" && !f.dryRun {
		if execErr != nil {
			c.Conn.Exec("ROLLBACK")
		} else if _, err := c.Conn.Exec("COMMIT"); err != nil {
			return err
		}
	}
	payload.End = time.Now()
	fmt.Fprintf(text, "  -------------------------\\n")
	fmt.Fprintf(text, "  -- %s\\n", time.Since(start))
	if execErr != nil {
		payload.Error = execErr.Error()
		switch {
		case okFiles > 0:
			fmt.Fprintf(text, "  -- %s ok, %d with errors\\n", plural(okFiles, "migration"), errFiles)
		default:
			fmt.Fprintf(text, "  -- %d migration with errors\\n", errFiles)
		}
		if okStmts > 0 {
			fmt.Fprintf(text, "  -- %s ok, %d with errors\\n", plural(okStmts, "sql statement"), errStmts)
		} else {
			fmt.Fprintf(text, "  -- %d sql statement with errors\\n", errStmts)
		}
	} else {
		payload.Message = fmt.Sprintf("Migrated to version %s from %s (%d migrations in total)", target, lastApplied, len(pending))
		fmt.Fprintf(text, "  -- %s\\n", plural(okFiles, "migration"))
		fmt.Fprintf(text, "  -- %s\\n", plural(okStmts, "sql statement"))
	}
	if tmpl != nil {
		if err := tmpl.Execute(out, payload); err != nil {
			return err
		}
	}
	return execErr
}

