func revisionsExist(c *sqlite.Conn) (bool, error) {
	rows, err := c.Query("SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?", revTable)
	if err != nil {
		return false, err
	}
	return len(rows.Values) > 0, nil
}

func runMigrateStatus(cmd *cobra.Command, f *migrateFlags) error {
	format := f.format
	if f.logFormat != "" {
		format = f.logFormat
	}
	var tmpl *template.Template
	if format != "" {
		t, err := template.New("format").Funcs(cmdlog.ApplyFuncs).Parse(format)
		if err != nil {
			return fmt.Errorf("parse format: %w", err)
		}
		tmpl = t
	}
	d, err := openMigrateDir(f.dir, f.dirFormat, false)
	if err != nil {
		return err
	}
	if err := validateDir(cmd, d); err != nil {
		return err
	}
	if f.url == "" {
		return errors.New("sql/sqlclient: missing driver. See: https://atlasgo.io/url")
	}
	c, err := OpenClient(f.url)
	if err != nil {
		return err
	}
	defer c.Close()
	if err := revisionsSchemaCheck(f.revSchema); err != nil {
		return err
	}
	if err := c.Connect(); err != nil {
		return err
	}
	var revs []*Revision
	exists, err := revisionsExist(c.Conn)
	if err != nil {
		return err
	}
	if exists {
		if revs, err = readRevisions(c.Conn); err != nil {
			return err
		}
		if len(revs) == 0 {
			if err := dbCleanCheck(c.Conn); err != nil {
				return err
			}
		}
	}
	files, err := d.Files()
	if err != nil {
		return err
	}
	applied := map[string]*Revision{}
	var last *Revision
	for _, r := range revs {
		applied[r.Version] = r
		if last == nil || r.Version > last.Version {
			last = r
		}
	}
	st := &cmdlog.MigrateStatus{Env: cmdlog.StatusEnv{Driver: "sqlite", URL: &cmdlog.URL{URL: *c.URL, Schema: "main"}, Dir: dirWithFormat(f.dir)}}
	var pending []*migrate.File
	executed := 0
	for _, fl := range files {
		st.Available = append(st.Available, toCmdFile(fl))
		if r, ok := applied[fl.Version()]; ok {
			executed++
			if r.Applied < r.Total && r.Type&revTypeResolved == 0 {
				pending = append(pending, fl)
			}
			continue
		}
		if last != nil && fl.Version() < last.Version {
			continue
		}
		pending = append(pending, fl)
	}
	for _, r := range revs {
		cr := &cmdlog.Revision{Version: r.Version, Description: r.Description, Type: revTypeName(r.Type), Applied: int(r.Applied), Total: int(r.Total), ExecutionTime: r.ExecutionTime, Error: r.Error, ErrorStmt: r.ErrorStmt, OperatorVersion: r.OperatorVersion}
		if t, err := time.Parse(timeFormat, r.ExecutedAt); err == nil {
			cr.ExecutedAt = t
		}
		st.Applied = append(st.Applied, cr)
	}
	for _, fl := range pending {
		st.Pending = append(st.Pending, toCmdFile(fl))
	}
	st.Status = "OK"
	if len(pending) > 0 {
		st.Status = "PENDING"
	}
	cur, next := "No migration applied yet", "Already at latest version"
	partial := last != nil && last.Applied < last.Total && last.Type&revTypeResolved == 0
	if last != nil {
		st.Current = last.Version
		cur = last.Version
	}
	if len(pending) > 0 {
		st.Next = pending[0].Version()
		next = pending[0].Version()
	}
	execStr := strconv.Itoa(executed)
	if partial {
		st.Count = int(last.Applied)
		st.Total = int(last.Total)
		cur = fmt.Sprintf("%s (%d statements applied)", last.Version, last.Applied)
		next = fmt.Sprintf("%s (%d statements left)", next, last.Total-last.Applied)
		execStr += " (last one partially)"
	}
	if last != nil && last.Error != "" {
		st.Error = last.Error
		st.SQL = last.ErrorStmt
	}
	out := cmd.OutOrStdout()
	if tmpl != nil {
		return tmpl.Execute(out, st)
	}
	fmt.Fprintf(out, "Migration Status: %s\\n", st.Status)
	fmt.Fprintf(out, "  -- Current Version: %s\\n", cur)
	fmt.Fprintf(out, "  -- Next Version:    %s\\n", next)
	fmt.Fprintf(out, "  -- Executed Files:  %s\\n", execStr)
	fmt.Fprintf(out, "  -- Pending Files:   %d\\n", len(pending))
	if st.Error != "" {
		fmt.Fprintf(out, "\\nLast migration attempt had errors:\\n")
		fmt.Fprintf(out, "  -- SQL:   %s\\n", st.SQL)
		fmt.Fprintf(out, "  -- ERROR: %s\\n", st.Error)
	}
	return nil
}

func dirWithFormat(raw string) string {
	u, err := parseURL(raw)
	if err != nil {
		return raw
	}
	q := u.Query()
	if q.Get("format") == "" {
		q.Set("format", "atlas")
	}
	u.RawQuery = q.Encode()
	return u.String()
}

