								dataDep = append(dataDep, &lintDiag{pos: s.Pos, text: fmt.Sprintf("Modifying nullable column %q to non-nullable might fail in case it contains NULL values", mc.To.Name), code: "MF104"})
							}
						}
					}
				}
			}
			cur = next
		}
		var b strings.Builder
		fmt.Fprintf(&b, "  -- analyzing version %s\n", fl.Version())
		content := string(fl.Bytes)
		writeDiags := func(title string, ds []*lintDiag) {
			fmt.Fprintf(&b, "    -- %s:\n", title)
			for _, dg := range ds {
				text := fmt.Sprintf("L%d: %s https://atlasgo.io/lint/analyzers#%s", lineOf(content, dg.pos), dg.text, dg.code)
				fmt.Fprintf(&b, "      -- %s\n", wrapText(text, "         "))
			}
		}
		if len(destructive) == 0 && len(dataDep) == 0 {
			b.WriteString("    -- no diagnostics found\n")
		}
		if len(destructive) > 0 {
			writeDiags("destructive changes detected", destructive)
		}
		if len(dataDep) > 0 {
			writeDiags("data dependent changes detected", dataDep)
		}
		var fixes []string
		for _, dg := range append(append([]*lintDiag{}, destructive...), dataDep...) {
			if dg.fix != "" {
				fixes = append(fixes, dg.fix)
			}
		}
		if len(fixes) > 0 {
			if len(fixes) == 1 {
				b.WriteString("    -- suggested fix:\n")
			} else {
				b.WriteString("    -- suggested fixes:\n")
			}
			for _, fx := range fixes {
				fmt.Fprintf(&b, "      -> %s\n", wrapText(fx, "         "))
			}
		}
		fmt.Fprintf(&b, "  -- ok (%s)\n\n", time.Since(fstart))
		perFile = append(perFile, b.String())
		totalDiags += len(destructive) + len(dataDep)
		switch {
		case len(destructive) > 0:
			errCount++
		case len(dataDep) > 0:
			warnCount++
		default:
			okCount++
		}
	}
	fmt.Fprint(out, strings.Join(perFile, ""))
	fmt.Fprintf(out, "  -------------------------\n")
	fmt.Fprintf(out, "  -- %s\n", time.Since(start))
	var parts []string
	if okCount > 0 {
		parts = append(parts, plural2(okCount, "version")+" ok")
	}
	if warnCount > 0 {
		if len(parts) == 0 {
			parts = append(parts, plural2(warnCount, "version")+" with warnings")
		} else {
			parts = append(parts, fmt.Sprintf("%d with warnings", warnCount))
		}
	}
	if errCount > 0 {
		if len(parts) == 0 {
			parts = append(parts, plural2(errCount, "version")+" with errors")
		} else {
			parts = append(parts, fmt.Sprintf("%d with errors", errCount))
		}
	}
	fmt.Fprintf(out, "  -- %s\n", strings.Join(parts, ", "))
	fmt.Fprintf(out, "  -- %s\n", plural2(totalChanges, "schema change"))
	if totalDiags > 0 {
		fmt.Fprintf(out, "  -- %s\n", plural2(totalDiags, "diagnostic"))
	}
	if errCount > 0 {
		return silentError{code: 1}
	}
	return nil
}

