func importFiles(dir, format string) ([]*migrate.File, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var out []*migrate.File
	var lastVersion string
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".sql") {
			continue
		}
		b, err := os.ReadFile(filepath.Join(dir, e.Name()))
		if err != nil {
			return nil, err
		}
		name := e.Name()
		content := string(b)
		switch format {
		case "golang-migrate":
			if !strings.HasSuffix(name, ".up.sql") {
				continue
			}
			base := strings.TrimSuffix(name, ".up.sql")
			if strings.Contains(base, "_") {
				name = base + ".sql"
			}
		case "goose":
			content = section(content, "-- +goose Up", "-- +goose Down")
		case "dbmate":
			content = section(content, "-- migrate:up", "-- migrate:down")
		case "flyway":
			switch {
			case strings.HasPrefix(name, "V"):
				base := strings.TrimSuffix(name[1:], ".sql")
				parts := strings.SplitN(base, "__", 2)
				lastVersion = parts[0]
				if len(parts) == 2 {
					name = parts[0] + "_" + parts[1] + ".sql"
				} else {
					name = parts[0] + ".sql"
				}
			case strings.HasPrefix(name, "R__"):
				name = lastVersion + "R_" + strings.TrimPrefix(name, "R__")
			default:
				continue
			}
		}
		text, err := importStmts(content)
		if err != nil {
			return nil, err
		}
		out = append(out, &migrate.File{Name: name, Bytes: []byte(text)})
	}
	if format == "flyway" {
		for _, f := range out {
			if strings.HasPrefix(f.Name, "R_") {
				f.Name = lastVersion + f.Name
			}
		}
	}
	return out, nil
}
