				parts := strings.SplitN(base, "__", 2)
				lastVersion = parts[0]
				if len(parts) == 2 {
					name = parts[0] + "_" + parts[1] + ".sql"
				} else {
					name = parts[0] + ".sql"
				}
			case strings.HasPrefix(name, "R__"):
				name = lastVersion + "R_" + strings.TrimPrefix(name, "R__")
