// writeFormatted writes a migration file in the directory format.
func writeFormatted(d *migrate.Dir, ts, name, desc string, plan *sqlite.Plan) error {
	var up, down strings.Builder
	if plan != nil {
		for _, c := range plan.Changes {
			fmt.Fprintf(&up, "-- %s\\n%s;\\n", c.Comment, c.Cmd)
		}
		for i := len(plan.Changes) - 1; i >= 0; i-- {
			c := plan.Changes[i]
			if c.Reverse != "" {
				fmt.Fprintf(&down, "-- reverse: %s\\n%s;\\n", c.Comment, c.Reverse)
			}
		}
	}
	switch d.Format {
	case "golang-migrate":
		if err := d.WriteFile(name+".up.sql", []byte(up.String())); err != nil {
			return err
		}
		return d.WriteFile(name+".down.sql", []byte(down.String()))
	case "goose":
		return d.WriteFile(name+".sql", []byte("-- +goose Up\\n"+up.String()+"\\n-- +goose Down\\n"+down.String()))
	case "dbmate":
		return d.WriteFile(name+".sql", []byte("-- migrate:up\\n"+up.String()+"\\n-- migrate:down\\n"+down.String()))
	case "flyway":
		fname := ts
		if desc != "" {
			fname += "__" + desc
		}
		if err := d.WriteFile("V"+fname+".sql", []byte(up.String())); err != nil {
			return err
		}
		return d.WriteFile("U"+fname+".sql", []byte(down.String()))
	case "liquibase":
		var b strings.Builder
		b.WriteString("--liquibase formatted sql")
		if plan != nil {
			for i, c := range plan.Changes {
				if i == 0 {
					b.WriteString("\\n")
				} else {
					b.WriteString("\\n\\n")
				}
				fmt.Fprintf(&b, "--changeset atlas:%s-%d\\n--comment: %s\\n%s;", ts, i+1, c.Comment, c.Cmd)
				if c.Reverse != "" {
					fmt.Fprintf(&b, "\\n--rollback: %s;", c.Reverse)
				}
			}
			b.WriteString("\\n")
		}
		return d.WriteFile(name+".sql", []byte(b.String()))
	}
	if plan == nil {
		return d.WriteFile(name+".sql", nil)
	}
	return d.WriteFile(name+".sql", []byte(cmdlog.PlanSQL(plan)))
}

