type lintStmt struct {
	pos     int
	changes []schema.Change
}

// collapseCopies detects the SQLite table-copy pattern (create new table,
// drop old table and rename the new one) and collapses it into a single
// ModifyTable change attributed to the statement creating the new table.
func collapseCopies(steps []*lintStmt) []*lintStmt {
	for ri, st := range steps {
		if len(st.changes) != 2 {
			continue
		}
		dt, ok1 := st.changes[0].(*schema.DropTable)
		at, ok2 := st.changes[1].(*schema.AddTable)
		if !ok1 || !ok2 || len(sqlite.TableDiff(renamed(dt.T, at.T.Name), at.T)) != 0 {
			continue
		}
		// Find the creation of the temporary table and the drop of the target.
		ci, di := -1, -1
		var oldT *schema.Table
		for i := 0; i < ri; i++ {
			for _, c := range steps[i].changes {
				switch c := c.(type) {
				case *schema.AddTable:
					if c.T.Name == dt.T.Name {
						ci = i
					}
				case *schema.DropTable:
					if c.T.Name == at.T.Name {
						di = i
						oldT = c.T
					}
				}
			}
		}
		if ci < 0 || di < 0 {
			continue
		}
		mod := &schema.ModifyTable{T: at.T, From: oldT, Changes: sqlite.TableDiff(oldT, at.T)}
		var out []*lintStmt
		for i, s2 := range steps {
			switch i {
			case ci:
				var cs []schema.Change
				for _, c := range s2.changes {
					if a, ok := c.(*schema.AddTable); ok && a.T.Name == dt.T.Name {
						cs = append(cs, mod)
						continue
					}
					cs = append(cs, c)
				}
				out = append(out, &lintStmt{pos: s2.pos, changes: cs})
			case di:
				var cs []schema.Change
				for _, c := range s2.changes {
					if d, ok := c.(*schema.DropTable); ok && d.T.Name == at.T.Name {
						continue
					}
					cs = append(cs, c)
				}
				out = append(out, &lintStmt{pos: s2.pos, changes: cs})
			case ri:
				out = append(out, &lintStmt{pos: s2.pos})
			default:
				out = append(out, s2)
			}
		}
		return collapseCopies(out)
	}
	return steps
}

func renamed(t *schema.Table, name string) *schema.Table {
	c := *t
	c.Name = name
	return &c
}

func joinNames(names []string) string {
	q := make([]string, len(names))
	for i, n := range names {
		q[i] = fmt.Sprintf("%q", n)
	}
	if len(q) == 1 {
		return q[0]
	}
	return strings.Join(q[:len(q)-1], ", ") + " and " + q[len(q)-1]
}

func analyzeSteps(steps []*lintStmt) (destructive, dataDep []*lintDiag) {
	created := map[string]bool{}
	for _, st := range steps {
		for _, c := range st.changes {
			switch c := c.(type) {
			case *schema.AddTable:
				created[c.T.Name] = true
			case *schema.DropTable:
				if !created[c.T.Name] {
					destructive = append(destructive, &lintDiag{pos: st.pos, text: fmt.Sprintf("Dropping table %q", c.T.Name), code: "DS102", fix: fmt.Sprintf("Add a pre-migration check to ensure table %q is empty before dropping it", c.T.Name)})
				}
			case *schema.ModifyTable:
				if created[c.T.Name] {
					continue
				}
				var dropped []string
				for _, mc := range c.Changes {
					if dc, ok := mc.(*schema.DropColumn); ok && (dc.C.Generated == nil || strings.EqualFold(dc.C.Generated.Type, "STORED")) {
						dropped = append(dropped, dc.C.Name)
					}
				}
				switch len(dropped) {
				case 0:
				case 1:
					destructive = append(destructive, &lintDiag{pos: st.pos, text: fmt.Sprintf("Dropping non-virtual column %q", dropped[0]), code: "DS103", fix: fmt.Sprintf("Add a pre-migration check to ensure column %q is NULL before dropping it", dropped[0])})
				default:
					destructive = append(destructive, &lintDiag{pos: st.pos, text: fmt.Sprintf("Dropping non-virtual columns %s", joinNames(dropped)), code: "DS103", fix: fmt.Sprintf("Add pre-migration checks to ensure columns %s are NULL before dropping them", joinNames(dropped))})
				}
				for _, mc := range c.Changes {
					switch mc := mc.(type) {
					case *schema.AddColumn:
						if !mc.C.Type.Null && mc.C.Default == nil && mc.C.Generated == nil {
							typ, _ := sqlite.FormatType(mc.C.Type.Type)
							dataDep = append(dataDep, &lintDiag{pos: st.pos, text: fmt.Sprintf("Adding a non-nullable %q column %q will fail in case table %q is not empty", typ, mc.C.Name, c.T.Name), code: "MF103"})
						}
					case *schema.AddIndex:
						if mc.I.Unique {
							var cols []*schema.Column
							for _, p := range mc.I.Parts {
								if p.C != nil {
									cols = append(cols, p.C)
								}
							}
							var text string
							if len(cols) == 1 {
								text = fmt.Sprintf("Adding a unique index %q on table %q might fail in case column %s contains duplicate entries", mc.I.Name, c.T.Name, quoteNames(cols))
							} else {
								text = fmt.Sprintf("Adding a unique index %q on table %q might fail in case columns %s contain duplicate entries", mc.I.Name, c.T.Name, quoteNames(cols))
							}
							dataDep = append(dataDep, &lintDiag{pos: st.pos, text: text, code: "MF101"})
						}
					case *schema.ModifyIndex:
						if mc.To.Unique && !mc.From.Unique {
							dataDep = append(dataDep, &lintDiag{pos: st.pos, text: fmt.Sprintf("Modifying an index %q on table %q to unique might fail in case of duplicate entries", mc.To.Name, c.T.Name), code: "MF102"})
						}
					case *schema.ModifyColumn:
						if mc.Change&schema.ChangeNull != 0 && !mc.To.Type.Null && mc.To.Default == nil {
							dataDep = append(dataDep, &lintDiag{pos: st.pos, text: fmt.Sprintf("Modifying nullable column %q to non-nullable might fail in case it contains NULL values", mc.To.Name), code: "MF104"})
						}
					}
				}
			}
		}
	}
	return destructive, dataDep
}
